              <p style={{ margin: '0 0 8px', fontSize: 12, fontWeight: 700 }}>Aspect Ratio</p>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, minmax(0, 1fr))', gap: 8 }}>
                {ASPECT_RATIOS.map((ratio) => {
                  const active = aspectRatio === ratio;
                  return (
                    <button key={ratio} type="button" onClick={() => setAspectRatio(ratio)} style={{ borderRadius: 12, border: active ? '1px solid rgba(255,255,255,0.25)' : '1px solid rgba(255,255,255,0.08)', background: active ? 'rgba(255,255,255,0.08)' : '#17181c', color: 'var(--text)', padding: '12px 8px', minHeight: 58, fontSize: 11, cursor: 'pointer' }}>{ratio}</button>
                  );
                })}
              </div>
            </div>

            <div style={{ borderTop: '1px solid rgba(255,255,255,0.08)', paddingTop: 10 }}>
              <button type="button" onClick={setRandomSeed} style={{ width: '100%', borderRadius: 12, border: '1px solid rgba(255,255,255,0.08)', background: '#17181c', color: 'var(--text)', padding: '8px 12px', cursor: 'pointer' }}>Advanced</button>
              <div style={{ marginTop: 8, display: 'grid', gap: 8 }}>
                <label style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 12 }}>
