                <input disabled={!seedEnabled} value={seedValue} onChange={(event) => setSeedValue(event.target.value.replace(/[^0-9]/g, '').slice(0, 12))} placeholder="Choose any number" style={{ width: '100%', padding: '8px 10px', borderRadius: 10, border: '1px solid rgba(255,255,255,0.08)', background: '#101115', color: 'var(--text)' }} />
              </div>
            </div>

            <div>
