                  </div>
                ) : referenceImages.length > 0 ? (
                  <div style={{ textAlign: 'center' }}>
                    <p style={{ margin: 0, fontSize: 13, fontWeight: 700 }}>Image Reference Ready</p>
                    <p style={{ margin: '6px 0 0', fontSize: 12, color: 'var(--muted)' }}>{referenceImages[0].name}</p>
                  </div>
                ) : (
                  <div style={{ textAlign: 'center' }}>
                    <p style={{ margin: 0, fontSize: 13, fontWeight: 700 }}>Video Preview</p>
                    <p style={{ margin: '6px 0 0', fontSize: 12, color: 'var(--muted)' }}>Upload references or generate to preview output here.</p>
                  </div>
