            </div>

            <div style={{ border: '1px solid rgba(255,255,255,0.08)', borderRadius: 14, padding: 14, background: '#17181c' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', gap: 10, alignItems: 'center' }}>
                <p style={{ margin: 0, fontSize: 12, fontWeight: 700 }}>Multi Reference Guide</p>
                <span style={{ borderRadius: 999, border: '1px solid rgba(255,255,255,0.08)', padding: '4px 8px', fontSize: 11, color: 'var(--muted)' }}>Full Guide</span>
              </div>
              <div style={{ marginTop: 10, border: '1px solid rgba(255,255,255,0.08)', borderRadius: 10, padding: 10, background: '#111318' }}>
                <p style={{ margin: 0, fontSize: 11, color: 'var(--muted)' }}>Prompt Guide</p>
                <p style={{ margin: '6px 0 0', fontSize: 12 }}>Type @ to quickly insert uploaded file refs inside the prompt. Supported: @Image1, @Video1, @Audio1.</p>
              </div>
              <div style={{ marginTop: 12, display: 'grid', gap: 10 }}>
                <div>
                  <p style={{ margin: 0, fontSize: 11, fontWeight: 700 }}>Material Limits</p>
                  <ul style={{ margin: '6px 0 0', paddingLeft: 18, fontSize: 12, color: 'var(--muted)' }}>
                    <li>Up to 9 reference images</li>
                    <li>Up to 3 reference videos, total duration 15 seconds</li>
                    <li>Up to 3 reference audios, total duration 15 seconds</li>
                    <li>Maximum 12 material slots across all types</li>
                  </ul>
                </div>
                <div>
                  <p style={{ margin: 0, fontSize: 11, fontWeight: 700 }}>Supported Input Combinations</p>
                  <ul style={{ margin: '6px 0 0', paddingLeft: 18, fontSize: 12, color: 'var(--muted)' }}>
                    <li>Text + Image</li>
                    <li>Text + Video</li>
                    <li>Text + Image + Video</li>
                    <li>Text + Image + Audio</li>
                    <li>Text + Video + Audio</li>
                    <li>Text + Image + Video + Audio</li>
                  </ul>
                  <p style={{ margin: '6px 0 0', fontSize: 11, color: 'var(--muted)' }}>Note: audio can be used alone with text, or combined with at least one image or video reference.</p>
                </div>
              </div>
            </div>

            <div style={{ border: '1px solid rgba(255,255,255,0.08)', borderRadius: 14, padding: 14, background: 'linear-gradient(180deg, rgba(15,20,48,0.88), rgba(9,12,28,0.96))' }}>
              <h4 style={{ margin: 0, textAlign: 'center', color: '#5ea0ff' }}>Get Inspired</h4>
              <p style={{ margin: '8px 0 0', textAlign: 'center', fontSize: 12, color: 'rgba(255,255,255,0.72)' }}>Explore multimodal video examples created with the current reference workflow.</p>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, minmax(0, 1fr))', gap: 10, marginTop: 12 }}>
                {['Brand reel', 'Angel motion', 'Promo shot', 'Ambient loop'].map((item) => (
                  <div key={item} style={{ borderRadius: 12, minHeight: 100, background: 'linear-gradient(135deg, rgba(255,255,255,0.14), rgba(255,255,255,0.04))', display: 'grid', placeItems: 'center', fontSize: 12, color: 'rgba(255,255,255,0.8)' }}>{item}</div>
                ))}
              </div>
            </div>
          </div>
        </div>
      ) : null}

      {!isVideoMode ? (
      <>
      <div style={{ display: 'grid', gridTemplateColumns: '1.1fr 1fr', gap: 14, marginTop: 16 }}>
        <div>
          <label style={{ display: 'block', fontSize: 12, fontWeight: 700, marginBottom: 6 }}>Creative Mode</label>
          <select
