          >
            {CREATIVE_MODES.map((mode) => (
              <option key={mode.value} value={mode.value}>
                {mode.label}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label style={{ display: 'block', fontSize: 12, fontWeight: 700, marginBottom: 6 }}>AI Model</label>
          <select value={model} onChange={(event) => setModel(event.target.value)} style={{ width: '100%', padding: '8px 10px', borderRadius: 8, border: '1px solid var(--line)' }}>
            {AI_MODELS.map((modelOption) => (
              <option key={modelOption} value={modelOption}>
                {modelOption}
              </option>
            ))}
          </select>
        </div>
      </div>

      <div style={{ marginTop: 12 }}>
        <label style={{ display: 'block', fontSize: 12, fontWeight: 700, marginBottom: 6 }}>
          Prompt Description ({promptDescription.length}/5000)
        </label>
        <textarea
          value={promptDescription}
          onChange={(event) => setPromptDescription(event.target.value.slice(0, 5000))}
          placeholder="Describe your creative output in detail..."
          rows={5}
          style={{ width: '100%', padding: 10, borderRadius: 8, border: '1px solid var(--line)', resize: 'vertical' }}
        />
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, minmax(160px, 1fr))', gap: 12, marginTop: 12 }}>
        <div>
          <label style={{ display: 'block', fontSize: 12, fontWeight: 700, marginBottom: 6 }}>Aspect Ratio</label>
          <select value={aspectRatio} onChange={(event) => setAspectRatio(event.target.value)} style={{ width: '100%', padding: '8px 10px', borderRadius: 8, border: '1px solid var(--line)' }}>
            {ASPECT_RATIOS.map((ratio) => (
              <option key={ratio} value={ratio}>
                {ratio}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label style={{ display: 'block', fontSize: 12, fontWeight: 700, marginBottom: 6 }}>Resolution</label>
          <select value={resolution} onChange={(event) => setResolution(event.target.value)} style={{ width: '100%', padding: '8px 10px', borderRadius: 8, border: '1px solid var(--line)' }}>
