          <input
            type="file"
            accept=".png,.jpg,.jpeg,.webp"
            multiple
            onChange={(event) => handleImageUpload(event.target.files)}
            style={{ marginTop: 8, width: '100%' }}
          />
        </div>

        <div style={{ border: '1px dashed var(--line)', borderRadius: 8, padding: 10 }}>
          <p style={{ margin: 0, fontSize: 12, fontWeight: 700 }}>Reference Videos</p>
          <p style={{ margin: '6px 0 0', fontSize: 12, color: 'var(--muted)' }}>
            Max 3, total 15s (mp4, mov) ({remainingVideoSlots} remaining)
          </p>
          <input type="file" accept=".mp4,.mov" multiple onChange={(event) => handleVideoUpload(event.target.files)} style={{ marginTop: 8, width: '100%' }} />
        </div>

        <div style={{ border: '1px dashed var(--line)', borderRadius: 8, padding: 10 }}>
          <p style={{ margin: 0, fontSize: 12, fontWeight: 700 }}>Reference Audios</p>
          <p style={{ margin: '6px 0 0', fontSize: 12, color: 'var(--muted)' }}>
            Max 3, total 15s (mp3, wav) ({remainingAudioSlots} remaining)
          </p>
          <input type="file" accept=".mp3,.wav" multiple onChange={(event) => handleAudioUpload(event.target.files)} style={{ marginTop: 8, width: '100%' }} />
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12, marginTop: 12 }}>
        <label style={{ display: 'flex', alignItems: 'center', gap: 8, border: '1px solid var(--line)', borderRadius: 8, padding: 10 }}>
          <input type="checkbox" checked={containsRealPeople} onChange={(event) => setContainsRealPeople(event.target.checked)} />
          <span style={{ fontSize: 13 }}>
            Contains Real People (specialized realistic-human generation pipeline)
          </span>
        </label>

        <label style={{ display: 'flex', alignItems: 'center', gap: 8, border: '1px solid var(--line)', borderRadius: 8, padding: 10 }}>
          <input type="checkbox" checked={returnLastFrame} onChange={(event) => setReturnLastFrame(event.target.checked)} />
          <span style={{ fontSize: 13 }}>
            Return Last Frame (for seamless continuation in next video task)
          </span>
        </label>
      </div>

      <div style={{ marginTop: 12, border: '1px solid var(--line)', borderRadius: 8, padding: 10 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', gap: 10, alignItems: 'center', flexWrap: 'wrap' }}>
          <p style={{ margin: 0, fontSize: 12, fontWeight: 700 }}>Advanced: Seed Control</p>
          <button
