            onClick={setRandomSeed}
            style={{ borderRadius: 8, border: '1px solid var(--line)', background: 'transparent', color: 'var(--text)', padding: '6px 10px', cursor: 'pointer' }}
          >
            Random Seed
          </button>
        </div>
        <div style={{ display: 'flex', gap: 8, marginTop: 8, alignItems: 'center' }}>
          <label style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            <input type="checkbox" checked={seedEnabled} onChange={(event) => setSeedEnabled(event.target.checked)} />
            Use Seed
          </label>
          <input
            disabled={!seedEnabled}
            value={seedValue}
            onChange={(event) => setSeedValue(event.target.value.replace(/[^0-9]/g, '').slice(0, 12))}
            placeholder="Choose any number"
            style={{ padding: '6px 10px', borderRadius: 8, border: '1px solid var(--line)', minWidth: 180 }}
          />
        </div>
      </div>

      <div style={{ marginTop: 12, border: '1px solid var(--line)', borderRadius: 8, padding: 10 }}>
        <p style={{ margin: 0, fontSize: 12, fontWeight: 700 }}>Edit Tools</p>
        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginTop: 8 }}>
          {EDIT_TOOLS.map((tool) => (
            <span key={tool} style={{ borderRadius: 999, border: '1px solid var(--line)', padding: '4px 10px', fontSize: 12 }}>
              {tool}
            </span>
          ))}
        </div>
      </div>

      <div style={{ marginTop: 12, border: '1px solid var(--line)', borderRadius: 8, padding: 10 }}>
        <p style={{ margin: 0, fontSize: 12, fontWeight: 700 }}>Enterprise Capability Stack</p>
        <ul style={{ margin: '8px 0 0', paddingLeft: 18 }}>
          {capabilityList().map((item) => (
            <li key={item} style={{ marginBottom: 4, fontSize: 13 }}>
              {item}
            </li>
          ))}
        </ul>
      </div>

      <div style={{ marginTop: 12, border: '1px solid #f59e0b55', borderRadius: 8, padding: 10, background: '#f59e0b12' }}>
        <p style={{ margin: 0, fontSize: 12, fontWeight: 700 }}>Public Figure / Celebrity Controls</p>
        <p style={{ margin: '6px 0 0', fontSize: 13 }}>
          Celebrity avatar or voice cloning is restricted by policy and rights checks. Use licensed likeness/voice profiles
          only after documented consent and legal approval.
        </p>
      </div>

      {onApplyConfig ? (
        <div style={{ marginTop: 12, display: 'flex', justifyContent: 'flex-end' }}>
          <button
            type="button"
            onClick={applyConfigToParent}
            style={{
              borderRadius: 8,
              border: 'none',
              background: 'var(--brand)',
              color: '#00101e',
              padding: '9px 12px',
              fontWeight: 700,
              cursor: 'pointer',
            }}
          >
            Apply Suite Config To Generator
          </button>
        </div>
      ) : null}
      </>
      ) : null}

      {showPortraitLibrary ? (
        <div
          role="dialog"
          aria-modal="true"
          style={{
            position: 'fixed',
            inset: 0,
            background: 'rgba(5, 8, 18, 0.72)',
            display: 'grid',
            placeItems: 'center',
            zIndex: 50,
            padding: 16,
          }}
        >
          <div className="card" style={{ width: 'min(920px, 100%)', maxHeight: '90vh', overflow: 'auto', padding: 16 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 10 }}>
              <h3 style={{ margin: 0 }}>Virtual Portrait Library</h3>
              <button
                type="button"
                onClick={() => setShowPortraitLibrary(false)}
                style={{ borderRadius: 8, border: '1px solid var(--line)', background: 'transparent', padding: '6px 10px', cursor: 'pointer' }}
              >
                Close
              </button>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, minmax(140px, 1fr))', gap: 12, marginTop: 12 }}>
              <div>
                <label style={{ display: 'block', fontSize: 12, fontWeight: 700, marginBottom: 6 }}>Gender</label>
                <select value={portraitGender} onChange={(event) => setPortraitGender(event.target.value as 'male' | 'female' | 'all')} style={{ width: '100%', padding: '8px 10px', borderRadius: 8, border: '1px solid var(--line)' }}>
                  <option value="all">All</option>
                  <option value="male">Male</option>
                  <option value="female">Female</option>
                </select>
              </div>

              <div>
                <label style={{ display: 'block', fontSize: 12, fontWeight: 700, marginBottom: 6 }}>Country</label>
                <div style={{ position: 'relative' }}>
                  <button
                    type="button"
                    onClick={() => setShowCountryMenu((value) => !value)}
                    style={{ width: '100%', padding: '8px 10px', borderRadius: 8, border: '1px solid var(--line)', background: '#111318', color: 'var(--text)', textAlign: 'left', cursor: 'pointer' }}
                  >
                    {portraitCountry}
                  </button>
                  {showCountryMenu ? (
                    <div style={{ position: 'absolute', top: 'calc(100% + 6px)', left: 0, right: 0, zIndex: 40, borderRadius: 10, border: '1px solid rgba(255,255,255,0.08)', background: '#17181c', boxShadow: '0 20px 60px rgba(0,0,0,0.35)', overflow: 'hidden' }}>
                      <div style={{ padding: 8, borderBottom: '1px solid rgba(255,255,255,0.08)' }}>
                        <input
                          value={portraitCountrySearch}
                          onChange={(event) => setPortraitCountrySearch(event.target.value)}
                          placeholder="Search country..."
                          style={{ width: '100%', padding: '8px 10px', borderRadius: 8, border: '1px solid rgba(255,255,255,0.08)', background: '#101115', color: 'var(--text)' }}
                        />
                      </div>
                      <div style={{ maxHeight: 220, overflow: 'auto' }}>
                        {filteredCountries.map((country) => (
                          <button
                            key={country}
                            type="button"
                            onClick={() => {
                              setPortraitCountry(country);
                              setPortraitCountrySearch('');
                              setShowCountryMenu(false);
                            }}
                            style={{ width: '100%', border: 'none', background: portraitCountry === country ? 'rgba(255,255,255,0.08)' : 'transparent', color: 'var(--text)', padding: '10px 12px', textAlign: 'left', cursor: 'pointer' }}
                          >
                            {country}
                          </button>
                        ))}
                      </div>
                    </div>
                  ) : null}
                </div>
              </div>

              <div>
                <label style={{ display: 'block', fontSize: 12, fontWeight: 700, marginBottom: 6 }}>Age</label>
                <select value={portraitAgeBand} onChange={(event) => setPortraitAgeBand(event.target.value as AgeBand)} style={{ width: '100%', padding: '8px 10px', borderRadius: 8, border: '1px solid var(--line)' }}>
                  {AGE_BANDS.map((band) => (
                    <option key={band} value={band}>
                      {band}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label style={{ display: 'block', fontSize: 12, fontWeight: 700, marginBottom: 6 }}>Total Avatars</label>
                <input
                  type="number"
                  value={portraitCount}
                  onChange={(event) => setPortraitCount(Math.max(1, Number(event.target.value) || 1))}
                  min={1}
                  style={{ width: '100%', padding: '8px 10px', borderRadius: 8, border: '1px solid var(--line)' }}
                />
              </div>
            </div>

            <div style={{ marginTop: 14, border: '1px solid var(--line)', borderRadius: 8, padding: 10 }}>
              <p style={{ margin: 0, fontSize: 12, fontWeight: 700 }}>Preview Selection</p>
              <p style={{ margin: '8px 0 0', fontSize: 13 }}>
                {portraitCount} avatars | Gender: {portraitGender} | Country: {portraitCountry || 'Any'} | Age: {portraitAgeBand}
              </p>
            </div>
          </div>
        </div>
      ) : null}
    </section>
  );
}

