                        <div>
                          <div className="flex items-center gap-3 mb-1">
                            <h2 className="font-bold text-white">{test.name}</h2>
                            <span className={`px-2 py-0.5 rounded text-xs font-medium ${test.status === 'running' ? 'bg-green-500/20 text-green-300' : 'bg-slate-600 text-slate-400'}`}>{test.status}</span>
                          </div>
                          {test.description && <p className="text-slate-400 text-sm">{test.description}</p>}
                          <p className="text-slate-500 text-xs mt-1">Metric: <span className="text-slate-300">{test.metric}</span> ┬À Created: {formatTime(test.created_at)}</p>
                        </div>
                        {test.analysis.winner && (
                          <div className="text-right">
                            <p className="text-slate-400 text-xs mb-1">Current Leader</p>
                            <span className="px-3 py-1 bg-yellow-500/20 text-yellow-300 rounded-lg text-sm font-bold">&#127942; {test.analysis.winner}</span>
                            <p className="text-slate-500 text-xs mt-1">Confidence: {pct(test.analysis.confidence)}</p>
                          </div>
                        )}
                      </div>
                      <div className="p-6 grid gap-4">
                        {Object.entries(test.analysis.by_variant).map(([variant, stats]) => {
                          const isWinner = variant === test.analysis.winner;
                          return (
                            <div key={variant} className={`rounded-lg p-4 border ${isWinner ? 'border-yellow-500/40 bg-yellow-500/5' : 'border-slate-600 bg-slate-800/40'}`}>
