                                <div className={`h-full rounded-full transition-all ${isWinner ? 'bg-yellow-400' : 'bg-blue-500'}`} style={{ width: `${Math.min(stats.success_rate * 100, 100)}%` }} />
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    </section>
                  ))
                )}
              </div>
            )}

            {/* EVENTS */}
            {tab === 'events' && (
              <section className="bg-slate-700/50 border border-slate-600 rounded-lg overflow-hidden">
                <div className="px-6 py-4 border-b border-slate-600"><h2 className="font-bold text-white">Recent IRA Events</h2></div>
