  const latestBrainReasoning = useMemo(() => asJson(latestBrainReasoningEnvelope.reasoning), [latestBrainReasoningEnvelope]);
  const directBrainReasoningSource = useMemo(() => {
    const provider = asString(latestBrainReasoning.provider, '').toLowerCase();
    const statusValue = asString(latestBrainReasoningEnvelope.status, '').toLowerCase();
    if (!provider && !statusValue) {
      return { label: 'No Reasoning Yet', tone: '#64748b', detail: 'Run brain reasoning to capture source telemetry.' };
    }
    if (provider && provider !== 'fallback_stub' && statusValue === 'ok') {
      return {
        label: 'Provider Reasoning',
        tone: '#16a34a',
        detail: `Direct result resolved by ${provider}.`,
      };
    }
    return {
      label: 'Fallback Reasoning',
      tone: '#d97706',
      detail: 'Direct result used fallback path' + (provider ? ` (${String(provider)})` : '') + '.',
    };
  }, [latestBrainReasoningEnvelope, latestBrainReasoning]);
