  async function refreshStatus() {
    setLoading(true);
    setError('');
    try {
      const payload = (await apiGet('/ira/status', tenantId)) as Json;
      setStatus({
        autonomy: typeof payload.autonomy === 'object' ? (payload.autonomy as Json) : {},
        connectors: Array.isArray(payload.connectors) ? (payload.connectors as Json[]) : [],
        finance_health: typeof payload.finance_health === 'object' ? (payload.finance_health as Json) : {},
        risk_signal: typeof payload.risk_signal === 'object' ? (payload.risk_signal as Json) : {},
        recent_events: Array.isArray(payload.recent_events) ? (payload.recent_events as Json[]) : [],
      });

      const auxiliaryRequests: Array<{ key: string; request: Promise<Json> }> = [
        { key: 'disputes', request: apiGet('/ira/disputes/dashboard', tenantId) as Promise<Json> },
        { key: 'crmRecommendation', request: apiGet('/ira/crm/hybrid-recommendation', tenantId) as Promise<Json> },
        { key: 'crmConnectors', request: apiGet('/ira/crm/connectors/status', tenantId) as Promise<Json> },
        { key: 'sync', request: apiGet('/crm/ops/live-sync', tenantId) as Promise<Json> },
        { key: 'backup', request: apiGet('/crm/ops/backup', tenantId) as Promise<Json> },
        { key: 'mlOverview', request: apiGet('/ira/ml/overview', tenantId) as Promise<Json> },
        { key: 'memoryOverview', request: apiGet('/ira/memory/overview', tenantId) as Promise<Json> },
        { key: 'agentFrameworks', request: apiGet('/ira/agent/frameworks', tenantId) as Promise<Json> },
        { key: 'frontierStack', request: apiGet('/ira/frontier/stack', tenantId) as Promise<Json> },
      ];

      const auxiliaryResults = await Promise.allSettled(auxiliaryRequests.map((item) => item.request));
      const warnings: string[] = [];

      auxiliaryResults.forEach((result, index) => {
        const key = auxiliaryRequests[index].key;
        if (result.status === 'fulfilled') {
          applyAuxiliaryData(key, result.value);
          return;
        }

        warnings.push(key);
        resetAuxiliaryData(key);
      });

      if (warnings.length) {
        setError(`Partial IRA data unavailable: ${warnings.join(', ')}`);
      }
    } catch (ex) {
      setError(ex instanceof Error ? ex.message : 'Failed to load IRA status.');
    } finally {
      setLoading(false);
    }
  }

