export const PROXY_BASE_URL = '/api/fastapi';
export const DEFAULT_TENANT_ID = process.env.NEXT_PUBLIC_DEFAULT_TENANT_ID || 'tenant-demo';
export const STORAGE_TOKEN_KEY = 'nuxtron.jwt';
export const STORAGE_TENANT_KEY = 'nuxtron.tenant';
export const STORAGE_SUPER_ADMIN_KEY = 'nuxtron.superAdminKey';

type JsonValue = Record<string, unknown>;

const RETRY_STATUS_CODES = new Set([502, 503, 504]);
const MAX_RETRIES = 2;

type RecoveryEventDetail = {
  path: string;
  attempt: number;
  totalRetries: number;
};

function isRetryableRequest(method: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE'): boolean {
  return method === 'GET';
}

function sleep(milliseconds: number): Promise<void> {
  return new Promise((resolve) => {
    setTimeout(resolve, milliseconds);
  });
}

function dispatchRecoveryEvent(eventName: string, detail: RecoveryEventDetail): void {
  if (!globalThis.window) return;
  globalThis.window.dispatchEvent(new CustomEvent(eventName, { detail }));
}

function getSessionTenant(): string {
  /* v8 ignore next */ if (!globalThis.window) return '';
  return globalThis.localStorage?.getItem(STORAGE_TENANT_KEY)?.trim() || '';
}

function getSuperAdminKey(): string {
  /* v8 ignore next */ if (!globalThis.window) return '';
  return globalThis.localStorage?.getItem(STORAGE_SUPER_ADMIN_KEY)?.trim() || '';
}

export function setAuthSession(token: string, tenantId: string): void {
  /* v8 ignore next */ if (!globalThis.window) return;
  globalThis.localStorage?.removeItem(STORAGE_TOKEN_KEY);
  if (tenantId.trim()) {
    globalThis.localStorage?.setItem(STORAGE_TENANT_KEY, tenantId.trim());
  }
}

export function clearAuthSession(): void {
  /* v8 ignore next */ if (!globalThis.window) return;
  globalThis.localStorage?.removeItem(STORAGE_TOKEN_KEY);
  globalThis.localStorage?.removeItem(STORAGE_TENANT_KEY);
}

export function setSuperAdminKeySession(superAdminKey: string): void {
  /* v8 ignore next */ if (!globalThis.window) return;
  if (superAdminKey.trim()) {
    globalThis.localStorage?.setItem(STORAGE_SUPER_ADMIN_KEY, superAdminKey.trim());
  }
}

async function parseBody(response: Response): Promise<JsonValue> {
  const contentType = response.headers.get('content-type') || '';
  if (contentType.includes('application/json')) {
    const text = await response.text();
    if (!text.trim()) {
      return {};
    }
    try {
      return JSON.parse(text) as JsonValue;
    } catch {
      return { detail: text };
    }
  }
  const text = await response.text();
  return text.trim() ? { detail: text } : {};
}

type RequestResult = {
  response: Response;
  data: JsonValue;
};

type AttemptEvaluation = { kind: 'success'; data: JsonValue } | { kind: 'retry' } | { kind: 'failure'; error: Error };

function formatErrorDetail(detail: unknown, status: number): string {
  if (typeof detail === 'string' && detail.trim()) {
    return detail;
  }

  if (Array.isArray(detail)) {
    const messages = detail
      .map((item) => {
        if (!item || typeof item !== 'object') {
          return null;
        }

        const message = typeof item.msg === 'string' ? item.msg : '';
        const location = Array.isArray(item.loc)
          ? item.loc.filter((value: unknown) => typeof value === 'string' || typeof value === 'number').join('.')
          : '';

        if (message && location) {
          return `${location}: ${message}`;
        }

        return message || null;
      })
      .filter((value): value is string => Boolean(value));

    if (messages.length) {
      return messages.join('; ');
    }
  }

  return `Request failed with status ${status}`;
}

async function performRequest(url: string, init: RequestInit): Promise<RequestResult> {
  const response = await fetch(url, init);
  return { response, data: await parseBody(response) };
}

async function requestWithRecovery(
  url: string,
  init: RequestInit,
  path: string,
  canRetry: boolean
): Promise<JsonValue> {
  let lastError: Error | null = null;
  let recoveryStarted = false;

  for (let attempt = 0; attempt <= MAX_RETRIES; attempt += 1) {
    const attemptNumber = attempt + 1;
    const evaluation = await evaluateAttempt(url, init, canRetry, attempt);

    if (evaluation.kind === 'success') {
      if (recoveryStarted) {
        dispatchRecoveryEnd(path, attemptNumber);
      }
      return evaluation.data;
    }

    if (evaluation.kind === 'retry') {
      recoveryStarted = await triggerRetry(path, attemptNumber);
      continue;
    }

    if (!shouldRetryNetworkFailure(canRetry, attempt)) {
      if (recoveryStarted) {
        dispatchRecoveryEnd(path, attemptNumber);
      }
      throw evaluation.error;
    }

    recoveryStarted = await triggerRetry(path, attemptNumber);
    lastError = evaluation.error;
  }

  throw lastError || new Error('Unable to recover request after retries.');
}

async function evaluateAttempt(
  url: string,
  init: RequestInit,
  canRetry: boolean,
  attempt: number
): Promise<AttemptEvaluation> {
  try {
    const result = await performRequest(url, init);

    if (shouldRetryStatusFailure(canRetry, result.response.status, attempt)) {
      return { kind: 'retry' };
    }

    if (!result.response.ok) {
      const detail = formatErrorDetail(result.data.detail, result.response.status);
      return { kind: 'failure', error: new Error(detail) };
    }

    return { kind: 'success', data: result.data };
  } catch (error) {
    return {
      kind: 'failure',
      error: error instanceof Error ? error : new Error('Unknown request error'),
    };
  }
}

function shouldRetryStatusFailure(canRetry: boolean, status: number, attempt: number): boolean {
  return canRetry && RETRY_STATUS_CODES.has(status) && attempt < MAX_RETRIES;
}

function shouldRetryNetworkFailure(canRetry: boolean, attempt: number): boolean {
  return canRetry && attempt < MAX_RETRIES;
}

async function triggerRetry(path: string, attemptNumber: number): Promise<true> {
  dispatchRecoveryStart(path, attemptNumber);
  await sleep(200 * attemptNumber);
  return true;
}

function dispatchRecoveryStart(path: string, attempt: number): void {
  dispatchRecoveryEvent('nuxtron:auto-recovery:start', {
    path,
    attempt,
    totalRetries: MAX_RETRIES,
  });
}

function dispatchRecoveryEnd(path: string, attempt: number): void {
  dispatchRecoveryEvent('nuxtron:auto-recovery:end', {
    path,
    attempt,
    totalRetries: MAX_RETRIES,
  });
}

async function apiRequest(
  path: string,
  method: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE',
  tenantId: string,
  body?: JsonValue,
  extraHeaders?: Record<string, string>
): Promise<JsonValue> {
  const resolvedTenant = tenantId.trim() || getSessionTenant() || DEFAULT_TENANT_ID;
  const superAdminKey = getSuperAdminKey();

  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    'X-Tenant-Id': resolvedTenant,
  };

  if (superAdminKey) {
    headers['X-Super-Admin-Key'] = superAdminKey;
  }
  if (extraHeaders) {
    for (const [name, value] of Object.entries(extraHeaders)) {
      if (value.trim()) {
        headers[name] = value;
      }
    }
  }

  const canRetry = isRetryableRequest(method);
  const url = `${PROXY_BASE_URL}${path}`;
  const init: RequestInit = {
    method,
    headers,
    body: body ? JSON.stringify(body) : undefined,
    cache: 'no-store',
  };

  return requestWithRecovery(url, init, path, canRetry);
}

export async function apiGet(path: string, tenantId = DEFAULT_TENANT_ID): Promise<JsonValue> {
  return apiRequest(path, 'GET', tenantId);
}

export async function apiPost(
  path: string,
  body: JsonValue,
  tenantId = DEFAULT_TENANT_ID,
  extraHeaders?: Record<string, string>
): Promise<JsonValue> {
  return apiRequest(path, 'POST', tenantId, body, extraHeaders);
}

export async function apiPatch(path: string, body: JsonValue, tenantId = DEFAULT_TENANT_ID): Promise<JsonValue> {
  return apiRequest(path, 'PATCH', tenantId, body);
}

export async function apiPut(path: string, body: JsonValue, tenantId = DEFAULT_TENANT_ID): Promise<JsonValue> {
  return apiRequest(path, 'PUT', tenantId, body);
}

export async function apiDelete(path: string, tenantId = DEFAULT_TENANT_ID): Promise<JsonValue> {
  return apiRequest(path, 'DELETE', tenantId);
}

const API_BASE = '/api/fastapi';
export const DEFAULT_TENANT_ID = process.env.NEXT_PUBLIC_DEFAULT_TENANT_ID ?? 'tenant-demo';
const API_TIMEOUT_MS = 45000;
const RESPONSE_CACHE_TTL_MS = 120000;
const INFLIGHT_REQUESTS = new Map<string, Promise<unknown>>();
const RESPONSE_CACHE = new Map<string, { expiresAt: number; value: unknown }>();
const LOCAL_CACHE_PREFIX = 'nuxtron:platform-api:';

function requestId(): string {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  return `req-${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

async function parseResponseBody(res: Response): Promise<unknown> {
  const contentType = res.headers.get('content-type') || '';
  const raw = await res.text();
  if (!raw) return {};
  if (contentType.toLowerCase().includes('application/json')) {
    try {
      return JSON.parse(raw);
    } catch {
      return { detail: raw };
    }
  }
  return { detail: raw };
}

function inflightKey(method: string, path: string, tenantId: string, payload?: unknown): string {
  const payloadPart = payload === undefined ? '' : JSON.stringify(payload);
  return `${method}:${tenantId}:${path}:${payloadPart}`;
}

function getCachedResponse<T>(key: string): T | null {
  const cached = RESPONSE_CACHE.get(key);
  if (cached) {
    if (cached.expiresAt <= Date.now()) {
      RESPONSE_CACHE.delete(key);
    } else {
      return cached.value as T;
    }
  }

  if (typeof window === 'undefined') return null;
  try {
    const raw = window.localStorage.getItem(LOCAL_CACHE_PREFIX + key);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as { expiresAt?: number; value?: unknown };
    if (!parsed || typeof parsed.expiresAt !== 'number' || parsed.expiresAt <= Date.now()) {
      window.localStorage.removeItem(LOCAL_CACHE_PREFIX + key);
      return null;
    }
    RESPONSE_CACHE.set(key, { expiresAt: parsed.expiresAt, value: parsed.value });
    return parsed.value as T;
  } catch {
    return null;
  }
}

function setCachedResponse<T>(key: string, value: T): void {
  const entry = {
    expiresAt: Date.now() + RESPONSE_CACHE_TTL_MS,
    value,
  };
  RESPONSE_CACHE.set(key, entry);
  if (typeof window === 'undefined') return;
  try {
    window.localStorage.setItem(LOCAL_CACHE_PREFIX + key, JSON.stringify(entry));
  } catch {
    // Ignore localStorage write errors (quota/private mode); in-memory cache still works.
  }
}

async function fetchWithTimeout(input: RequestInfo | URL, init: RequestInit): Promise<Response> {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), API_TIMEOUT_MS);
  try {
    return await fetch(input, { ...init, signal: controller.signal });
  } finally {
    clearTimeout(timeout);
  }
}

function dedupeInFlight<T>(key: string, run: () => Promise<T>): Promise<T> {
  const existing = INFLIGHT_REQUESTS.get(key);
  if (existing) return existing as Promise<T>;
  const task = run().finally(() => INFLIGHT_REQUESTS.delete(key));
  INFLIGHT_REQUESTS.set(key, task as Promise<unknown>);
  return task;
}

export async function apiGet<T>(path: string, tenantId = DEFAULT_TENANT_ID): Promise<T> {
  const key = inflightKey('GET', path, tenantId);
  const cached = getCachedResponse<T>(key);
  if (cached !== null) return cached;

  return dedupeInFlight<T>(key, async () => {
    const res = await fetchWithTimeout(`${API_BASE}${path}`, {
      method: 'GET',
      headers: { 'X-Tenant-Id': tenantId, 'X-Request-ID': requestId() },
      cache: 'no-store',
    });
    const data = (await parseResponseBody(res)) as Record<string, unknown>;
    const detail = typeof data?.detail === 'string' ? data.detail : `Request failed: ${res.status}`;
    if (!res.ok) throw new Error(detail);
    const typed = data as T;
    setCachedResponse(key, typed);
    return typed;
  });
}

export async function apiSend<T>(
  path: string,
  method: 'POST' | 'PATCH' | 'PUT' | 'DELETE',
  payload?: unknown,
  tenantId = DEFAULT_TENANT_ID
): Promise<T> {
  const cacheKey = inflightKey(method, path, tenantId, payload);
  const shouldCachePost = method === 'POST' && path.startsWith('/seo-platform/');
  if (shouldCachePost) {
    const cached = getCachedResponse<T>(cacheKey);
    if (cached !== null) return cached;
  }

  const run = async () => {
    const res = await fetchWithTimeout(`${API_BASE}${path}`, {
      method,
      headers: {
        'Content-Type': 'application/json',
        'X-Tenant-Id': tenantId,
        'X-Request-ID': requestId(),
      },
      body: payload === undefined ? undefined : JSON.stringify(payload),
    });
    const data = (await parseResponseBody(res)) as Record<string, unknown>;
    const detail = typeof data?.detail === 'string' ? data.detail : `Request failed: ${res.status}`;
    if (!res.ok) throw new Error(detail);
    const typed = data as T;
    if (shouldCachePost) setCachedResponse(cacheKey, typed);
    return typed;
  };

  // Most SEO calls are idempotent analyses; in-flight dedupe prevents duplicate compute work.
  if (shouldCachePost) {
    return dedupeInFlight<T>(cacheKey, run);
  }
  return run();
}

