'use client';

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';

type NotificationItem = {
  id: number;
  title: string;
  message: string;
  category: string;
  // ENHANCED: priority field (info | warning | error | success | critical)
  priority: string;
  read: boolean;
  created_at: string;
};

// ENHANCED: toast state for real-time popup alerts
type ToastItem = {
  id: number;
  title: string;
  message: string;
  priority: string;
  expiresAt: number;
};

type NotificationSnapshot = {
  notifications: NotificationItem[];
  unreadCount: number;
  // ENHANCED (additive): global unread count from backend snapshot.
  unreadTotal?: number;
  total?: number;
};

const proxyBaseUrl = '/api/fastapi';
const defaultTenantId = process.env.NEXT_PUBLIC_DEFAULT_TENANT_ID || 'tenant-demo';

function formatAge(value: string) {
  const parsed = Date.parse(value);
  if (Number.isNaN(parsed)) {
    return 'just now';
  }

  const seconds = Math.max(0, Math.round((Date.now() - parsed) / 1000));
  if (seconds < 60) return 'just now';
  const minutes = Math.floor(seconds / 60);
  if (minutes < 60) return `${minutes}m ago`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `${hours}h ago`;
  return `${Math.floor(hours / 24)}d ago`;
}

export default function NotificationCenter() {
  const [panelOpen, setPanelOpen] = useState(false);
  // ENHANCED: keep raw feed state separate so UI filters do not fight SSE snapshots.
  const [allNotifications, setAllNotifications] = useState<NotificationItem[]>([]);
  const [notifications, setNotifications] = useState<NotificationItem[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [connectionState, setConnectionState] = useState<'connecting' | 'live' | 'offline'>('connecting');
  // ENHANCED: category filter ÔÇö backend supports ?category=X, now exposed in UI
  const [filterCategory, setFilterCategory] = useState<string>('');
  // ENHANCED: toast queue for popup alerts when panel is closed
  const [toasts, setToasts] = useState<ToastItem[]>([]);
  const prevNotifIdsRef = useRef<Set<number>>(new Set());
  const prevUnreadCountRef = useRef(0);
  const panelOpenRef = useRef(false);

  const removeExpiredToasts = useCallback(() => {
    const now = Date.now();
    setToasts((prev) => prev.filter((t) => t.expiresAt > now));
  }, []);

  useEffect(() => {
    panelOpenRef.current = panelOpen;
  }, [panelOpen]);

  // ENHANCED: dismiss expired toasts every second
  useEffect(() => {
    const interval = setInterval(() => {
      removeExpiredToasts();
    }, 1000);
    return () => clearInterval(interval);
  }, [removeExpiredToasts]);

  // ENHANCED: helper to add a toast for newly arrived notifications
  const addToast = useCallback((item: NotificationItem) => {
    setToasts((prev) => {
      // Don't duplicate toasts for the same notification
      if (prev.some((t) => t.id === item.id)) return prev;
      return [
        ...prev,
        {
          id: item.id,
          title: item.title,
          message: item.message,
          priority: item.priority || 'info',
          expiresAt: Date.now() + 5000,
        },
      ];
    });
  }, []);

  const dismissToast = useCallback((toastId: number) => {
    setToasts((prev) => prev.filter((t) => t.id !== toastId));
  }, []);

  const authHeaders = useMemo(
    () => ({
      'Content-Type': 'application/json',
      'X-Tenant-Id': defaultTenantId,
    }),
    []
  );

  useEffect(() => {
    let cancelled = false;

    async function loadInitialSnapshot() {
      try {
        // ENHANCED: apply category filter if set
        const url = new URL(`${proxyBaseUrl}/notifications`, globalThis.location.origin);
        if (filterCategory) url.searchParams.set('category', filterCategory);
        const response = await fetch(url.toString(), {
          headers: authHeaders,
          cache: 'no-store',
        });
        if (!response.ok) {
          throw new Error(`Notification bootstrap failed: ${response.status}`);
        }

        const payload = (await response.json()) as NotificationSnapshot;
        if (cancelled) return;
        const incoming = payload.notifications || [];
        const unread = Number(payload.unreadTotal ?? payload.unreadCount ?? 0);
        setAllNotifications(incoming);
        setUnreadCount(unread);
        setNotifications(filterCategory ? incoming.filter((n) => n.category === filterCategory) : incoming);
        // Seed known IDs to avoid stale toasts
        prevNotifIdsRef.current = new Set(incoming.map((n) => n.id));
        prevUnreadCountRef.current = unread;
      } catch {
        if (!cancelled) {
          setConnectionState('offline');
        }
      }
    }

    loadInitialSnapshot();
    return () => {
      cancelled = true;
    };
  }, [authHeaders, filterCategory]);

  // ENHANCED: update visible list when only category filter changes.
  useEffect(() => {
    setNotifications(filterCategory ? allNotifications.filter((n) => n.category === filterCategory) : allNotifications);
  }, [allNotifications, filterCategory]);

  useEffect(() => {
    const streamUrl = new URL(`${proxyBaseUrl}/notifications/stream`, globalThis.location.origin);
    streamUrl.searchParams.set('tenant_id', defaultTenantId);

    const eventSource = new EventSource(streamUrl);

    const handleSnapshot = (event: MessageEvent<string>) => {
      try {
        const payload = JSON.parse(event.data) as NotificationSnapshot;
        const incoming = payload.notifications || [];
        const unread = Number(payload.unreadTotal ?? payload.unreadCount ?? 0);
        setAllNotifications(incoming);
        setUnreadCount(unread);
        setNotifications(filterCategory ? incoming.filter((n) => n.category === filterCategory) : incoming);
        setConnectionState('live');

        // ENHANCED: detect new unread notifications and show toast when panel is closed
        const newItems = incoming.filter((n) => !n.read && !prevNotifIdsRef.current.has(n.id));
        const unreadIncreased = unread > prevUnreadCountRef.current;
        const newestCreatedAt = incoming[0]?.created_at ? Date.parse(incoming[0].created_at) : Number.NaN;
        const hasVeryRecentItem = Number.isFinite(newestCreatedAt) && Date.now() - newestCreatedAt < 7000;
        if (!panelOpenRef.current && (newItems.length > 0 || unreadIncreased || hasVeryRecentItem)) {
          const candidate = newItems[0] || incoming.find((n) => !n.read) || incoming[0];
          if (candidate) addToast(candidate);
        }
        // Update known IDs
        prevNotifIdsRef.current = new Set(incoming.map((n) => n.id));
        prevUnreadCountRef.current = unread;
      } catch {
        setConnectionState('offline');
      }
    };

    eventSource.addEventListener('notifications.snapshot', handleSnapshot as EventListener);
    eventSource.addEventListener('notifications.updated', handleSnapshot as EventListener);
    eventSource.onerror = () => {
      setConnectionState('offline');
    };

    return () => {
      eventSource.close();
    };
  }, [addToast, filterCategory]);

  // Fallback polling keeps notification state fresh if SSE connects late.
  useEffect(() => {
    let cancelled = false;

    async function pollSnapshot() {
      try {
        const url = new URL(`${proxyBaseUrl}/notifications`, globalThis.location.origin);
        if (filterCategory) url.searchParams.set('category', filterCategory);
        const response = await fetch(url.toString(), {
          headers: authHeaders,
          cache: 'no-store',
        });
        if (!response.ok || cancelled) return;

        const payload = (await response.json()) as NotificationSnapshot;
        const incoming = payload.notifications || [];
        const unread = Number(payload.unreadTotal ?? payload.unreadCount ?? 0);
        const unreadIncreased = unread > prevUnreadCountRef.current;
        const newItems = incoming.filter((n) => !n.read && !prevNotifIdsRef.current.has(n.id));
        const newestCreatedAt = incoming[0]?.created_at ? Date.parse(incoming[0].created_at) : Number.NaN;
        const hasVeryRecentItem = Number.isFinite(newestCreatedAt) && Date.now() - newestCreatedAt < 7000;

        setAllNotifications(incoming);
        setUnreadCount(unread);
        setNotifications(filterCategory ? incoming.filter((n) => n.category === filterCategory) : incoming);

        if (!panelOpenRef.current && (unreadIncreased || newItems.length > 0 || hasVeryRecentItem)) {
          const candidate = newItems[0] || incoming.find((n) => !n.read) || incoming[0];
          if (candidate) addToast(candidate);
        }

        prevNotifIdsRef.current = new Set(incoming.map((n) => n.id));
        prevUnreadCountRef.current = unread;
      } catch {
        // Ignore polling failures; SSE remains the primary channel.
      }
    }

    const interval = setInterval(() => {
      void pollSnapshot();
    }, 30000);

    return () => {
      cancelled = true;
      clearInterval(interval);
    };
  }, [addToast, authHeaders, filterCategory]);

  async function markAllRead() {
    const response = await fetch(`${proxyBaseUrl}/notifications/read-all`, {
      method: 'POST',
      headers: authHeaders,
    });
    if (!response.ok) {
      return;
    }
  }

  async function markOneRead(notificationId: number) {
    const response = await fetch(`${proxyBaseUrl}/notifications/${notificationId}/read`, {
      method: 'POST',
      headers: authHeaders,
    });
    if (!response.ok) {
      return;
    }
  }

  async function dismissOne(notificationId: number) {
    const response = await fetch(`${proxyBaseUrl}/notifications/${notificationId}`, {
      method: 'DELETE',
      headers: authHeaders,
    });
    if (!response.ok) {
      return;
    }
  }

  // ENHANCED: auto-mark-read when user clicks to open a notification item
  async function handleItemClick(notification: NotificationItem) {
    if (!notification.read) {
      await markOneRead(notification.id);
    }
  }

  function handleItemKeyDown(event: React.KeyboardEvent<HTMLButtonElement>, notification: NotificationItem) {
    if (notification.read) {
      return;
    }

    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      void handleItemClick(notification);
    }
  }

  const triggerLabel = unreadCount > 0 ? `Notifications (${unreadCount} unread)` : 'Notifications';
  let connectionStatusText = 'Realtime sync reconnecting';
  if (connectionState === 'live') {
    connectionStatusText = 'Realtime sync active';
  } else if (connectionState === 'connecting') {
    connectionStatusText = 'Connecting...';
  }

  return (
    <div className="notification-shell">
      {/* Newly added shared shell component avoids duplicating notification UI per page. */}

      {/* ENHANCED: toast popup area for realtime alerts when panel is closed */}
      {toasts.length > 0 ? (
        <div className="notification-toast-tray" aria-live="polite" aria-atomic="false">
          {toasts.map((toast) => (
            <div key={toast.id} className={`notification-toast notification-toast--${toast.priority}`} role="alert">
              <strong className="notification-toast-title">{toast.title}</strong>
              <p className="notification-toast-msg">{toast.message}</p>
              <button
                type="button"
                className="notification-toast-close"
                aria-label="Dismiss toast"
                onClick={() => dismissToast(toast.id)}
              >
                ├ù
              </button>
            </div>
          ))}
        </div>
      ) : null}

      <button
        type="button"
        id="notificationTrigger"
        className="notification-trigger"
        aria-label={triggerLabel}
        onClick={() => setPanelOpen((value) => !value)}
      >
        <span className="notification-trigger-label">Alerts</span>
        {unreadCount > 0 ? (
          <span id="notificationBadge" className="notification-badge">
            {unreadCount}
          </span>
        ) : null}
      </button>

      <aside id="notificationPanel" className={`notification-panel${panelOpen ? ' open' : ''}`} aria-live="polite">
        <div className="notification-panel-head">
          <div>
            <h3>Notification Center</h3>
            <p className="muted">{connectionStatusText}</p>
          </div>
          <button type="button" id="markAllReadBtn" onClick={markAllRead} disabled={unreadCount === 0}>
            Mark all read
          </button>
        </div>

        {/* ENHANCED: category filter dropdown ÔÇö maps to ?category=X on the list endpoint */}
        <div className="notification-filter-row">
          <label htmlFor="notifCategoryFilter" className="sr-only">
            Filter by category
          </label>
          <select
            id="notifCategoryFilter"
            className="notification-filter-select"
            value={filterCategory}
            onChange={(e) => setFilterCategory(e.target.value)}
          >
            <option value="">All categories</option>
            {/* Collect unique categories from current list for dynamic options */}
            {[...new Set(allNotifications.map((n) => n.category))]
              .sort((a, b) => a.localeCompare(b))
              .map((cat) => (
                <option key={cat} value={cat}>
                  {cat}
                </option>
              ))}
          </select>
        </div>

        <div id="notificationList" className="notification-list">
          {notifications.length === 0 ? (
            <article className="notification-item notification-empty">
              <strong>No notifications yet</strong>
              <p className="muted">Realtime alerts will appear here as backend events arrive.</p>
            </article>
          ) : (
            notifications.map((notification) => (
              /* ENHANCED: click anywhere on item auto-marks it as read */
              <article
                key={notification.id}
                className={`notification-item notification-item--${notification.priority || 'info'}${notification.read ? ' is-read' : ''}`}
              >
                <button
                  type="button"
                  className="notification-copy"
                  onClick={() => {
                    void handleItemClick(notification);
                  }}
                  onKeyDown={(e) => handleItemKeyDown(e, notification)}
                  style={{ cursor: notification.read ? 'default' : 'pointer' }}
                  disabled={notification.read}
                >
                  <div className="notification-meta-row">
                    <strong>{notification.title}</strong>
                    <span className="notification-age">{formatAge(notification.created_at)}</span>
                  </div>
                  <p>{notification.message}</p>
                  <div className="notification-meta-tags">
                    <span className="notification-category">{notification.category}</span>
                    {/* ENHANCED: priority badge for non-info notifications */}
                    {notification.priority && notification.priority !== 'info' ? (
                      <span className={`notification-priority notification-priority--${notification.priority}`}>
                        {notification.priority}
                      </span>
                    ) : null}
                  </div>
                </button>
                <div className="notification-actions">
                  {notification.read ? null : (
                    <button
                      type="button"
                      className="notification-read"
                      onClick={(e) => {
                        e.stopPropagation();
                        markOneRead(notification.id);
                      }}
                    >
                      Read
                    </button>
                  )}
                  <button
                    type="button"
                    className="notification-dismiss"
                    onClick={(e) => {
                      e.stopPropagation();
                      dismissOne(notification.id);
                    }}
                  >
                    Dismiss
                  </button>
                </div>
              </article>
            ))
          )}
        </div>
      </aside>
    </div>
  );
}

'use client';

import { useEffect, useMemo, useState } from 'react';
import { apiGet, apiPost, DEFAULT_TENANT_ID } from '../lib/api-client';

type Json = Record<string, unknown>;

function asNumber(v: unknown, fb = 0): number {
  return typeof v === 'number' ? v : fb;
}
function asString(v: unknown, fb = ''): string {
  return typeof v === 'string' ? v : fb;
}
function asArray(v: unknown): unknown[] {
  return Array.isArray(v) ? v : [];
}
function asObject(v: unknown): Json {
  return v !== null && typeof v === 'object' && !Array.isArray(v) ? (v as Json) : {};
}

const BAND_COLOR: Record<string, string> = {
  excellent: '#22c55e',
  good: '#60a5fa',
  fair: '#f59e0b',
  poor: '#ef4444',
};

const OUTCOME_BADGE: Record<string, string> = {
  conversion: '­ƒÆ░',
  churn_saved: '­ƒøí',
  dispute_resolved: 'Ô£à',
  fraud_blocked: '­ƒÜ½',
  upsell_accepted: '­ƒôê',
  support_deflected: '­ƒñû',
  campaign_attributed: '­ƒôú',
  no_outcome: 'ÔÅ│',
};

export default function OutcomeGraphPage() {
  const [tenantId, setTenantId] = useState(DEFAULT_TENANT_ID);
  const [graph, setGraph] = useState<Json>({});
  const [qualityScores, setQualityScores] = useState<unknown[]>([]);
  const [pendingActions, setPendingActions] = useState<unknown[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  // Record action form
  const [actionType, setActionType] = useState('ira_recommendation');
  const [actionTarget, setActionTarget] = useState('customers');
  const [actionCommand, setActionCommand] = useState('');
  const [actionMsg, setActionMsg] = useState('');

  // Submit quality form
  const [qualityActionId, setQualityActionId] = useState('');
  const [accuracy, setAccuracy] = useState(85);
  const [safety, setSafety] = useState(90);
  const [speedMs, setSpeedMs] = useState(500);
  const [revenueImpact, setRevenueImpact] = useState(0);
  const [qualityMsg, setQualityMsg] = useState('');

  const totalActions = asNumber(graph.total_actions, 0);
  const attributed = asNumber(graph.attributed_outcomes, 0);
  const totalRevenue = asNumber(graph.total_revenue_impact_gbp, 0);
  const avgQuality = asNumber(graph.avg_decision_quality_score, 0);
  const outcomeDist = asObject(graph.outcome_distribution);
  const bandDist = asObject(graph.quality_band_distribution);

  const attributionRate = useMemo(
    () => (totalActions > 0 ? Math.round((attributed / totalActions) * 100) : 0),
    [totalActions, attributed]
  );

  async function load() {
    setLoading(true);
    setError('');
    try {
      const [graphData, qualData, pendData] = await Promise.all([
        apiGet('/outcome/graph', tenantId),
        apiGet('/outcome/quality', tenantId),
        apiGet('/outcome/actions/pending', tenantId),
      ]);
      setGraph(graphData as Json);
      setQualityScores(asArray((qualData as Json).scores));
      setPendingActions(asArray((pendData as Json).pending));
    } catch (e) {
      setError(String(e));
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tenantId]);

  async function recordAction() {
    if (!actionCommand.trim()) return;
    setActionMsg('');
    try {
      const res = await apiPost(
        '/outcome/actions',
        {
          action_type: actionType,
          target: actionTarget,
          command: actionCommand,
          actor_role: 'ira_autonomous',
          dry_run: false,
        },
        tenantId
      );
      const id = asString((res as Json).action_id);
      setActionMsg(`Recorded action ${id}`);
      setQualityActionId(id);
      setActionCommand('');
      await load();
    } catch (e) {
      setActionMsg(`Error: ${String(e)}`);
    }
  }

  async function submitQuality() {
    if (!qualityActionId.trim()) return;
    setQualityMsg('');
    try {
      const res = await apiPost(
        '/outcome/quality',
        {
          action_id: qualityActionId,
          accuracy,
          safety,
          speed_ms: speedMs,
          revenue_impact_gbp: revenueImpact,
          human_override: false,
        },
        tenantId
      );
      const r = res as Json;
      setQualityMsg(`Score: ${asNumber(r.score)} (${asString(r.band)})`);
      await load();
    } catch (e) {
      setQualityMsg(`Error: ${String(e)}`);
    }
  }

  return (
    <main style={{ padding: '2rem', maxWidth: '1100px', margin: '0 auto' }}>
      <h1 style={{ fontSize: '1.8rem', fontWeight: 700, marginBottom: '0.5rem' }}>Outcome Graph</h1>
      <p style={{ color: '#888', marginBottom: '1.5rem' }}>
        Action-to-outcome attribution and Decision Quality scores ÔÇö the core of the Outcome Data Flywheel.
      </p>

      <div style={{ display: 'flex', gap: '1rem', flexWrap: 'wrap', marginBottom: '1.5rem' }}>
        <input
          value={tenantId}
          onChange={(e) => setTenantId(e.target.value)}
          placeholder="Tenant ID"
          style={{
            padding: '0.5rem 0.8rem',
            borderRadius: 6,
            border: '1px solid #333',
            background: '#111',
            color: '#fff',
            minWidth: 200,
          }}
        />
        <button
          onClick={load}
          disabled={loading}
          style={{
            padding: '0.5rem 1.2rem',
            borderRadius: 6,
            background: '#2563eb',
            color: '#fff',
            border: 'none',
            cursor: 'pointer',
          }}
        >
          {loading ? 'LoadingÔÇª' : 'Refresh'}
        </button>
      </div>

      {error && <p style={{ color: '#ef4444', marginBottom: '1rem' }}>{error}</p>}

      {/* KPI strip */}
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(150px, 1fr))',
          gap: '1rem',
          marginBottom: '2rem',
        }}
      >
        {[
          { label: 'Total Actions', value: totalActions, color: '#60a5fa' },
          { label: 'Attributed', value: attributed, color: '#22c55e' },
          { label: 'Attribution Rate', value: `${attributionRate}%`, color: '#a78bfa' },
          { label: 'Revenue Impact ┬ú', value: `┬ú${totalRevenue.toFixed(2)}`, color: '#f59e0b' },
          { label: 'Avg Quality Score', value: avgQuality, color: '#34d399' },
        ].map((kpi) => (
          <div
            key={kpi.label}
            style={{
              background: '#111',
              border: '1px solid #222',
              borderRadius: 8,
              padding: '0.75rem 1rem',
              textAlign: 'center',
            }}
          >
            <div style={{ fontSize: '1.8rem', fontWeight: 700, color: kpi.color }}>{kpi.value}</div>
            <div style={{ fontSize: '0.78rem', color: '#888' }}>{kpi.label}</div>
          </div>
        ))}
      </div>

      {/* Outcome distribution */}
      {Object.keys(outcomeDist).length > 0 && (
        <section style={{ marginBottom: '2rem' }}>
          <h2 style={{ fontSize: '1.1rem', fontWeight: 600, marginBottom: '0.75rem' }}>Outcome Distribution</h2>
          <div style={{ display: 'flex', gap: '0.75rem', flexWrap: 'wrap' }}>
            {Object.entries(outcomeDist).map(([outcome, count]) => (
              <div
                key={outcome}
                style={{
                  background: '#111',
                  border: '1px solid #222',
                  borderRadius: 8,
                  padding: '0.6rem 1rem',
                  minWidth: 130,
                  textAlign: 'center',
                }}
              >
                <div style={{ fontSize: '1.2rem' }}>{OUTCOME_BADGE[outcome] ?? '­ƒôè'}</div>
                <div style={{ fontWeight: 600 }}>{count as number}</div>
                <div style={{ fontSize: '0.75rem', color: '#888' }}>{outcome.replaceAll('_', ' ')}</div>
              </div>
            ))}
          </div>
        </section>
      )}

      {/* Quality band distribution */}
      {Object.keys(bandDist).length > 0 && (
        <section style={{ marginBottom: '2rem' }}>
          <h2 style={{ fontSize: '1.1rem', fontWeight: 600, marginBottom: '0.75rem' }}>Decision Quality Bands</h2>
          <div style={{ display: 'flex', gap: '0.75rem' }}>
            {(['excellent', 'good', 'fair', 'poor'] as const).map((band) => (
              <div
                key={band}
                style={{
                  background: '#111',
                  border: `1px solid ${BAND_COLOR[band]}`,
                  borderRadius: 8,
                  padding: '0.6rem 1rem',
                  minWidth: 100,
                  textAlign: 'center',
                }}
              >
                <div style={{ fontSize: '1.4rem', fontWeight: 700, color: BAND_COLOR[band] }}>
                  {(bandDist[band] as number) ?? 0}
                </div>
                <div style={{ fontSize: '0.78rem', color: '#888', textTransform: 'capitalize' }}>{band}</div>
              </div>
            ))}
          </div>
        </section>
      )}

      {/* Record action form */}
      <section
        style={{
          marginBottom: '2rem',
          background: '#0d0d0d',
          border: '1px solid #222',
          borderRadius: 8,
          padding: '1.25rem',
        }}
      >
        <h2 style={{ fontSize: '1.1rem', fontWeight: 600, marginBottom: '1rem' }}>Record Autonomous Action</h2>
        <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap', marginBottom: '0.5rem' }}>
          <input
            value={actionType}
            onChange={(e) => setActionType(e.target.value)}
            placeholder="Action type"
            style={{
              width: 180,
              padding: '0.4rem 0.7rem',
              borderRadius: 6,
              border: '1px solid #333',
              background: '#111',
              color: '#fff',
            }}
          />
          <input
            value={actionTarget}
            onChange={(e) => setActionTarget(e.target.value)}
            placeholder="Target"
            style={{
              width: 130,
              padding: '0.4rem 0.7rem',
              borderRadius: 6,
              border: '1px solid #333',
              background: '#111',
              color: '#fff',
            }}
          />
          <input
            value={actionCommand}
            onChange={(e) => setActionCommand(e.target.value)}
            placeholder="Command description"
            style={{
              flex: 1,
              minWidth: 200,
              padding: '0.4rem 0.7rem',
              borderRadius: 6,
              border: '1px solid #333',
              background: '#111',
              color: '#fff',
            }}
          />
          <button
            onClick={recordAction}
            style={{
              padding: '0.4rem 1rem',
              borderRadius: 6,
              background: '#22c55e',
              color: '#000',
              border: 'none',
              cursor: 'pointer',
              fontWeight: 600,
            }}
          >
            Record
          </button>
        </div>
        {actionMsg && <p style={{ color: '#60a5fa', fontSize: '0.85rem' }}>{actionMsg}</p>}
      </section>

      {/* Submit quality score */}
      <section
        style={{
          marginBottom: '2rem',
          background: '#0d0d0d',
          border: '1px solid #222',
          borderRadius: 8,
          padding: '1.25rem',
        }}
      >
        <h2 style={{ fontSize: '1.1rem', fontWeight: 600, marginBottom: '1rem' }}>Submit Decision Quality Score</h2>
        <div
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fit, minmax(160px, 1fr))',
            gap: '0.5rem',
            marginBottom: '0.75rem',
          }}
        >
          <div>
            <label htmlFor="quality-action-id" style={{ fontSize: '0.78rem', color: '#888' }}>
              Action ID
            </label>
            <input
              id="quality-action-id"
              value={qualityActionId}
              onChange={(e) => setQualityActionId(e.target.value)}
              style={{
                width: '100%',
