export default function KodeeAgentPage() {
  const [configData, setConfigData] = useState<AgentConfigResponse | null>(null);
  const [toolsData, setToolsData] = useState<AgentToolsResponse | null>(null);
  const [auditData, setAuditData] = useState<AgentAuditResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [lastRefresh, setLastRefresh] = useState('');
  const [activePhase, setActivePhase] = useState(0);
  const [expandedGroup, setExpandedGroup] = useState<string | null>(null);
  const [view, setView] = useState<'overview' | 'tools' | 'audit'>('overview');
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  async function load() {
    setLoading(true);
    setError('');
    try {
      const [cfg, tools, audit] = await Promise.all([
        apiGet<AgentConfigResponse>('/platform/agent-config', DEFAULT_TENANT_ID),
        apiGet<AgentToolsResponse>('/platform/agent-tools', DEFAULT_TENANT_ID),
        apiGet<AgentAuditResponse>('/platform/agent-audit', DEFAULT_TENANT_ID),
      ]);
      setConfigData(cfg);
      setToolsData(tools);
      setAuditData(audit);
      setLastRefresh(new Date().toLocaleTimeString());
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : String(e));
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    load();
    intervalRef.current = setInterval(load, 60_000);
    return () => { if (intervalRef.current) clearInterval(intervalRef.current); };
   
  }, []);

  const phaseKeys = ['phase1', 'phase2', 'phase3'];
  const phases = configData?.phase_info
    ? phaseKeys.map(k => ({ key: k, ...configData.phase_info[k] }))
    : [
        { key: 'phase1', label: 'Internal Admin Agent',  status: 'current',  description: 'Read-only + reporting, 5ÔÇô10 safe tools, local LLM' },
        { key: 'phase2', label: 'Controlled Actions',    status: 'planned',  description: 'Write tools with confirmation UX + full audit logging' },
        { key: 'phase3', label: 'Full Kodee-Class',      status: 'planned',  description: 'MCP tool registry, multi-agent orchestration, 350+ actions' },
      ];

  const phaseIcons = ['­ƒî▒', 'ÔÜÖ´©Å', '­ƒÜÇ'];

  return (
    <div style={{ minHeight: '100vh', background: C.bg, color: C.text, fontFamily: 'system-ui, sans-serif', padding: '28px 20px', maxWidth: 1200, margin: '0 auto' }}>

      {/* ÔöÇÔöÇ Header ÔöÇÔöÇ */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 28, flexWrap: 'wrap', gap: 12 }}>
        <div>
          <div style={{ fontSize: 10, color: C.muted, textTransform: 'uppercase', letterSpacing: 2, marginBottom: 6 }}>Platform ┬À AI Infrastructure</div>
