                          <div style={{ display: 'flex', alignItems: 'flex-start', gap: 12, justifyContent: 'space-between', flexWrap: 'wrap' }}>
                            <div>
                              <div style={{ fontSize: 13, fontWeight: 700, color: C.text, marginBottom: 2 }}>{t.display_name}</div>
                              <code style={{ fontSize: 10, color, fontFamily: 'monospace' }}>{t.fn_signature}</code>
                              {t.description && <div style={{ fontSize: 11, color: C.muted, marginTop: 4 }}>{t.description}</div>}
                              {t.backend_endpoint && (
                                <div style={{ fontSize: 10, color: C.muted, marginTop: 3 }}>
                                  ÔåÆ <code style={{ color: C.cyan }}>{t.backend_endpoint}</code>
                                </div>
                              )}
                            </div>
                            <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap', alignItems: 'center' }}>
                              <span style={{
                                fontSize: 9, fontWeight: 800, padding: '3px 8px', borderRadius: 5,
                                background: RISK_COLOR[t.risk_level] + '18', color: RISK_COLOR[t.risk_level],
                                border: `1px solid ${RISK_COLOR[t.risk_level]}33`,
                              }}>RISK: {RISK_LABEL[t.risk_level]}</span>
                              {t.requires_confirmation && (
                                <span style={{ fontSize: 9, color: C.amber, border: `1px solid ${C.amber}33`, borderRadius: 5, padding: '3px 8px', background: C.amber + '10' }}>ÔÜá Confirm</span>
                              )}
                              <span style={{ fontSize: 9, color: t.is_active ? C.green : C.red }}>{t.is_active ? 'Ô£ô Active' : 'Ô£ù Off'}</span>
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* ÔöÇÔöÇ AUDIT TAB ÔöÇÔöÇ */}
      {view === 'audit' && (
        <div>
          {auditData && (
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(130px, 1fr))', gap: 10, marginBottom: 20 }}>
              <StatBox label="Total Calls"  value={auditData.total_calls}   color={C.blue} />
              <StatBox label="Successful"   value={auditData.success_count} color={C.green} />
              <StatBox label="Errors"       value={auditData.error_count}   color={auditData.error_count > 0 ? C.red : C.muted} />
            </div>
          )}

          <Card>
            <SectionTitle sub="Every tool invocation ÔÇö who, what, when">Tool Call Audit Log</SectionTitle>
            {auditData && auditData.calls.length === 0 ? (
              <div style={{ textAlign: 'center', color: C.muted, padding: 40, fontSize: 13 }}>
                No tool calls recorded yet. Start an agent session to generate audit entries.
              </div>
            ) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                {(auditData?.calls ?? []).map((call, i) => {
                  const statusColor = call.status === 'success' ? C.green : call.status === 'error' ? C.red : call.status === 'pending' ? C.amber : C.muted;
                  return (
                    <div key={`item-${i}`} style={{ display: 'grid', gridTemplateColumns: '160px 100px 80px 80px 1fr', gap: 12, alignItems: 'center', padding: '10px 14px', background: C.card2, border: `1px solid ${C.border}`, borderRadius: 8 }}>
                      <code style={{ fontSize: 11, color: C.cyan }}>{call.tool_key}</code>
                      <span style={{ fontSize: 10, fontWeight: 700, color: statusColor, textTransform: 'uppercase' }}>{call.status}</span>
                      <span style={{ fontSize: 10, color: RISK_COLOR[call.risk_level] ?? C.muted }}>{RISK_LABEL[call.risk_level] ?? '-'} risk</span>
                      <span style={{ fontSize: 10, color: C.muted }}>{call.agent_role ?? '-'}</span>
                      <span style={{ fontSize: 10, color: C.muted }}>{call.created_at ? new Date(call.created_at).toLocaleTimeString() : '-'}</span>
                    </div>
                  );
                })}
              </div>
            )}
          </Card>
        </div>
      )}

      {/* ÔöÇÔöÇ Footer ÔöÇÔöÇ */}
      <div style={{ borderTop: `1px solid ${C.border}`, paddingTop: 16, marginTop: 28, display: 'flex', justifyContent: 'space-between', flexWrap: 'wrap', gap: 8 }}>
        <div style={{ fontSize: 10, color: C.muted }}>
          Kodee-Class AI Agent ┬À MCP + AutoGen + LangChain + DeepSeek R1 + FastAPI + Next.js ┬À 100% Open Source
        </div>
        {lastRefresh && <div style={{ fontSize: 10, color: C.muted }}>Refreshed {lastRefresh} ┬À auto 60s</div>}
      </div>
    </div>
  );
}

