'use client';

import { useCallback, useEffect, useState } from 'react';
import {
  adsApi,
  AdsCampaign,
  AdsPlatform,
  PLATFORM_LABELS,
  BestTimeRecommendation,
  AudienceInsights,
  AbTestSuggestions,
} from '../../lib/ads-api';

// ÔöÇÔöÇÔöÇ Constants ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
const PLATFORMS: AdsPlatform[] = [
  'google_ads', 'microsoft_ads', 'amazon_ads', 'apple_search_ads', 'youtube_ads',
];
const OBJECTIVES = ['conversions', 'brand_awareness', 'traffic'];
const DAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const HOURS = Array.from({ length: 24 }, (_, i) => i);

// ÔöÇÔöÇÔöÇ Helpers ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
function scoreColor(score: number): string {
  if (score === 0) return '#111827';
  if (score < 40) return '#1c2a1c';
  if (score < 60) return '#14532d';
  if (score < 75) return '#166534';
  if (score < 85) return '#15803d';
  if (score < 93) return '#16a34a';
  return '#22c55e';
}

function fmtHour(h: number): string {
  if (h === 0) return '12a';
  if (h < 12) return `${h}a`;
  if (h === 12) return '12p';
  return `${h - 12}p`;
}

function fmtReach(n: number): string {
  if (n >= 1_000_000_000) return `${(n / 1_000_000_000).toFixed(1)}B`;
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(0)}M`;
  return n.toLocaleString();
}

function hourLabelColor(h: number, humanWindow: number[], avoidHours: number[]): string {
  if (humanWindow.includes(h)) return '#60a5fa';
  if (avoidHours.includes(h)) return '#ef4444';
  return '#64748b';
}

function cellBorder(isHuman: boolean, isAvoid: boolean): string {
  if (isHuman) return '1px solid #3b82f6';
  if (isAvoid) return '1px solid #991b1b';
  return '1px solid transparent';
}

// ÔöÇÔöÇÔöÇ Sub-components ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
function Section({ title, children }: Readonly<{ title: string; children: React.ReactNode }>) {
  return (
    <section style={{ marginBottom: 32 }}>
      <h2 style={{ fontSize: 16, fontWeight: 800, marginBottom: 14, color: '#e2e8f0', borderBottom: '1px solid #1e293b', paddingBottom: 8 }}>
        {title}
      </h2>
      {children}
    </section>
  );
}

function HeatmapGrid({ heatmap, humanWindow, avoidHours }: Readonly<{
  heatmap: Record<string, Record<string, number>>;
  humanWindow: number[];
  avoidHours: number[];
}>) {
  return (
    <div style={{ overflowX: 'auto' }}>
      <div style={{ display: 'grid', gridTemplateColumns: `56px repeat(24, 26px)`, gap: 2, marginBottom: 2 }}>
        <div />
        {HOURS.map((h) => (
          <div key={h} style={{ fontSize: 9, textAlign: 'center', fontWeight: humanWindow.includes(h) ? 800 : 400, color: hourLabelColor(h, humanWindow, avoidHours) }}>
            {fmtHour(h)}
          </div>
        ))}
      </div>
      {DAYS.map((day) => {
        const dayData = heatmap[day] ?? {};
        return (
          <div key={day} style={{ display: 'grid', gridTemplateColumns: `56px repeat(24, 26px)`, gap: 2, marginBottom: 2 }}>
            <div style={{ fontSize: 11, color: '#94a3b8', display: 'flex', alignItems: 'center' }}>{day}</div>
            {HOURS.map((h) => {
              const score = dayData[String(h)] ?? 0;
              const isHuman = humanWindow.includes(h);
              const isAvoid = avoidHours.includes(h);
              return (
                <div
                  key={h}
                  title={score > 0 ? `${day} ${fmtHour(h)}: score ${score}` : `${day} ${fmtHour(h)}: low activity`}
                  style={{
                    height: 20,
                    borderRadius: 3,
                    background: scoreColor(score),
                      border: cellBorder(isHuman, isAvoid),
                    opacity: isAvoid && score === 0 ? 0.3 : 1,
                  }}
                />
              );
            })}
          </div>
        );
      })}
      <div style={{ display: 'flex', gap: 12, alignItems: 'center', marginTop: 10, fontSize: 10, flexWrap: 'wrap' }}>
        <span style={{ color: '#64748b' }}>Low</span>
        {[0, 30, 55, 72, 85, 93].map((s) => (
          <div key={s} style={{ width: 14, height: 14, borderRadius: 3, background: scoreColor(s), border: '1px solid #333' }} />
        ))}
        <span style={{ color: '#64748b' }}>High</span>
        <span style={{ width: 1, background: '#334155', height: 14, display: 'inline-block', margin: '0 6px' }} />
        <div style={{ width: 14, height: 14, borderRadius: 3, background: '#1c3a5e', border: '1px solid #3b82f6' }} />
        <span style={{ color: '#60a5fa' }}>Human review window</span>
        <div style={{ width: 14, height: 14, borderRadius: 3, background: '#1c1010', border: '1px solid #991b1b' }} />
        <span style={{ color: '#ef4444' }}>Avoid</span>
      </div>
    </div>
  );
}

function ApprovalBadge({ status }: Readonly<{ status: string | null | undefined }>) {
  if (!status) return null;
  const cfg: Record<string, { label: string; color: string }> = {
    pending_approval: { label: 'Pending Review', color: '#f59e0b' },
    approved: { label: 'Approved', color: '#22c55e' },
    rejected: { label: 'Rejected', color: '#ef4444' },
  };
  const c = cfg[status];
  if (!c) return null;
  return (
    <span style={{ borderRadius: 999, padding: '2px 8px', fontSize: 10, fontWeight: 700, background: `${c.color}22`, color: c.color, border: `1px solid ${c.color}55` }}>
      {c.label}
    </span>
  );
}

// ÔöÇÔöÇÔöÇ Main Page ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
export default function SmartSchedulePage() {
  const [platform, setPlatform] = useState<AdsPlatform>('google_ads');
  const [objective, setObjective] = useState('conversions');
  const [bestTime, setBestTime] = useState<BestTimeRecommendation | null>(null);
  const [loadingBT, setLoadingBT] = useState(false);

  const [campaigns, setCampaigns] = useState<AdsCampaign[]>([]);
  const [insights, setInsights] = useState<AudienceInsights | null>(null);
  const [abData, setAbData] = useState<AbTestSuggestions | null>(null);
  const [selectedCampaign, setSelectedCampaign] = useState('');
  const [loadingAb, setLoadingAb] = useState(false);

  // Approval form state
  const [approvalTarget, setApprovalTarget] = useState<string | null>(null);
  const [approvalEmail, setApprovalEmail] = useState('');
  const [approvalMsg, setApprovalMsg] = useState('');
  const [autoPublish, setAutoPublish] = useState(true);
  const [approvalSaving, setApprovalSaving] = useState(false);

  // Decide form state
  const [decideTarget, setDecideTarget] = useState<string | null>(null);
  const [decideReason, setDecideReason] = useState('');
  const [decideName, setDecideName] = useState('');
  const [decideSaving, setDecideSaving] = useState(false);

  const [error, setError] = useState('');
  const [info, setInfo] = useState('');

  const loadBestTime = useCallback(async () => {
    setLoadingBT(true);
    setError('');
    try {
      const res = await adsApi.bestTime(platform, objective);
      setBestTime(res);
    } catch {
      setError('Failed to load best time data.');
    } finally {
      setLoadingBT(false);
    }
  }, [platform, objective]);

  useEffect(() => {
    void loadBestTime();
  }, [loadBestTime]);

  useEffect(() => {
    async function loadSidePanels() {
      try {
        const [cRes, insRes] = await Promise.all([
          adsApi.listCampaigns(),
          adsApi.audienceInsights(),
        ]);
        setCampaigns(cRes.campaigns);
        setInsights(insRes);
        if (cRes.campaigns.length > 0) {
          setSelectedCampaign(cRes.campaigns[0].id);
        }
      } catch {
        /* non-critical */
      }
    }
    void loadSidePanels();
  }, []);

  async function loadAbTest(id: string) {
    setLoadingAb(true);
    setAbData(null);
    try {
      const res = await adsApi.abTestSuggestions(id);
      setAbData(res);
    } catch {
      setError('Failed to load A/B suggestions.');
    } finally {
      setLoadingAb(false);
    }
  }

  async function handleRequestApproval(campaignId: string) {
    if (!approvalEmail.trim()) { setError('Reviewer email is required.'); return; }
    setApprovalSaving(true);
    setError('');
    try {
      const res = await adsApi.requestApproval(campaignId, {
        reviewer_email: approvalEmail,
        message: approvalMsg,
        auto_publish_on_approve: autoPublish,
      });
      setCampaigns((prev) => prev.map((c) => c.id === campaignId ? res.campaign : c));
      setApprovalTarget(null);
      setApprovalEmail('');
      setApprovalMsg('');
      setInfo(`Approval request sent to ${approvalEmail}`);
    } catch {
      setError('Failed to send approval request.');
    } finally {
      setApprovalSaving(false);
    }
  }

  async function handleDecide(campaignId: string, decision: 'approved' | 'rejected') {
    setDecideSaving(true);
    setError('');
    try {
      const res = await adsApi.approveOrReject(campaignId, {
        decision,
        reason: decideReason,
        reviewer_name: decideName || 'Reviewer',
      });
      setCampaigns((prev) => prev.map((c) => c.id === campaignId ? res.campaign : c));
      setDecideTarget(null);
      setDecideReason('');
      setDecideName('');
      setInfo(`Campaign ${decision}.`);
    } catch {
      setError(`Failed to ${decision} campaign.`);
    } finally {
      setDecideSaving(false);
    }
  }

  const pending = campaigns.filter((c) => c.approval_status === 'pending_approval');

  return (
    <main style={{ padding: '28px 32px', maxWidth: 1180, margin: '0 auto', fontFamily: 'inherit', color: '#e2e8f0' }}>
      <h1 style={{ fontSize: 26, fontWeight: 900, marginBottom: 4 }}>Smart Schedule &amp; Approval</h1>
      <p style={{ color: '#64748b', marginBottom: 28, fontSize: 14 }}>
        Best-time heatmap ┬À Human touch windows ┬À Approval workflow ┬À A/B creative testing ┬À Audience insights
      </p>

      {error && <div style={{ background: '#7f1d1d', color: '#fca5a5', borderRadius: 10, padding: '10px 16px', marginBottom: 14, fontSize: 13 }}>{error}</div>}
      {info && <div style={{ background: '#052e16', color: '#86efac', borderRadius: 10, padding: '10px 16px', marginBottom: 14, fontSize: 13 }}>{info}</div>}

      {/* ÔöÇÔöÇ Best Time Heatmap ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */}
      <Section title="Best Time to Run Ads">
        <div style={{ display: 'flex', gap: 12, marginBottom: 16, flexWrap: 'wrap' }}>
          <div>
            <label htmlFor="bt-platform" style={{ fontSize: 11, color: '#64748b', display: 'block', marginBottom: 4 }}>Platform</label>
            <select
              id="bt-platform"
              value={platform}
              onChange={(e) => setPlatform(e.target.value as AdsPlatform)}
              style={{ background: '#1e293b', border: '1px solid #334155', borderRadius: 8, color: '#e2e8f0', padding: '6px 10px', fontSize: 13 }}
            >
              {PLATFORMS.map((p) => (
                <option key={p} value={p}>{PLATFORM_LABELS[p]}</option>
              ))}
            </select>
          </div>
          <div>
            <label htmlFor="bt-objective" style={{ fontSize: 11, color: '#64748b', display: 'block', marginBottom: 4 }}>Objective</label>
            <select
              id="bt-objective"
              value={objective}
              onChange={(e) => setObjective(e.target.value)}
              style={{ background: '#1e293b', border: '1px solid #334155', borderRadius: 8, color: '#e2e8f0', padding: '6px 10px', fontSize: 13 }}
            >
              {OBJECTIVES.map((o) => (
                <option key={o} value={o}>{o.replace('_', ' ')}</option>
              ))}
            </select>
          </div>
        </div>

        {loadingBT && <div style={{ color: '#64748b', fontSize: 13 }}>Loading heatmapÔÇª</div>}
        {bestTime && !loadingBT && (
          <>
            <HeatmapGrid
              heatmap={bestTime.heatmap}
              humanWindow={bestTime.human_review_window}
              avoidHours={bestTime.avoid_hours}
            />
            <div style={{ marginTop: 14, display: 'flex', gap: 16, flexWrap: 'wrap' }}>
              <div style={{ background: '#0f172a', border: '1px solid #1e293b', borderRadius: 10, padding: '10px 16px', flex: 1, minWidth: 200 }}>
                <div style={{ fontSize: 10, color: '#64748b', textTransform: 'uppercase', letterSpacing: '0.06em' }}>Peak Hour</div>
                <div style={{ fontSize: 22, fontWeight: 900, color: '#22c55e' }}>{fmtHour(bestTime.peak_hour)}</div>
                <div style={{ fontSize: 11, color: '#64748b' }}>across {bestTime.best_days.join(', ')}</div>
              </div>
              <div style={{ background: '#0f172a', border: '1px solid #1e293b', borderRadius: 10, padding: '10px 16px', flex: 1, minWidth: 200 }}>
                <div style={{ fontSize: 10, color: '#64748b', textTransform: 'uppercase', letterSpacing: '0.06em' }}>Human Review Window</div>
                <div style={{ fontSize: 18, fontWeight: 800, color: '#60a5fa' }}>
                  {bestTime.human_review_window.map(fmtHour).join(' ÔÇô ')}
                </div>
                <div style={{ fontSize: 11, color: '#64748b' }}>Schedule human check-in here</div>
              </div>
              <div style={{ background: '#0f172a', border: '1px solid #1e293b', borderRadius: 10, padding: '10px 16px', flex: 2, minWidth: 240 }}>
                <div style={{ fontSize: 10, color: '#64748b', textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: 4 }}>AI Rationale</div>
                <div style={{ fontSize: 12, color: '#94a3b8', lineHeight: 1.5 }}>{bestTime.rationale}</div>
              </div>
            </div>
            <div style={{ marginTop: 12, padding: '10px 14px', background: '#0f172a', borderRadius: 10, border: '1px solid #1e293b', fontSize: 12 }}>
              <span style={{ color: '#64748b', marginRight: 8 }}>Peak hour per platform:</span>
              {Object.entries(bestTime.all_platforms_peak).map(([p, h]) => (
                <span key={p} style={{ marginRight: 12, color: '#e2e8f0' }}>
                  <span style={{ color: '#64748b' }}>{PLATFORM_LABELS[p as AdsPlatform] ?? p}: </span>
                  <strong>{fmtHour(h)}</strong>
                </span>
              ))}
            </div>
          </>
        )}
      </Section>

      {/* ÔöÇÔöÇ Human Approval Queue ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */}
      {/* eslint-disable-next-line sonarjs/no-nested-template-literals */}
      <Section title={pending.length > 0 ? `Approval Queue (${pending.length})` : 'Approval Queue'}>
        {pending.length === 0 && (
          <div style={{ color: '#64748b', fontSize: 13, padding: '10px 0' }}>No campaigns pending review.</div>
        )}
        {pending.map((c) => (
          <div key={c.id} style={{ background: '#0f172a', border: '1px solid #334155', borderRadius: 12, padding: '14px 18px', marginBottom: 10 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 8 }}>
              <div>
                <span style={{ fontWeight: 800, fontSize: 15 }}>{c.campaign_name}</span>
                <span style={{ fontSize: 12, color: '#64748b', marginLeft: 10 }}>{PLATFORM_LABELS[c.platform]}</span>
                {c.reviewer_email && (
                  <span style={{ fontSize: 11, color: '#94a3b8', marginLeft: 10 }}>ÔåÆ {c.reviewer_email}</span>
                )}
              </div>
              <div style={{ display: 'flex', gap: 8 }}>
                <button
                  type="button"
                  onClick={() => { setDecideTarget(c.id); }}
                  style={{ padding: '6px 14px', borderRadius: 8, background: '#1e3a5f', border: '1px solid #3b82f6', color: '#93c5fd', fontSize: 12, fontWeight: 700, cursor: 'pointer' }}
                >
                  Review
                </button>
              </div>
            </div>
            {c.approval_message && (
              <div style={{ marginTop: 8, fontSize: 12, color: '#64748b', fontStyle: 'italic' }}>"{c.approval_message}"</div>
            )}
            {decideTarget === c.id && (
              <div style={{ marginTop: 12, padding: '12px 14px', background: '#111827', borderRadius: 10, border: '1px solid #1e293b' }}>
                <div style={{ display: 'flex', gap: 10, marginBottom: 10, flexWrap: 'wrap' }}>
                  <input
                    placeholder="Your name"
                    value={decideName}
                    onChange={(e) => setDecideName(e.target.value)}
                    style={{ flex: 1, minWidth: 140, background: '#1e293b', border: '1px solid #334155', borderRadius: 8, color: '#e2e8f0', padding: '6px 10px', fontSize: 12 }}
                  />
                  <input
                    placeholder="Reason / notes (optional)"
                    value={decideReason}
                    onChange={(e) => setDecideReason(e.target.value)}
                    style={{ flex: 2, minWidth: 200, background: '#1e293b', border: '1px solid #334155', borderRadius: 8, color: '#e2e8f0', padding: '6px 10px', fontSize: 12 }}
                  />
                </div>
                <div style={{ display: 'flex', gap: 8 }}>
                  <button
                    type="button"
                    disabled={decideSaving}
                    onClick={() => void handleDecide(c.id, 'approved')}
                    style={{ padding: '6px 16px', borderRadius: 8, background: '#14532d', border: '1px solid #22c55e', color: '#86efac', fontSize: 12, fontWeight: 700, cursor: 'pointer' }}
                  >
                    {decideSaving ? 'ÔÇª' : 'Approve'}
                  </button>
                  <button
                    type="button"
                    disabled={decideSaving}
                    onClick={() => void handleDecide(c.id, 'rejected')}
                    style={{ padding: '6px 16px', borderRadius: 8, background: '#7f1d1d', border: '1px solid #ef4444', color: '#fca5a5', fontSize: 12, fontWeight: 700, cursor: 'pointer' }}
                  >
                    {decideSaving ? 'ÔÇª' : 'Reject'}
                  </button>
                  <button
                    type="button"
                    onClick={() => setDecideTarget(null)}
                    style={{ padding: '6px 12px', borderRadius: 8, background: 'transparent', border: '1px solid #334155', color: '#64748b', fontSize: 12, cursor: 'pointer' }}
                  >
                    Cancel
                  </button>
                </div>
              </div>
            )}
          </div>
        ))}

        {/* Request approval for any campaign */}
        <div style={{ marginTop: 16 }}>
          <div style={{ fontSize: 12, color: '#64748b', marginBottom: 8 }}>Send a campaign for human review:</div>
          <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap' }}>
            <select
              value={approvalTarget ?? ''}
              onChange={(e) => setApprovalTarget(e.target.value || null)}
              style={{ background: '#1e293b', border: '1px solid #334155', borderRadius: 8, color: '#e2e8f0', padding: '6px 10px', fontSize: 12, flex: 1, minWidth: 160 }}
            >
              <option value="">ÔÇö Select campaign ÔÇö</option>
              {campaigns.filter((c) => c.approval_status !== 'pending_approval').map((c) => (
                <option key={c.id} value={c.id}>{c.campaign_name}</option>
              ))}
            </select>
            {approvalTarget && (
              <>
                <input
                  placeholder="Reviewer email"
                  value={approvalEmail}
                  onChange={(e) => setApprovalEmail(e.target.value)}
                  style={{ flex: 1, minWidth: 180, background: '#1e293b', border: '1px solid #334155', borderRadius: 8, color: '#e2e8f0', padding: '6px 10px', fontSize: 12 }}
                />
                <input
                  placeholder="Message (optional)"
                  value={approvalMsg}
                  onChange={(e) => setApprovalMsg(e.target.value)}
                  style={{ flex: 2, minWidth: 180, background: '#1e293b', border: '1px solid #334155', borderRadius: 8, color: '#e2e8f0', padding: '6px 10px', fontSize: 12 }}
                />
                <label style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 12, color: '#94a3b8', cursor: 'pointer' }}>
                  <input
                    type="checkbox"
                    checked={autoPublish}
                    onChange={(e) => setAutoPublish(e.target.checked)}
                  />{' '}
                  Auto-publish on approve
                </label>
                <button
                  type="button"
                  disabled={approvalSaving}
                  onClick={() => void handleRequestApproval(approvalTarget)}
                  style={{ padding: '6px 14px', borderRadius: 8, background: '#1e3a5f', border: '1px solid #3b82f6', color: '#93c5fd', fontSize: 12, fontWeight: 700, cursor: 'pointer' }}
                >
                  {approvalSaving ? 'SendingÔÇª' : 'Send for Review'}
                </button>
              </>
            )}
          </div>
        </div>
      </Section>

      {/* ÔöÇÔöÇ A/B Creative Test ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */}
      <Section title="A/B Creative Suggestions">
        <div style={{ display: 'flex', gap: 10, marginBottom: 14, flexWrap: 'wrap', alignItems: 'flex-end' }}>
          <div>
            <label htmlFor="ab-campaign" style={{ fontSize: 11, color: '#64748b', display: 'block', marginBottom: 4 }}>Campaign</label>
            <select
              id="ab-campaign"
              value={selectedCampaign}
              onChange={(e) => setSelectedCampaign(e.target.value)}
              style={{ background: '#1e293b', border: '1px solid #334155', borderRadius: 8, color: '#e2e8f0', padding: '6px 10px', fontSize: 12, minWidth: 200 }}
            >
              <option value="">ÔÇö Select ÔÇö</option>
              {campaigns.map((c) => (
                <option key={c.id} value={c.id}>{c.campaign_name}</option>
              ))}
            </select>
          </div>
          <button
            type="button"
            disabled={!selectedCampaign || loadingAb}
            onClick={() => selectedCampaign && void loadAbTest(selectedCampaign)}
            style={{ padding: '7px 16px', borderRadius: 8, background: '#1e293b', border: '1px solid #334155', color: '#e2e8f0', fontSize: 12, fontWeight: 700, cursor: 'pointer' }}
          >
            {loadingAb ? 'GeneratingÔÇª' : 'Generate Variants'}
          </button>
        </div>

        {abData && (
          <div>
            <div style={{ marginBottom: 10, padding: '10px 14px', background: '#0f172a', borderRadius: 10, border: '1px solid #1e293b', fontSize: 12 }}>
              <span style={{ color: '#64748b' }}>Original: </span>
              <strong>{abData.original.title}</strong>
              <span style={{ color: '#64748b', marginLeft: 10 }}>CTA: </span>{abData.original.cta}
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))', gap: 10 }}>
              {abData.suggestions.map((v) => (
                <div key={v.variant} style={{ background: '#0f172a', border: '1px solid #1e293b', borderRadius: 12, padding: '12px 14px' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
                    <span style={{ fontWeight: 800, fontSize: 13, color: '#60a5fa' }}>Variant {v.variant}</span>
                    <span style={{ fontSize: 10, color: '#94a3b8' }}>{v.label}</span>
                    <span style={{ fontSize: 11, fontWeight: 800, color: '#22c55e' }}>+{v.predicted_ctr_lift_pct}% CTR</span>
                  </div>
                  <div style={{ fontSize: 13, fontWeight: 700, marginBottom: 4 }}>{v.title}</div>
                  <div style={{ fontSize: 11, color: '#94a3b8', marginBottom: 6, lineHeight: 1.4 }}>{v.description}</div>
                  <div style={{ fontSize: 11, color: '#60a5fa' }}>CTA: {v.cta}</div>
                  <div style={{ fontSize: 10, color: '#475569', marginTop: 6, lineHeight: 1.4 }}>{v.rationale}</div>
                </div>
              ))}
            </div>
          </div>
        )}
      </Section>

      {/* ÔöÇÔöÇ Audience Insights ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */}
      <Section title="Audience Insights">
        {!insights && <div style={{ color: '#64748b', fontSize: 13 }}>Loading insightsÔÇª</div>}
        {insights && (
          <div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(170px, 1fr))', gap: 10, marginBottom: 14 }}>
              {[
                { label: 'Est. Total Reach', value: fmtReach(insights.estimated_reach), color: '#22c55e' },
                { label: 'Audience Overlap', value: `${insights.audience_overlap_pct}%`, color: insights.audience_overlap_pct > 60 ? '#f59e0b' : '#22c55e' },
                { label: 'Keyword Saturation', value: `${insights.keyword_saturation_score}/100`, color: insights.keyword_saturation_score > 70 ? '#ef4444' : '#22c55e' },
                { label: 'Keywords Indexed', value: String(insights.keywords_indexed), color: '#e2e8f0' },
                { label: 'Freq Cap Suggestion', value: `${insights.frequency_cap_suggestion}├ù/day`, color: '#e2e8f0' },
                { label: 'Active Platforms', value: String(insights.platforms_active.length), color: '#e2e8f0' },
              ].map((kpi) => (
                <div key={kpi.label} style={{ background: '#0f172a', border: '1px solid #1e293b', borderRadius: 10, padding: '10px 14px', textAlign: 'center' }}>
                  <div style={{ fontSize: 10, color: '#64748b', textTransform: 'uppercase', letterSpacing: '0.06em' }}>{kpi.label}</div>
                  <div style={{ fontSize: 20, fontWeight: 900, color: kpi.color, marginTop: 4 }}>{kpi.value}</div>
                </div>
              ))}
            </div>
            {insights.top_keywords.length > 0 && (
              <div style={{ marginBottom: 12 }}>
                <span style={{ fontSize: 11, color: '#64748b', marginRight: 8 }}>Top keywords:</span>
                {insights.top_keywords.map((kw) => (
                  <span key={kw} style={{ display: 'inline-block', margin: '2px 4px', padding: '2px 8px', borderRadius: 999, background: '#1e293b', border: '1px solid #334155', fontSize: 11, color: '#94a3b8' }}>{kw}</span>
                ))}
              </div>
            )}
            <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
              {insights.recommendations.map((rec, i) => (
                <div key={rec.slice(0, 40)} style={{ display: 'flex', gap: 10, alignItems: 'flex-start', padding: '8px 12px', background: '#0f172a', borderRadius: 8, border: '1px solid #1e293b', fontSize: 12 }}>
                  <span style={{ color: '#f59e0b', fontWeight: 800, flexShrink: 0 }}>ÔÜí</span>
