      </Section>

      {/* ÔöÇÔöÇ Campaign Approval Status Overview ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */}
      <Section title="Campaign Approval Status">
        {campaigns.filter((c) => c.approval_status).length === 0 && (
          <div style={{ color: '#64748b', fontSize: 13 }}>No campaigns have been submitted for approval yet.</div>
        )}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
          {campaigns.filter((c) => c.approval_status).map((c) => (
            <div key={c.id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '10px 14px', background: '#0f172a', borderRadius: 10, border: '1px solid #1e293b', flexWrap: 'wrap', gap: 8 }}>
              <div>
                <span style={{ fontWeight: 700, fontSize: 14 }}>{c.campaign_name}</span>
                <span style={{ fontSize: 11, color: '#64748b', marginLeft: 10 }}>{PLATFORM_LABELS[c.platform]}</span>
              </div>
              <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
                <ApprovalBadge status={c.approval_status} />
                {c.approver_name && <span style={{ fontSize: 11, color: '#64748b' }}>by {c.approver_name}</span>}
                {c.approval_reason && <span style={{ fontSize: 11, color: '#64748b', fontStyle: 'italic' }}>"{c.approval_reason}"</span>}
              </div>
            </div>
          ))}
        </div>
      </Section>
    </main>
  );
}

"use client";

import { useState } from "react";

interface StyleViolation {
  type: string;
  text: string;
  suggestion: string;
}

interface Change {
  original: string;
  rewritten: string;
  reason: string;
}

interface BrandVoiceResult {
  analysis_id: string;
  brand_alignment_score: number;
  tone_analysis: { detected_tone: string; target_tone: string; alignment_pct: number };
  rewritten_content: string;
  changes: Change[];
  style_violations: StyleViolation[];
  seo_preservation: { keywords_retained: boolean; density_unchanged: boolean; meta_impact: string };
  quick_wins: string[];
  recommended_tools: string[];
  brand_name: string;
  tone: string;
  rewritten_at: string;
}

const TONES = ["professional", "friendly", "authoritative", "conversational", "playful", "empathetic", "bold"];

export default function BrandVoicePage() {
  const [content, setContent] = useState("");
  const [brandName, setBrandName] = useState("");
  const [tone, setTone] = useState("professional");
  const [targetAudience, setTargetAudience] = useState("");
  const [notes, setNotes] = useState("");
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<BrandVoiceResult | null>(null);
  const [error, setError] = useState("");
  const [activeTab, setActiveTab] = useState<"rewritten" | "changes">("rewritten");

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setLoading(true);
    setError("");
    setResult(null);
    try {
      const res = await fetch("/api/fastapi/seo-platform/brand-voice/rewrite", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ content, brand_name: brandName, tone, target_audience: targetAudience, notes }),
      });
      if (!res.ok) throw new Error(`Error ${res.status}: ${res.statusText}`);
      setResult(await res.json());
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : "Request failed");
    } finally {
      setLoading(false);
    }
  }

  const score = result?.brand_alignment_score ?? 0;
  const scoreColor = score >= 80 ? "text-green-600" : score >= 60 ? "text-yellow-600" : "text-red-600";

  return (
    <div className="max-w-4xl mx-auto p-6 space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-gray-900">Brand Voice & Style Engine</h1>
        <p className="text-gray-500 mt-1">Brand-consistent rewriting and tone governance for SEO content.</p>
      </div>

      <form onSubmit={handleSubmit} className="bg-white rounded-xl border border-gray-200 p-6 space-y-4">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Content to Rewrite *</label>
          <textarea
            value={content}
            onChange={(e) => setContent(e.target.value)}
            rows={8}
            placeholder="Paste the content you want to rewrite in your brand voice..."
            className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
            required
          />
        </div>
        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Brand Name</label>
            <input
              type="text"
              value={brandName}
              onChange={(e) => setBrandName(e.target.value)}
              placeholder="e.g. Nuxtron AI"
              className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Target Audience</label>
            <input
              type="text"
              value={targetAudience}
              onChange={(e) => setTargetAudience(e.target.value)}
              placeholder="e.g. B2B marketers, startup founders"
              className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">Target Tone</label>
          <div className="flex flex-wrap gap-2">
            {TONES.map((t) => (
              <button
                key={t}
                type="button"
                onClick={() => setTone(t)}
                className={`px-3 py-1 rounded-full text-xs font-medium border transition-colors capitalize ${
                  tone === t
                    ? "bg-blue-600 text-white border-blue-600"
                    : "bg-white text-gray-600 border-gray-300 hover:border-blue-400"
                }`}
              >
                {t}
              </button>
            ))}
          </div>
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Notes</label>
          <textarea
            value={notes}
            onChange={(e) => setNotes(e.target.value)}
            rows={2}
            placeholder="Style guidelines, brand keywords to preserve..."
            className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
        </div>
        <button
          type="submit"
          disabled={loading || !content}
          className="w-full bg-blue-600 text-white py-2 px-4 rounded-lg text-sm font-medium hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
        >
          {loading ? "RewritingÔÇª" : "Rewrite in Brand Voice"}
        </button>
      </form>

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-700 rounded-lg px-4 py-3 text-sm">{error}</div>
      )}

      {result && (
        <div className="space-y-4">
          {/* Score + Tone Analysis */}
          <div className="bg-white rounded-xl border border-gray-200 p-6 flex items-center gap-8">
            <div className="text-center">
              <div className={`text-4xl font-bold ${scoreColor}`}>{score}</div>
              <div className="text-xs text-gray-500 mt-1">Brand Alignment</div>
            </div>
            <div className="flex-1 space-y-2">
              <div className="flex items-center gap-2 text-sm">
                <span className="text-gray-500 w-32">Detected Tone:</span>
                <span className="font-medium text-gray-800 capitalize">{result.tone_analysis.detected_tone}</span>
              </div>
              <div className="flex items-center gap-2 text-sm">
                <span className="text-gray-500 w-32">Target Tone:</span>
                <span className="font-medium text-blue-600 capitalize">{result.tone_analysis.target_tone}</span>
              </div>
              <div>
                <div className="flex justify-between text-xs text-gray-500 mb-1">
                  <span>Alignment</span>
                  <span>{result.tone_analysis.alignment_pct}%</span>
                </div>
                <div className="h-2 bg-gray-200 rounded-full">
                  <div
                    className={`h-2 rounded-full ${result.tone_analysis.alignment_pct >= 80 ? "bg-green-500" : result.tone_analysis.alignment_pct >= 60 ? "bg-yellow-500" : "bg-red-500"}`}
                    style={{ width: `${result.tone_analysis.alignment_pct}%` }}
                  />
                </div>
              </div>
            </div>
            <div className="space-y-1 text-center">
              <div className={`text-sm font-medium ${result.seo_preservation.keywords_retained ? "text-green-600" : "text-red-600"}`}>
                {result.seo_preservation.keywords_retained ? "Ô£ô" : "Ô£ù"} Keywords Retained
              </div>
              <div className={`text-sm font-medium ${result.seo_preservation.density_unchanged ? "text-green-600" : "text-orange-600"}`}>
                {result.seo_preservation.density_unchanged ? "Ô£ô" : "~"} Density Unchanged
              </div>
              <div className="text-xs text-gray-500">SEO Impact: {result.seo_preservation.meta_impact}</div>
            </div>
          </div>

          {/* Rewritten Content / Changes Tabs */}
          <div className="bg-white rounded-xl border border-gray-200 p-6">
            <div className="flex border-b border-gray-200 mb-4">
              <button
                onClick={() => setActiveTab("rewritten")}
                className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${activeTab === "rewritten" ? "border-blue-600 text-blue-600" : "border-transparent text-gray-500 hover:text-gray-700"}`}
              >
                Rewritten Content
              </button>
              <button
                onClick={() => setActiveTab("changes")}
                className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${activeTab === "changes" ? "border-blue-600 text-blue-600" : "border-transparent text-gray-500 hover:text-gray-700"}`}
              >
                Changes Made ({result.changes.length})
              </button>
            </div>
            {activeTab === "rewritten" ? (
              <div className="bg-gray-50 rounded-lg p-4 text-sm text-gray-800 whitespace-pre-wrap leading-relaxed">
                {result.rewritten_content}
              </div>
            ) : (
              <div className="space-y-4">
                {result.changes.map((c, i) => (
                  <div key={`item-${i}`} className="border border-gray-200 rounded-lg overflow-hidden">
                    <div className="bg-red-50 px-3 py-2 border-b border-gray-200">
                      <span className="text-xs text-red-400 font-medium">Before</span>
                      <p className="text-sm text-red-700 mt-0.5">{c.original}</p>
                    </div>
                    <div className="bg-green-50 px-3 py-2 border-b border-gray-200">
                      <span className="text-xs text-green-400 font-medium">After</span>
                      <p className="text-sm text-green-700 mt-0.5">{c.rewritten}</p>
                    </div>
                    <div className="px-3 py-2 bg-gray-50">
                      <p className="text-xs text-gray-500">Reason: {c.reason}</p>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Style Violations */}
          {result.style_violations.length > 0 && (
            <div className="bg-white rounded-xl border border-gray-200 p-6">
              <h2 className="text-base font-semibold text-gray-800 mb-3">Style Violations ({result.style_violations.length})</h2>
              <div className="space-y-3">
                {result.style_violations.map((v, i) => (
                  <div key={`item-${i}`} className="flex items-start gap-3 text-sm">
                    <span className="text-xs bg-orange-100 text-orange-700 px-2 py-0.5 rounded font-mono whitespace-nowrap mt-0.5">{v.type}</span>
                    <div>
                      <span className="line-through text-gray-400 mr-2">"{v.text}"</span>
                      <span className="text-green-600">ÔåÆ "{v.suggestion}"</span>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Quick Wins */}
          <div className="bg-green-50 rounded-xl border border-green-200 p-6">
            <h2 className="text-base font-semibold text-green-800 mb-3">Quick Wins</h2>
            <ul className="space-y-2">
              {result.quick_wins.map((w, i) => (
                <li key={`item-${i}`} className="flex items-start gap-2 text-sm text-green-700"><span className="mt-0.5">Ô£ô</span>{w}</li>
              ))}
            </ul>
          </div>

          <p className="text-xs text-gray-400 text-right">
            Rewritten: {new Date(result.rewritten_at).toLocaleString()} ┬À ID: {result.analysis_id.slice(0, 8)}
          </p>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState } from 'react';
import { apiSend, DEFAULT_TENANT_ID } from '../../lib/platform-api';

export default function EEATPage() {
  const [content, setContent] = useState('');
  const [authorBio, setAuthorBio] = useState('');
  const [domain, setDomain] = useState('');
  const [niche, setNiche] = useState('');
  const [result, setResult] = useState<Record<string, unknown> | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  async function run() {
    if (!content) { setError('Content is required.'); return; }
    setLoading(true); setError('');
    try {
      const data = await apiSend<Record<string, unknown>>(
        '/seo-platform/eeat/score', 'POST',
        { content, author_bio: authorBio, domain, niche },
        DEFAULT_TENANT_ID,
      );
      setResult(data);
    } catch (e) { setError(e instanceof Error ? e.message : 'E-E-A-T scoring failed'); }
    finally { setLoading(false); }
  }

  const card = { background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 16, marginBottom: 16 };
  const inp = { width: '100%', padding: '8px 10px', borderRadius: 8, border: '1px solid var(--line)', background: 'var(--bg)', color: 'var(--text)', marginBottom: 10, boxSizing: 'border-box' as const };
