            </div>
            <div>
              <label style={{ display: 'block', fontSize: 12, fontWeight: 600, marginBottom: 4 }}>Niche / Industry</label>
              <input style={inp} value={niche} onChange={e => setNiche(e.target.value)} placeholder="e.g. personal finance, health, SaaS" />
            </div>
          </div>
          <label style={{ display: 'block', fontSize: 12, fontWeight: 600, marginBottom: 4 }}>Author Bio (optional)</label>
          <textarea style={{ ...inp, minHeight: 60 }} value={authorBio} onChange={e => setAuthorBio(e.target.value)} placeholder="Jane Doe is a CPA with 15 years experience in corporate finance..." />
          <label style={{ display: 'block', fontSize: 12, fontWeight: 600, marginBottom: 4 }}>Content to Score</label>
          <textarea style={{ ...inp, minHeight: 180 }} value={content} onChange={e => setContent(e.target.value)} placeholder="Paste your article or page content here..." />
          <button onClick={run} disabled={loading}
            style={{ padding: '8px 16px', borderRadius: 8, border: 'none', background: 'var(--brand)', color: '#00101e', fontWeight: 700, cursor: 'pointer', opacity: loading ? 0.7 : 1 }}>
            {loading ? 'Scoring E-E-A-TÔÇª' : 'Score E-E-A-T'}
          </button>
                  {loading && (
                    <div style={{ marginTop: 12, padding: '10px 14px', borderRadius: 8, background: 'rgba(27,199,255,0.08)', border: '1px solid rgba(27,199,255,0.2)', fontSize: 13, color: 'var(--muted)' }}>
                      ÔÅ│ AI is scoring your content ÔÇö this typically takes 20ÔÇô40 s on local inference. Please waitÔÇª
                    </div>
                  )}
        </section>
        {result && (
          <>
            <section style={{ ...card, display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', gap: 10 }}>
              <div style={{ background: 'var(--bg)', borderRadius: 8, padding: '12px 14px', border: '1px solid var(--line)', textAlign: 'center' }}>
                <div style={{ fontSize: 10, color: 'var(--muted)' }}>E-E-A-T Score</div>
                <div style={{ fontSize: 28, fontWeight: 800, color: (result.eeat_score as number) >= 80 ? '#22c55e' : (result.eeat_score as number) >= 60 ? '#f59e0b' : '#ef4444' }}>{result.eeat_score as number ?? 'ÔÇö'}</div>
              </div>
              {DIMS.map(d => (
                <div key={d.key} style={{ background: 'var(--bg)', borderRadius: 8, padding: '12px 14px', border: '1px solid var(--line)', textAlign: 'center' }}>
                  <div style={{ fontSize: 10, color: 'var(--muted)' }}>{d.label}</div>
                  <div style={{ fontSize: 22, fontWeight: 800 }}>{result[d.key] as number ?? 'ÔÇö'}</div>
                  <div style={{ background: 'var(--line)', borderRadius: 4, height: 4, marginTop: 6 }}>
                    <div style={{ width: `${result[d.key] as number ?? 0}%`, height: '100%', background: '#a78bfa', borderRadius: 4 }} />
                  </div>
                </div>
              ))}
            </section>
            {(result.critical_gaps as string[] | undefined)?.length ? (
              <section style={card}>
                <p style={{ fontSize: 14, fontWeight: 700, marginTop: 0, marginBottom: 12, color: '#ef4444' }}>­ƒÜ¿ Critical Gaps</p>
                <ul style={{ margin: 0, paddingLeft: 20 }}>
