function DonutChart({ slices, size = 130 }: Readonly<{ slices: Array<{ label: string; value: number; color: string }>; size?: number }>) {
  const total = slices.reduce((s, sl) => s + sl.value, 0) || 1;
  const cx = size / 2; const cy = size / 2;
  const r = size / 2 - 8; const inner = r * 0.55;
  let cumAngle = -Math.PI / 2;
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
      {slices.map(sl => {
        const sweep = (sl.value / total) * Math.PI * 2;
        const a0 = cumAngle;
        cumAngle += sweep;
        const x1 = cx + r * Math.cos(a0); const y1 = cy + r * Math.sin(a0);
        const x2 = cx + r * Math.cos(cumAngle); const y2 = cy + r * Math.sin(cumAngle);
        const xi1 = cx + inner * Math.cos(a0); const yi1 = cy + inner * Math.sin(a0);
        const xi2 = cx + inner * Math.cos(cumAngle); const yi2 = cy + inner * Math.sin(cumAngle);
        const large = sweep > Math.PI ? 1 : 0;
        const d = `M ${x1.toFixed(1)} ${y1.toFixed(1)} A ${r} ${r} 0 ${large} 1 ${x2.toFixed(1)} ${y2.toFixed(1)} L ${xi2.toFixed(1)} ${yi2.toFixed(1)} A ${inner} ${inner} 0 ${large} 0 ${xi1.toFixed(1)} ${yi1.toFixed(1)} Z`;
        return <path key={sl.label} d={d} fill={sl.color} opacity={0.88} />;
      })}
      <text x={cx} y={cy} textAnchor="middle" dominantBaseline="middle" fontSize={8} fill="var(--muted)">
        {slices.length} seg
      </text>
    </svg>
  );
}

function AreaChart({ points, width = 380, height = 72, color = '#3b82f6', labels }: Readonly<{ points: number[]; width?: number; height?: number; color?: string; labels?: string[] }>) {
  if (points.length < 2) return null;
  const mn = Math.min(...points); const mx = Math.max(...points); const rng = mx - mn || 1;
  const px = 8; const py = 10;
  const xs = (i: number) => ((i / (points.length - 1)) * (width - px * 2) + px).toFixed(1);
  const ys = (v: number) => (height - py - ((v - mn) / rng) * (height - py * 2)).toFixed(1);
  const linePts = points.map((v, i) => `${xs(i)},${ys(v)}`).join(' ');
  const gradId = `ag${color.replaceAll(/[^0-9a-z]/gi, '')}`;
  return (
    <svg width="100%" viewBox={`0 0 ${width} ${height}`} style={{ display: 'block' }}>
      <defs>
        <linearGradient id={gradId} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={color} stopOpacity={0.3} />
          <stop offset="100%" stopColor={color} stopOpacity={0.02} />
        </linearGradient>
      </defs>
      <path d={`M ${px},${height - py} L ${linePts} L ${width - px},${height - py} Z`} fill={`url(#${gradId})`} />
      <polyline points={linePts} fill="none" stroke={color} strokeWidth={1.5} />
      {points.map((v, i) => (
        <circle key={`pt-${xs(i)}-${ys(v)}`} cx={xs(i)} cy={ys(v)} r={3} fill={color} />
      ))}
    </svg>
  );
}

function MiniBarChart({ items }: Readonly<{ items: Array<{ label: string; value: number; color?: string; max?: number; suffix?: string }> }>) {
  const globalMax = Math.max(...items.map(it => it.max ?? it.value), 1);
