              <div style={{ width: `${((it.value) / (it.max ?? globalMax)) * 100}%`, height: '100%', background: col, borderRadius: 3 }} />
            </div>
            <div style={{ width: 60, fontWeight: 700, textAlign: 'right', color: col, fontSize: 11 }}>{it.value.toLocaleString()}{it.suffix ?? ''}</div>
          </div>
        );
      })}
    </div>
  );
}

function LatencyPercentileBar({ p50 = 0, p75 = 0, p95 = 0, p99 = 0, unit = 'ms', threshold = 0 }: Readonly<{ p50?: number; p75?: number; p95?: number; p99?: number; unit?: string; threshold?: number }>) {
  const mx = Math.max(p99, threshold * 1.1, 1);
  const bars = [
    { label: 'p50', value: p50, color: '#22c55e' },
    { label: 'p75', value: p75, color: '#f59e0b' },
    { label: 'p95', value: p95, color: '#f97316' },
    { label: 'p99', value: p99, color: '#ef4444' },
  ];
  return (
    <div style={{ display: 'grid', gap: 5 }}>
      {bars.map(b => (
        <div key={b.label} style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 11 }}>
          <div style={{ width: 22, fontWeight: 800, color: b.color }}>{b.label}</div>
          <div style={{ flex: 1, height: 10, background: 'var(--line)', borderRadius: 3, overflow: 'hidden', position: 'relative' }}>
            <div style={{ width: `${(b.value / mx) * 100}%`, height: '100%', background: b.color, borderRadius: 3 }} />
