        <div style={{ fontSize: 12, color: 'var(--muted)', marginTop: 12 }}>No suite data available.</div>
      </section>
    );
  }

  return (
    <section style={{ display: 'grid', gap: 12 }}>
      <div style={panel}>
        <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 12, flexWrap: 'wrap' }}>
          <div>
            <div style={{ fontWeight: 700, fontSize: 14 }}>{title}</div>
            <div style={{ fontSize: 12, color: 'var(--muted)', marginTop: 4 }}>{subtitle}</div>
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, minmax(110px, 1fr))', gap: 8 }}>
            <div style={{ textAlign: 'center' }}>
              <div style={{ fontSize: 10, color: 'var(--muted)' }}>Score</div>
              <div style={{ fontWeight: 800, fontSize: 22 }}>{suite.overview_score ?? 0}</div>
            </div>
            <div style={{ textAlign: 'center' }}>
              <div style={{ fontSize: 10, color: 'var(--muted)' }}>Coverage</div>
              <div style={{ fontWeight: 800, fontSize: 22 }}>{suite.coverage ?? 0}%</div>
            </div>
            <div style={{ textAlign: 'center' }}>
              <div style={{ fontSize: 10, color: 'var(--muted)' }}>Opportunities</div>
              <div style={{ fontWeight: 800, fontSize: 22 }}>{suite.opportunity_count ?? 0}</div>
            </div>
          </div>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: 12 }}>
        {(suite.distribution ?? []).length > 0 && (
          <div style={panel}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 8 }}>Coverage Mix</div>
            <div style={{ display: 'flex', gap: 12, alignItems: 'center' }}>
              <DonutChart
                slices={(suite.distribution ?? []).map(slice => ({
                  label: slice.label ?? 'slice',
                  value: slice.value ?? 0,
                  color: slice.color ?? '#3b82f6',
                }))}
                size={116}
              />
              <div style={{ display: 'grid', gap: 6, flex: 1 }}>
                {(suite.distribution ?? []).map(slice => (
                  <div key={`${slice.label ?? 'slice'}-${slice.value ?? 0}`} style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 12 }}>
                    <div style={{ width: 8, height: 8, borderRadius: '50%', background: slice.color ?? '#3b82f6', flexShrink: 0 }} />
                    <span style={{ color: 'var(--muted)', flex: 1 }}>{slice.label}</span>
                    <strong>{slice.value}%</strong>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {(suite.timeline ?? []).length > 1 && (
          <div style={panel}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 8 }}>Readiness Trend</div>
            <AreaChart
              points={(suite.timeline ?? []).map(point => point.value ?? 0)}
              labels={(suite.timeline ?? []).map(point => point.label ?? '')}
              color="#3b82f6"
              height={82}
            />
          </div>
        )}
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: 12 }}>
        {(suite.highlights ?? []).length > 0 && (
          <div style={panel}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 8 }}>Highlights</div>
            <div style={{ display: 'grid', gap: 7 }}>
              {(suite.highlights ?? []).map(item => (
                <div key={item} style={{ fontSize: 12 }}>{item}</div>
              ))}
            </div>
          </div>
        )}
        {(suite.risks ?? []).length > 0 && (
          <div style={panel}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 8 }}>Risks</div>
            <div style={{ display: 'grid', gap: 7 }}>
              {(suite.risks ?? []).map(item => (
                <div key={item} style={{ fontSize: 12, color: '#f59e0b' }}>{item}</div>
              ))}
            </div>
          </div>
        )}
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: 12 }}>
        {(suite.modules ?? []).map(module => (
          <div key={module.name ?? 'module'} style={panel}>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 10, marginBottom: 8 }}>
              <div style={{ fontWeight: 700, fontSize: 13 }}>{module.name}</div>
              <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                {typeof module.score === 'number' && <strong style={{ fontSize: 12 }}>{module.score}</strong>}
                {module.tier && (
                  <span style={{ background: tierColor(module.tier), color: '#fff', borderRadius: 999, padding: '2px 8px', fontSize: 10, fontWeight: 700 }}>
                    {module.tier}
                  </span>
                )}
                <span style={{ background: suiteReadinessColor(module.status), color: '#fff', borderRadius: 999, padding: '2px 8px', fontSize: 10, fontWeight: 700 }}>{module.status}</span>
              </div>
            </div>
            <div style={{ fontSize: 12, color: 'var(--muted)', marginBottom: 10 }}>{module.summary}</div>

            {(module.metrics ?? []).length > 0 && (
              <div style={{ display: 'grid', gap: 6, marginBottom: 10 }}>
                {(module.metrics ?? []).map(metric => (
                  <div key={`${module.name ?? 'module'}-${metric.label ?? 'metric'}`} style={{ display: 'flex', justifyContent: 'space-between', fontSize: 11, gap: 8 }}>
                    <span style={{ color: 'var(--muted)' }}>{metric.label}</span>
                    <strong>{metric.value}</strong>
                  </div>
                ))}
              </div>
            )}

            {(module.automations ?? []).length > 0 && (
              <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap', marginBottom: 10 }}>
                {(module.automations ?? []).map(item => (
                  <span key={`${module.name ?? 'module'}-${item}`} style={{ border: '1px solid var(--line)', borderRadius: 999, padding: '2px 8px', fontSize: 10, color: '#3b82f6' }}>{item}</span>
                ))}
              </div>
            )}

            {(module.issues ?? []).length > 0 && (
              <div style={{ display: 'grid', gap: 5 }}>
                {(module.issues ?? []).map(issue => (
                  <div key={`${module.name ?? 'module'}-${issue}`} style={{ fontSize: 11, color: '#f59e0b' }}>- {issue}</div>
                ))}
              </div>
            )}
          </div>
        ))}
      </div>
    </section>
  );
}

// ÔöÇÔöÇÔöÇ Main Page ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

type Tab = 'summary' | 'waterfall' | 'filmstrip' | 'rum' | 'causality' | 'agents' | 'prediction' | 'global' | 'business' | 'ci-gate' | 'slo' | 'roi' | 'copilot' | 'opportunities' | 'ai-fixes' | 'images' | 'security' | 'javascript' | 'css' | 'input-validation' | 'latency' | 'outdated' | 'workflow' | 'data-analysis' | 'core-seo' | 'content-blogging' | 'ai-optimization' | 'search-experience' | 'vertical-seo' | 'platform-ops' | 'accessibility' | 'competitor-intel' | 'schema-entities' | 'technical-deep' | 'trust-revenue' | 'ux-conversion' | 'growth-landing' | 'live-intelligence' | 'history' | 'monitoring' | 'keywords' | 'seo-ranking' | 'ai-models-ranking' | 'hashtags' | 'visibility' | 'leads' | 'clicks' | 'trends-vs-platform' | 'power-ranking' | 'autonomous';



