        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
          {(result.recommended_stack ?? []).map(item => (
            <span key={item} style={{ fontSize: 12, borderRadius: 999, padding: '5px 12px', background: 'var(--bg)', border: '1px solid var(--line)' }}>{item}</span>
          ))}
        </div>
      </section>
