function WaterfallTab({ result, card, isOfflinePreview }: PerfTabProps) {
  return (
  <section style={{ display: 'grid', gap: 12 }}>
    {/* KPI strip */}
    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(150px, 1fr))', gap: 10 }}>
      {[
        { label: 'Total Requests', value: String(result.waterfall?.requests ?? 84), color: 'var(--text)' },
        { label: 'Total Size', value: `${result.waterfall?.transfer_kb ?? 2340} KB`, color: '#f59e0b' },
        { label: 'TTFB', value: `${result.waterfall?.timeline_ms?.ttfb ?? 210}ms`, color: (result.waterfall?.timeline_ms?.ttfb ?? 210) > 600 ? '#ef4444' : '#22c55e' },
        { label: 'Time to Interactive', value: '3,400ms', color: '#f59e0b' },
        { label: 'Blocking Assets', value: String(result.waterfall?.render_blocking?.length ?? 7), color: '#ef4444' },
        { label: 'Cached Requests', value: '38%', color: '#6366f1' },
        { label: 'Compression Ratio', value: '3.2├ù', color: '#22c55e' },
      ].map(kpi => (
        <div key={kpi.label} style={card}>
          <div style={{ fontSize: 11, color: 'var(--muted)' }}>{kpi.label}</div>
          <div style={{ fontWeight: 800, fontSize: 18, color: kpi.color, marginTop: 4 }}>{kpi.value}</div>
        </div>
      ))}
    </div>

    {/* Request type breakdown */}
    <div style={card}>
      <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Request Type Breakdown</div>
      <MiniBarChart items={[
        { label: 'JavaScript', value: 28, color: '#f59e0b', max: result.waterfall?.requests ?? 84, suffix: ' reqs' },
        { label: 'CSS', value: 12, color: '#6366f1', max: result.waterfall?.requests ?? 84, suffix: ' reqs' },
        { label: 'Images', value: 31, color: '#22c55e', max: result.waterfall?.requests ?? 84, suffix: ' reqs' },
        { label: 'Fonts', value: 6, color: '#3b82f6', max: result.waterfall?.requests ?? 84, suffix: ' reqs' },
        { label: 'API / XHR', value: 7, color: '#ec4899', max: result.waterfall?.requests ?? 84, suffix: ' reqs' },
      ]} />
    </div>

    {/* Timing phases */}
    <div style={card}>
      <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Connection Timing Phases</div>
      <div style={{ display: 'grid', gap: 8 }}>
        {[
          { phase: 'DNS Lookup', ms: result.waterfall?.timeline_ms?.dns ?? 18, color: '#6366f1', tip: 'Use DNS prefetch for 3rd-party origins' },
          { phase: 'TCP Connect', ms: result.waterfall?.timeline_ms?.tcp ?? 42, color: '#3b82f6', tip: 'Enable HTTP/2 multiplexing' },
          { phase: 'SSL Handshake', ms: result.waterfall?.timeline_ms?.tls ?? 78, color: '#f59e0b', tip: 'TLS 1.3 reduces handshake to 1-RTT' },
          { phase: 'TTFB', ms: result.waterfall?.timeline_ms?.ttfb ?? 210, color: '#ef4444', tip: 'Server response time ÔÇö consider edge caching' },
          { phase: 'Content Download', ms: result.waterfall?.timeline_ms?.download ?? 320, color: '#22c55e', tip: 'Reduce payload with compression + splitting' },
          { phase: 'DOM Processing', ms: 890, color: '#ec4899', tip: 'Defer non-critical JS to unblock parsing' },
        ].map(p => {
          const maxMs = 1200;
          const w = Math.min(100, Math.round((p.ms / maxMs) * 100));
          return (
            <div key={p.phase}>
              <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12, marginBottom: 3 }}>
                <span style={{ fontWeight: 600 }}>{p.phase}</span>
                <span style={{ color: p.color, fontWeight: 700 }}>{p.ms}ms</span>
              </div>
              <div style={{ height: 8, background: 'var(--line)', borderRadius: 4, overflow: 'hidden', marginBottom: 2 }}>
                <div style={{ width: `${w}%`, height: '100%', background: p.color, borderRadius: 4 }} />
              </div>
              <div style={{ fontSize: 10, color: 'var(--muted)' }}>{p.tip}</div>
            </div>
          );
        })}
      </div>
    </div>

    {/* Waterfall chart */}
    <div style={card}>
      <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Timeline Waterfall</div>
      {result.waterfall?.timeline_ms ? (
        <WaterfallBars timeline={result.waterfall.timeline_ms} />
      ) : (
        <div style={{ display: 'grid', gap: 4 }}>
          {[
            { name: '/index.html', start: 0, dur: 228, type: 'document', size: '12 KB' },
            { name: '/main.bundle.js', start: 228, dur: 680, type: 'script', size: '420 KB' },
            { name: '/styles.css', start: 228, dur: 180, type: 'style', size: '84 KB' },
            { name: '/hero.avif', start: 408, dur: 340, type: 'image', size: '198 KB' },
            { name: '/fonts/inter.woff2', start: 450, dur: 220, type: 'font', size: '66 KB' },
            { name: 'cdn.analytics.io/track.js', start: 600, dur: 480, type: 'script', size: '38 KB' },
            { name: '/api/user', start: 908, dur: 190, type: 'xhr', size: '2 KB' },
            { name: '/thumbnail-1.webp', start: 700, dur: 260, type: 'image', size: '42 KB' },
            { name: '/chunk.vendor.js', start: 908, dur: 390, type: 'script', size: '210 KB' },
            { name: 'gtag/js', start: 1000, dur: 520, type: 'script', size: '28 KB' },
          ].map((r, i) => {
            const totalDur = 1520;
            const typeColor: Record<string, string> = { document: '#22c55e', script: '#ef4444', style: '#6366f1', image: '#3b82f6', font: '#f59e0b', xhr: '#ec4899' };
            const c = typeColor[r.type] ?? '#888';
            return (
              <div key={`wf-${i}`} style={{ display: 'grid', gridTemplateColumns: '200px 1fr 50px 60px', gap: 8, alignItems: 'center', fontSize: 11 }}>
                <div style={{ fontFamily: 'monospace', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', color: 'var(--muted)' }} title={r.name}>{r.name}</div>
                <div style={{ height: 12, background: 'var(--line)', borderRadius: 2, position: 'relative' }}>
                  <div style={{ position: 'absolute', left: `${(r.start / totalDur) * 100}%`, width: `${(r.dur / totalDur) * 100}%`, height: '100%', background: c, borderRadius: 2, opacity: r.type === 'script' ? 1 : 0.8 }} />
                </div>
                <div style={{ color: c, fontWeight: 700 }}>{r.dur}ms</div>
                <div style={{ color: 'var(--muted)' }}>{r.size}</div>
              </div>
            );
          })}
          <div style={{ display: 'flex', gap: 12, marginTop: 6, flexWrap: 'wrap' }}>
            {[['script','#ef4444'],['style','#6366f1'],['image','#3b82f6'],['font','#f59e0b'],['xhr','#ec4899'],['document','#22c55e']].map(([t,c]) => (
              <span key={t} style={{ fontSize: 10, display: 'flex', alignItems: 'center', gap: 4, color: 'var(--muted)' }}>
                <span style={{ width: 8, height: 8, borderRadius: 2, background: c, display: 'inline-block' }} />{t}
              </span>
            ))}
          </div>
        </div>
      )}
    </div>

    {/* Render-blocking assets */}
    {(result.waterfall?.render_blocking ?? ['main.bundle.js','chunk.vendor.js','styles-critical.css','gtag/js','cdn.analytics.io/track.js','fonts/inter.woff2','chunk.react.js']).length > 0 && (
      <div style={card}>
        <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 8 }}>
          Render-Blocking Assets{isOfflinePreview ? ' (sample)' : ''}
        </div>
        <div style={{ display: 'grid', gap: 6 }}>
          {(result.waterfall?.render_blocking ?? ['main.bundle.js','chunk.vendor.js','styles-critical.css','gtag/js','cdn.analytics.io/track.js','fonts/inter.woff2','chunk.react.js']).map((asset, i) => (
            <div
              key={`rb-${i}`}
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: 10,
                padding: '7px 12px',
                background: isOfflinePreview ? '#78350f33' : '#450a0a22',
                border: isOfflinePreview ? '1px solid #f59e0b55' : '1px solid #ef444444',
                borderRadius: 6,
                fontSize: 12,
              }}
            >
              <span style={{ color: isOfflinePreview ? '#f59e0b' : '#ef4444', fontWeight: 700, fontSize: 10 }}>
                {isOfflinePreview ? 'SAMPLE' : 'BLOCKING'}
              </span>
              <span style={{ flex: 1, fontFamily: 'monospace' }}>{asset}</span>
              <span style={{ color: 'var(--muted)', fontSize: 10 }}>
                {isOfflinePreview ? 'connect backend for live blockers' : 'add defer / preload'}
              </span>
            </div>
          ))}
        </div>
      </div>
    )}

    {/* Third-party impact */}
    <div style={card}>
      <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 8 }}>Third-Party Impact</div>
      <div style={{ overflowX: 'auto' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
          <thead><tr style={{ borderBottom: '1px solid var(--line)' }}>
            {['Origin', 'Reqs', 'Size', 'Blocking Time', 'Category'].map(h => (
              <th key={h} style={{ textAlign: 'left', padding: '6px 10px', fontSize: 10, color: 'var(--muted)', fontWeight: 600 }}>{h}</th>
            ))}
          </tr></thead>
          <tbody>
            {[
              { origin: 'googletagmanager.com', reqs: 4, size: '88 KB', block_ms: 320, cat: 'Analytics' },
              { origin: 'cdn.analytics.io', reqs: 2, size: '42 KB', block_ms: 480, cat: 'Analytics' },
              { origin: 'fonts.googleapis.com', reqs: 3, size: '66 KB', block_ms: 180, cat: 'Fonts' },
              { origin: 'cdn.intercom.io', reqs: 5, size: '124 KB', block_ms: 260, cat: 'Support' },
            ].map((r, i) => (
              <tr key={`tp-${i}`} style={{ borderBottom: '1px solid var(--line)' }}>
                <td style={{ padding: '7px 10px', fontFamily: 'monospace', fontSize: 11 }}>{r.origin}</td>
                <td style={{ padding: '7px 10px' }}>{r.reqs}</td>
                <td style={{ padding: '7px 10px' }}>{r.size}</td>
                <td style={{ padding: '7px 10px', color: r.block_ms > 300 ? '#ef4444' : '#f59e0b', fontWeight: 700 }}>{r.block_ms}ms</td>
                <td style={{ padding: '7px 10px' }}><span style={{ borderRadius: 999, padding: '2px 8px', background: 'var(--bg)', border: '1px solid var(--line)', fontSize: 10 }}>{r.cat}</span></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  </section>
  );
}


function FilmstripTab({ result, card, isOfflinePreview }: PerfTabProps) { // NOSONAR
  const fallbackFrames: FilmstripFrame[] = [
                  { label: 'navigation_start', timestamp_ms: 0, asset: 'synthetic-0' },
                  { label: 'first_paint', timestamp_ms: 420, asset: 'synthetic-1' },
                  { label: 'first_contentful_paint', timestamp_ms: 890, asset: 'synthetic-2' },
                  { label: 'largest_contentful_paint', timestamp_ms: 2210, asset: 'synthetic-3' },
                  { label: 'layout_stabilized', timestamp_ms: 2860, asset: 'synthetic-4' },
                  { label: 'visual_complete', timestamp_ms: 3340, asset: 'synthetic-5' },
                ];

                const rawFrames = (result.filmstrip ?? []).length > 0 ? (result.filmstrip ?? []) : fallbackFrames;
                const frames = [...rawFrames].sort((a, b) => (a.timestamp_ms ?? 0) - (b.timestamp_ms ?? 0));

                const visualCompleteMs = frames[frames.length - 1]?.timestamp_ms ?? 0;
                const firstPaintMs = frames.find(f => (f.label ?? '').toLowerCase().includes('first_paint'))?.timestamp_ms
                  ?? frames.find(f => (f.label ?? '').toLowerCase().includes('first'))?.timestamp_ms
                  ?? frames[1]?.timestamp_ms
                  ?? 0;
                const fcpMs = frames.find(f => (f.label ?? '').toLowerCase().includes('contentful'))?.timestamp_ms ?? firstPaintMs;
                const lcpMs = frames.find(f => (f.label ?? '').toLowerCase().includes('largest'))?.timestamp_ms
                  ?? frames.find(f => (f.label ?? '').toLowerCase().includes('hero'))?.timestamp_ms
                  ?? visualCompleteMs;

                const frameGaps = frames.slice(1).map((f, i) => Math.max(0, (f.timestamp_ms ?? 0) - (frames[i]?.timestamp_ms ?? 0)));
                const avgGapMs = frameGaps.length > 0
                  ? Math.round(frameGaps.reduce((sum, n) => sum + n, 0) / frameGaps.length)
                  : 0;
                const maxGapMs = frameGaps.length > 0 ? Math.max(...frameGaps) : 0;

                const speedIndexEstimate = Math.round(
                  frames.reduce((sum, f, i) => sum + (f.timestamp_ms ?? 0) * (i + 1), 0) / Math.max(1, frames.length * 2)
                );
                const completeness = Math.min(100, Math.round((lcpMs / Math.max(1, visualCompleteMs)) * 100));

                const timelinePoints = frames.map(f => Math.round(((f.timestamp_ms ?? 0) / Math.max(1, visualCompleteMs)) * 100));
                const timelineLabels = frames.map((_, i) => `F${i + 1}`);

                return (
                  <section style={{ display: 'grid', gap: 12 }}>
                    <div style={{ ...card, borderLeft: '4px solid #3b82f6', display: 'flex', justifyContent: 'space-between', gap: 12, flexWrap: 'wrap' }}>
                      <div>
                        <div style={{ fontWeight: 700, fontSize: 14 }}>Visual Render Filmstrip Intelligence</div>
                        <div style={{ fontSize: 12, color: 'var(--muted)', marginTop: 4 }}>
                          Frame-by-frame page rendering diagnostics with milestone extraction and pacing analysis.
                        </div>
                      </div>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                        <span style={badge(visualCompleteMs <= 3200 ? '#22c55e' : visualCompleteMs <= 4200 ? '#f59e0b' : '#ef4444')}>
                          {visualCompleteMs <= 3200 ? 'fast render' : visualCompleteMs <= 4200 ? 'needs tuning' : 'slow render'}
                        </span>
                      </div>
                    </div>

                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(150px, 1fr))', gap: 10 }}>
                      {[
                        { label: 'Frames Captured', value: String(frames.length), color: 'var(--text)' },
                        { label: 'First Paint', value: `${firstPaintMs}ms`, color: firstPaintMs <= 700 ? '#22c55e' : '#f59e0b' },
                        { label: 'FCP', value: `${fcpMs}ms`, color: fcpMs <= 1200 ? '#22c55e' : '#f59e0b' },
                        { label: 'LCP Visual', value: `${lcpMs}ms`, color: lcpMs <= 2500 ? '#22c55e' : '#ef4444' },
                        { label: 'Visual Complete', value: `${visualCompleteMs}ms`, color: visualCompleteMs <= 3200 ? '#22c55e' : '#ef4444' },
                        { label: 'Avg Frame Gap', value: `${avgGapMs}ms`, color: avgGapMs <= 400 ? '#22c55e' : '#f59e0b' },
                        { label: 'Max Gap', value: `${maxGapMs}ms`, color: maxGapMs <= 900 ? '#22c55e' : '#ef4444' },
                        { label: 'Speed Index Est.', value: `${speedIndexEstimate}`, color: '#6366f1' },
                      ].map(kpi => (
                        <div key={kpi.label} style={card}>
                          <div style={{ fontSize: 11, color: 'var(--muted)' }}>{kpi.label}</div>
                          <div style={{ fontWeight: 800, fontSize: 18, color: kpi.color, marginTop: 4 }}>{kpi.value}</div>
                        </div>
                      ))}
                    </div>

                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
                      <div style={card}>
                        <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Render Timeline Coverage</div>
                        <AreaChart points={timelinePoints} labels={timelineLabels} color="#3b82f6" height={70} />
                        <div style={{ marginTop: 8, fontSize: 12, color: 'var(--muted)' }}>
                          Above curve indicates how quickly visual completeness ramps up from first paint to final render.
                        </div>
                      </div>
                      <div style={card}>
                        <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Frame Cadence Breakdown</div>
                        <MiniBarChart items={frameGaps.map((gap, i) => ({
                          label: `F${i + 1} -> F${i + 2}`,
                          value: gap,
                          color: gap > 800 ? '#ef4444' : gap > 450 ? '#f59e0b' : '#22c55e',
                          max: Math.max(1, maxGapMs),
                          suffix: ' ms',
                        }))} />
                      </div>
                    </div>

                    <div style={card}>
                      <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Filmstrip Frames</div>
                      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(220px, 1fr))', gap: 12 }}>
                        {frames.map((frame, i) => {
                          const ts = frame.timestamp_ms ?? 0;
                          const progress = Math.max(0, Math.min(100, Math.round((ts / Math.max(1, visualCompleteMs)) * 100)));
                          const normalizedLabel = (frame.label ?? 'unknown').replace(/_/g, ' ');
                          return (
                            <div key={`${frame.label ?? 'frame'}-${i}`} style={{ ...card, padding: 12 }}>
                              <div style={{ width: '100%', marginBottom: 8, borderRadius: 6, overflow: 'hidden', border: '1px solid var(--line)' }}>
                                <FilmstripScreenshotSVG label={frame.label ?? ''} />
                              </div>
                              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 8 }}>
                                <div style={{ fontWeight: 700, fontSize: 12, textTransform: 'capitalize' }}>{normalizedLabel}</div>
                                <div style={{ fontSize: 11, color: 'var(--muted)' }}>{ts}ms</div>
                              </div>
                              <div style={{ height: 4, background: 'var(--line)', borderRadius: 2, marginTop: 8 }}>
                                <div style={{ width: `${progress}%`, height: '100%', background: progress >= completeness ? '#22c55e' : '#3b82f6', borderRadius: 2 }} />
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    </div>

                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
                      <div style={card}>
                        <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Milestone Timeline</div>
                        <div style={{ overflowX: 'auto' }}>
                          <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
                            <thead>
                              <tr style={{ borderBottom: '1px solid var(--line)' }}>
                                {['Milestone', 'Timestamp', 'Delta', 'Visual %'].map(h => (
                                  <th key={h} style={{ textAlign: 'left', padding: '6px 8px', fontSize: 10, color: 'var(--muted)', fontWeight: 600 }}>{h}</th>
                                ))}
                              </tr>
                            </thead>
                            <tbody>
                              {frames.map((frame, i) => {
                                const ts = frame.timestamp_ms ?? 0;
                                const prevTs = i > 0 ? (frames[i - 1]?.timestamp_ms ?? 0) : 0;
                                const delta = i === 0 ? 0 : Math.max(0, ts - prevTs);
                                const visualPct = Math.min(100, Math.round((ts / Math.max(1, visualCompleteMs)) * 100));
                                return (
                                  <tr key={`ms-${i}`} style={{ borderBottom: '1px solid var(--line)' }}>
                                    <td style={{ padding: '7px 8px', fontWeight: 600 }}>{(frame.label ?? 'unknown').replace(/_/g, ' ')}</td>
                                    <td style={{ padding: '7px 8px' }}>{ts}ms</td>
                                    <td style={{ padding: '7px 8px', color: delta > 800 ? '#ef4444' : delta > 450 ? '#f59e0b' : '#22c55e', fontWeight: 700 }}>
                                      {i === 0 ? '-' : `+${delta}ms`}
                                    </td>
                                    <td style={{ padding: '7px 8px' }}>{visualPct}%</td>
                                  </tr>
                                );
                              })}
                            </tbody>
                          </table>
                        </div>
                      </div>

                      <div style={card}>
                        <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Optimization Insights</div>
                        <div style={{ display: 'grid', gap: 8 }}>
                          {[
                            {
                              title: maxGapMs > 900 ? 'Large visual gap detected' : 'Frame pacing is mostly stable',
                              body: maxGapMs > 900
                                ? 'A large render idle window was detected. Investigate long tasks, blocking scripts, and hydration bursts.'
                                : 'No severe frame stalls detected in this capture window.',
                              tone: maxGapMs > 900 ? '#ef4444' : '#22c55e',
                            },
                            {
                              title: lcpMs > 2500 ? 'LCP visual milestone is late' : 'LCP visual milestone is healthy',
                              body: lcpMs > 2500
                                ? 'Prioritize hero asset compression and server response tuning to pull LCP earlier.'
                                : 'Largest visual element appears in an acceptable window.',
                              tone: lcpMs > 2500 ? '#f59e0b' : '#22c55e',
                            },
                            {
                              title: completeness < 75 ? 'Above-the-fold completion delayed' : 'Above-the-fold completion timing is good',
                              body: completeness < 75
                                ? 'Critical render path remains active for too long. Inline critical CSS and defer non-essential JS.'
                                : 'Above-the-fold visuals complete early in the timeline.',
                              tone: completeness < 75 ? '#f59e0b' : '#22c55e',
                            },
                          ].map((insight, i) => (
                            <div key={`fi-${i}`} style={{ border: '1px solid var(--line)', borderRadius: 8, padding: '10px 12px', background: 'var(--bg)' }}>
                              <div style={{ fontWeight: 700, fontSize: 12, color: insight.tone, marginBottom: 4 }}>{insight.title}</div>
                              <div style={{ fontSize: 12, color: 'var(--muted)' }}>{insight.body}</div>
                            </div>
                          ))}
                        </div>
                      </div>
                    </div>
                  </section>
                );
}


function RumTab({ result, card, isOfflinePreview }: PerfTabProps) {
  return (
  <section style={card}>
    <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 16 }}>Real User Monitoring Intelligence</div>
    {result.rum_summary ? (
      <>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(170px, 1fr))', gap: 10, marginBottom: 14 }}>
          <div style={card}><div style={{ color: 'var(--muted)', fontSize: 11 }}>Sessions</div><div style={{ fontWeight: 800, fontSize: 20 }}>{(result.rum_summary.sessions ?? 0).toLocaleString()}</div></div>
          <div style={card}><div style={{ color: 'var(--muted)', fontSize: 11 }}>Rage Click Rate</div><div style={{ fontWeight: 800, fontSize: 20 }}>{((result.rum_summary.rage_click_rate ?? 0) * 100).toFixed(2)}%</div></div>
          <div style={card}><div style={{ color: 'var(--muted)', fontSize: 11 }}>UX Friction Score</div><div style={{ fontWeight: 800, fontSize: 20 }}>{result.rum_summary.friction_score ?? 0}</div></div>
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: 12, marginBottom: 14 }}>
          <div style={card}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 8 }}>Device Mix</div>
            <div style={{ display: 'flex', gap: 12, alignItems: 'center' }}>
              <DonutChart slices={Object.entries(result.rum_summary.device_mix ?? {}).map(([k, v], i) => ({ label: k, value: v, color: DONUT_COLORS[i % DONUT_COLORS.length] }))} size={110} />
              <div style={{ display: 'grid', gap: 5, flex: 1 }}>
                {Object.entries(result.rum_summary.device_mix ?? {}).map(([k, v], i) => (
                  <div key={`item-${k}`} style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 12 }}>
                    <div style={{ width: 8, height: 8, borderRadius: '50%', background: DONUT_COLORS[i % DONUT_COLORS.length], flexShrink: 0 }} />
                    <span style={{ color: 'var(--muted)', flex: 1 }}>{k}</span>
                    <strong>{(v * 100).toFixed(1)}%</strong>
                  </div>
                ))}
              </div>
            </div>
          </div>

          <div style={card}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 8 }}>Network Mix</div>
            <div style={{ display: 'flex', gap: 12, alignItems: 'center' }}>
              <DonutChart slices={Object.entries(result.rum_summary.network_mix ?? {}).map(([k, v], i) => ({ label: k, value: v, color: NETWORK_COLORS[i % NETWORK_COLORS.length] }))} size={110} />
              <div style={{ display: 'grid', gap: 5, flex: 1 }}>
                {Object.entries(result.rum_summary.network_mix ?? {}).map(([k, v], i) => (
                  <div key={`item-${k}`} style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 12 }}>
                    <div style={{ width: 8, height: 8, borderRadius: '50%', background: NETWORK_COLORS[i % NETWORK_COLORS.length], flexShrink: 0 }} />
                    <span style={{ color: 'var(--muted)', flex: 1 }}>{k.toUpperCase()}</span>
                    <strong>{(v * 100).toFixed(1)}%</strong>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>

        <div>
          <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 8 }}>Geo + ISP Breakdown</div>
          {(result.rum_summary.geo_isp_breakdown ?? []).length === 0 ? (
            <div style={{ color: 'var(--muted)', fontSize: 12 }}>No geo/ISP breakdown captured.</div>
          ) : (
            <div style={{ display: 'grid', gap: 8 }}>
              {(result.rum_summary.geo_isp_breakdown ?? []).map((row, i) => (
                <div key={`${row.country}-${row.region}-${row.isp}-${i}`} style={{ ...card, padding: 10, display: 'grid', gridTemplateColumns: '1fr auto auto', gap: 10, alignItems: 'center' }}>
                  <div style={{ fontSize: 12 }}>
                    <strong>{row.country ?? 'n/a'}</strong>
                    <span style={{ color: 'var(--muted)' }}> / {row.region ?? 'n/a'} / {row.isp ?? 'n/a'}</span>
                  </div>
                  <div style={{ fontSize: 12 }}>LCP p75: <strong>{row.lcp_p75_ms ?? 0}ms</strong></div>
                  <div style={{ fontSize: 12, color: 'var(--muted)' }}>n={(row.sample_size ?? 0).toLocaleString()}</div>
                </div>
              ))}
            </div>
          )}
        </div>
      </>
    ) : (
      <div style={{ color: 'var(--muted)', fontSize: 12 }}>No RUM summary available for this audit run.</div>
    )}
  </section>
  );
}


function CausalityTab({ result, card, isOfflinePreview }: PerfTabProps) {
  return (
  <section style={card}>
    <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 4 }}>Performance Causality Graph</div>
    <div style={{ color: 'var(--muted)', fontSize: 12, marginBottom: 16 }}>Root-cause attribution for every millisecond of load delay, traced from network to paint.</div>

    {/* KPI row */}
    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(160px, 1fr))', gap: 10, marginBottom: 16 }}>
      <div style={card}><div style={{ color: 'var(--muted)', fontSize: 11 }}>Critical Path</div><div style={{ fontWeight: 800, fontSize: 22, color: '#ef4444' }}>{result.causality_graph?.critical_path_ms ?? 0}ms</div></div>
      <div style={card}><div style={{ color: 'var(--muted)', fontSize: 11 }}>Wasted Time</div><div style={{ fontWeight: 800, fontSize: 22, color: '#f59e0b' }}>{result.causality_graph?.wasted_ms ?? 0}ms</div></div>
      <div style={card}><div style={{ color: 'var(--muted)', fontSize: 11 }}>Blocking Assets</div><div style={{ fontWeight: 800, fontSize: 22 }}>{(result.causality_graph?.render_blocking_attribution ?? []).length}</div></div>
      <div style={card}><div style={{ color: 'var(--muted)', fontSize: 11 }}>3rd-party Scripts</div><div style={{ fontWeight: 800, fontSize: 22 }}>{(result.causality_graph?.third_party_impact ?? []).length}</div></div>
    </div>

    {/* Root causes */}
    <div style={{ ...card, marginBottom: 12 }}>
      <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 8 }}>Root Causes</div>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
        {(result.causality_graph?.root_causes ?? []).map((cause) => (
          <span key={cause} style={{ fontSize: 11, borderRadius: 999, padding: '5px 12px', background: '#7f1d1d22', color: '#fca5a5', border: '1px solid #ef444455' }}>ÔÜá {cause}</span>
        ))}
      </div>
    </div>

    {/* Main thread timeline */}
    {(result.causality_graph?.main_thread_timeline ?? []).length > 0 && (
      <div style={{ ...card, marginBottom: 12 }}>
        <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Main Thread Timeline</div>
        <MiniBarChart items={(result.causality_graph?.main_thread_timeline ?? []).map(t => ({
          label: t.task ?? '',
          value: t.duration_ms ?? 0,
          max: 500,
          suffix: 'ms',
          color: t.type === 'script' ? '#ef4444' : t.type === 'style' ? '#f59e0b' : t.type === 'render' ? '#22c55e' : '#6366f1',
        }))} />
        <div style={{ display: 'flex', gap: 12, marginTop: 8, fontSize: 11, color: 'var(--muted)', flexWrap: 'wrap' }}>
          {[['#ef4444','Script'],['#f59e0b','Style'],['#22c55e','Render'],['#6366f1','Parse']].map(([c,l]) => (
            <span key={l} style={{ display: 'flex', alignItems: 'center', gap: 4 }}><span style={{ width: 8, height: 8, borderRadius: 2, background: c, display: 'inline-block' }} />{l}</span>
          ))}
        </div>
      </div>
    )}

    {/* Render blocking + 3rd party side by side */}
    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))', gap: 12, marginBottom: 12 }}>
      <div style={card}>
        <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Render-blocking Attribution</div>
        <MiniBarChart items={(result.causality_graph?.render_blocking_attribution ?? []).map(x => ({
          label: x.asset ?? '',
          value: x.block_ms ?? 0,
          max: 400,
          suffix: 'ms',
          color: (x.severity === 'critical') ? '#ef4444' : (x.severity === 'high') ? '#f59e0b' : '#6366f1',
        }))} />
        <div style={{ marginTop: 8, display: 'grid', gap: 4 }}>
          {(result.causality_graph?.render_blocking_attribution ?? []).map((x, i) => (
            <div key={`rba-${i}`} style={{ display: 'flex', justifyContent: 'space-between', fontSize: 11 }}>
              <span style={{ color: 'var(--muted)' }}>{x.phase?.toUpperCase()}</span>
              <span style={{ borderRadius: 999, padding: '2px 8px', fontSize: 10, background: x.severity === 'critical' ? '#7f1d1d44' : x.severity === 'high' ? '#78350f44' : '#1e1b4b44', color: x.severity === 'critical' ? '#fca5a5' : x.severity === 'high' ? '#fcd34d' : '#a5b4fc' }}>{x.severity}</span>
            </div>
          ))}
        </div>
      </div>

      <div style={card}>
        <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Third-party Script Impact</div>
        <MiniBarChart items={(result.causality_graph?.third_party_impact ?? []).map(x => ({
          label: x.provider ?? '',
          value: (x.main_thread_block_ms ?? 0) + (x.network_ms ?? 0),
          max: 400,
          suffix: 'ms total',
          color: x.removable ? '#f59e0b' : '#6366f1',
        }))} />
        <div style={{ marginTop: 10, display: 'grid', gap: 6 }}>
          {(result.causality_graph?.third_party_impact ?? []).map((x, i) => (
            <div key={`tpi-${i}`} style={{ fontSize: 11, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <span><strong>{x.provider}</strong> <span style={{ color: 'var(--muted)' }}>({x.category})</span></span>
              <span style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
                <span style={{ color: 'var(--muted)' }}>MT: {x.main_thread_block_ms}ms ┬À Net: {x.network_ms}ms</span>
                {x.removable && <span style={{ borderRadius: 999, padding: '2px 7px', background: '#78350f44', color: '#fcd34d', fontSize: 10 }}>removable</span>}
              </span>
            </div>
          ))}
        </div>
      </div>
    </div>

    {/* Dependency chain */}
    <div style={card}>
      <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Dependency Chain</div>
      {(result.causality_graph?.dependencies ?? []).length === 0
        ? <div style={{ color: 'var(--muted)', fontSize: 12 }}>No dependency edges recorded.</div>
        : (
          <div style={{ display: 'grid', gap: 6 }}>
            {(result.causality_graph?.dependencies ?? []).map((edge, i) => (
              <div key={`dep-${i}`} style={{ fontSize: 12, display: 'flex', alignItems: 'center', gap: 10, flexWrap: 'wrap' }}>
                <code style={{ background: 'var(--bg)', padding: '2px 6px', borderRadius: 4, fontSize: 11 }}>{edge.from}</code>
                <span style={{ color: 'var(--muted)' }}>ÔåÆ {edge.latency_ms ?? 0}ms ÔåÆ</span>
                <code style={{ background: 'var(--bg)', padding: '2px 6px', borderRadius: 4, fontSize: 11 }}>{edge.to}</code>
              </div>
            ))}
          </div>
        )}
    </div>
  </section>
  );
}


function AgentsTab({ result, card, isOfflinePreview }: PerfTabProps) {
  return (
  <section style={card}>
    <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 4 }}>Autonomous Synthetic Agent Coverage</div>
    <div style={{ color: 'var(--muted)', fontSize: 12, marginBottom: 16 }}>Continuous multi-journey synthetic monitoring with scenario mutation testing across {(result.autonomous_agents?.scenario_mutations ?? 0)} permutations.</div>

    {/* KPI strip */}
    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(150px, 1fr))', gap: 10, marginBottom: 16 }}>
      <div style={card}><div style={{ color: 'var(--muted)', fontSize: 11 }}>Coverage Score</div><div style={{ fontWeight: 800, fontSize: 26, color: scoreColor(result.autonomous_agents?.coverage_score ?? 0) }}>{result.autonomous_agents?.coverage_score ?? 0}</div></div>
      <div style={card}><div style={{ color: 'var(--muted)', fontSize: 11 }}>Scenario Mutations</div><div style={{ fontWeight: 800, fontSize: 26 }}>{result.autonomous_agents?.scenario_mutations ?? 0}</div></div>
      <div style={card}><div style={{ color: 'var(--muted)', fontSize: 11 }}>Journeys</div><div style={{ fontWeight: 800, fontSize: 26 }}>{(result.autonomous_agents?.journeys_tested ?? []).length}</div></div>
      <div style={card}><div style={{ color: 'var(--muted)', fontSize: 11 }}>Healthy Agents</div><div style={{ fontWeight: 800, fontSize: 26, color: '#22c55e' }}>{result.autonomous_agents?.agent_health?.healthy ?? 0}<span style={{ fontSize: 13, color: 'var(--muted)' }}>/{result.autonomous_agents?.agent_health?.total_agents ?? 0}</span></div></div>
      <div style={card}><div style={{ color: 'var(--muted)', fontSize: 11 }}>Degraded</div><div style={{ fontWeight: 800, fontSize: 26, color: '#f59e0b' }}>{result.autonomous_agents?.agent_health?.degraded ?? 0}</div></div>
      <div style={card}><div style={{ color: 'var(--muted)', fontSize: 11 }}>Offline</div><div style={{ fontWeight: 800, fontSize: 26, color: '#ef4444' }}>{result.autonomous_agents?.agent_health?.offline ?? 0}</div></div>
    </div>

    {/* Per-journey metrics table */}
    <div style={{ ...card, marginBottom: 12 }}>
      <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Journey Performance Matrix</div>
      <div style={{ overflowX: 'auto' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
          <thead>
            <tr style={{ borderBottom: '1px solid var(--line)', color: 'var(--muted)', fontSize: 11 }}>
              {['Journey','P50','P75','P95','Pass Rate','Runs'].map(h => (
                <th key={h} style={{ padding: '6px 10px', textAlign: 'left', fontWeight: 600 }}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {(result.autonomous_agents?.journey_metrics ?? []).map((jm, i) => {
              const pass = (jm.pass_rate ?? 0) >= 0.9;
              return (
                <tr key={`jm-${i}`} style={{ borderBottom: '1px solid var(--line)' }}>
                  <td style={{ padding: '7px 10px', fontWeight: 600 }}>{jm.journey}</td>
                  <td style={{ padding: '7px 10px' }}>{jm.p50_ms}ms</td>
                  <td style={{ padding: '7px 10px' }}>{jm.p75_ms}ms</td>
                  <td style={{ padding: '7px 10px', color: (jm.p95_ms ?? 0) > 4000 ? '#ef4444' : (jm.p95_ms ?? 0) > 2500 ? '#f59e0b' : '#22c55e' }}><strong>{jm.p95_ms}ms</strong></td>
                  <td style={{ padding: '7px 10px' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                      <div style={{ flex: 1, height: 4, background: 'var(--line)', borderRadius: 2, overflow: 'hidden' }}>
                        <div style={{ width: `${(jm.pass_rate ?? 0) * 100}%`, height: '100%', background: pass ? '#22c55e' : '#ef4444', borderRadius: 2 }} />
                      </div>
                      <span style={{ color: pass ? '#22c55e' : '#ef4444', fontWeight: 700 }}>{((jm.pass_rate ?? 0) * 100).toFixed(0)}%</span>
                    </div>
                  </td>
                  <td style={{ padding: '7px 10px', color: 'var(--muted)' }}>{jm.runs}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>

    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))', gap: 12 }}>
      {/* Mutation matrix */}
      <div style={card}>
        <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Scenario Mutation Results</div>
        {(result.autonomous_agents?.mutation_matrix ?? []).map((m, i) => {
          const total = (m.passed ?? 0) + (m.failed ?? 0) + (m.flaky ?? 0);
          return (
            <div key={`mm-${i}`} style={{ marginBottom: 10 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12, marginBottom: 4 }}>
                <span style={{ fontWeight: 600 }}>{m.scenario}</span>
                <span style={{ color: 'var(--muted)' }}>{total} runs</span>
              </div>
              <div style={{ display: 'flex', height: 8, borderRadius: 4, overflow: 'hidden', gap: 1 }}>
                <div style={{ flex: m.passed ?? 0, background: '#22c55e' }} />
                <div style={{ flex: m.flaky ?? 0, background: '#f59e0b' }} />
                <div style={{ flex: m.failed ?? 0, background: '#ef4444' }} />
              </div>
              <div style={{ display: 'flex', gap: 10, fontSize: 10, marginTop: 3, color: 'var(--muted)' }}>
                <span style={{ color: '#22c55e' }}>{m.passed} pass</span>
                <span style={{ color: '#f59e0b' }}>{m.flaky} flaky</span>
                <span style={{ color: '#ef4444' }}>{m.failed} fail</span>
              </div>
            </div>
          );
        })}
      </div>

      {/* Deviation from baseline */}
      <div style={card}>
        <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Deviation from Baseline</div>
        <MiniBarChart items={(result.autonomous_agents?.deviation_from_baseline ?? []).map(d => ({
          label: `${d.metric} (+${d.delta_pct?.toFixed(1)}%)`,
          value: d.delta_pct ?? 0,
          max: 30,
          suffix: '%',
          color: (d.delta_pct ?? 0) > 20 ? '#ef4444' : '#f59e0b',
        }))} />
        <div style={{ marginTop: 10, display: 'grid', gap: 6 }}>
          {(result.autonomous_agents?.deviation_from_baseline ?? []).map((d, i) => (
            <div key={`dev-${i}`} style={{ fontSize: 11, display: 'flex', justifyContent: 'space-between' }}>
              <span style={{ color: 'var(--muted)' }}>{d.baseline_ms}ms baseline</span>
              <span style={{ color: '#ef4444', fontWeight: 700 }}>ÔåÆ {d.current_ms}ms</span>
            </div>
          ))}
        </div>
      </div>
    </div>

    {/* Failure hotspots */}
    {(result.autonomous_agents?.failure_hotspots ?? []).length > 0 && (
      <div style={{ ...card, marginTop: 12 }}>
        <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 8 }}>Failure Hotspots</div>
        <div style={{ display: 'grid', gap: 8 }}>
          {(result.autonomous_agents?.failure_hotspots ?? []).map((h, i) => (
            <div key={`hs-${i}`} style={{ ...card, padding: 10, display: 'flex', justifyContent: 'space-between', gap: 8, flexWrap: 'wrap', fontSize: 12, borderLeft: '3px solid #ef4444' }}>
