    <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 4 }}>Performance CI Gate</div>
    <div style={{ color: 'var(--muted)', fontSize: 12, marginBottom: 16 }}>Automated pre-merge gate that blocks regressions before they reach production using predicted PR impact analysis.</div>

    {/* Status banner */}
