        <div>
          <div style={{ fontWeight: 700, fontSize: 16 }}>Gate Status: <span style={{ color: result.ci_gate?.status === 'pass' ? '#22c55e' : result.ci_gate?.status === 'fail' ? '#ef4444' : '#f59e0b' }}>{(result.ci_gate?.status ?? 'warn').toUpperCase()}</span></div>
          <div style={{ fontSize: 12, color: 'var(--muted)', marginTop: 4 }}>{result.ci_gate?.recommendation?.replace(/_/g, ' ')}</div>
        </div>
