          {[
            { label: 'LCP ╬ö', value: `+${result.ci_gate?.predicted_pr_impact?.lcp_delta_ms ?? 0}ms`, over: (result.ci_gate?.predicted_pr_impact?.lcp_delta_ms ?? 0) > 0 },
            { label: 'INP ╬ö', value: `+${result.ci_gate?.predicted_pr_impact?.inp_delta_ms ?? 0}ms`, over: (result.ci_gate?.predicted_pr_impact?.inp_delta_ms ?? 0) > 0 },
            { label: 'CLS ╬ö', value: `+${result.ci_gate?.predicted_pr_impact?.cls_delta ?? 0}`, over: (result.ci_gate?.predicted_pr_impact?.cls_delta ?? 0) > 0 },
          ].map(m => (
            <div key={m.label} style={card}>
              <div style={{ fontSize: 10, color: 'var(--muted)' }}>{m.label}</div>
              <div style={{ fontWeight: 800, fontSize: 18, color: m.over ? '#ef4444' : '#22c55e' }}>{m.value}</div>
            </div>
          ))}
        </div>
      </div>
    </div>

    {/* Budget adherence bars */}
    <div style={{ ...card, marginBottom: 12 }}>
      <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 12 }}>Budget Adherence</div>
      <MiniBarChart items={[
        { label: 'LCP (budget 2500ms)', value: result.ci_gate?.predicted_pr_impact?.lcp_delta_ms ?? 0, max: result.ci_gate?.budget?.lcp_ms ?? 2500, suffix: 'ms over', color: '#ef4444' },
        { label: 'INP (budget 200ms)', value: result.ci_gate?.predicted_pr_impact?.inp_delta_ms ?? 0, max: result.ci_gate?.budget?.inp_ms ?? 200, suffix: 'ms over', color: '#f59e0b' },
      ]} />
    </div>

    {/* Blocking rules */}
    <div style={{ ...card, marginBottom: 12 }}>
      <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Gate Rules</div>
      <div style={{ display: 'grid', gap: 6 }}>
        {(result.ci_gate?.blocking_rules ?? []).map((rule, i) => (
          <div key={`br-${i}`} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '8px 12px', background: 'var(--bg)', borderRadius: 8, border: `1px solid ${rule.pass ? '#22c55e44' : '#ef444444'}`, fontSize: 12 }}>
            <span style={{ fontWeight: 600 }}>{rule.rule}</span>
            <span style={{ display: 'flex', gap: 12, alignItems: 'center' }}>
              <span style={{ color: 'var(--muted)' }}>budget: {rule.threshold}</span>
              <span style={{ color: rule.pass ? '#22c55e' : '#ef4444', fontWeight: 700 }}>current: {rule.current}</span>
              <span style={{ borderRadius: 999, padding: '2px 9px', fontSize: 10, background: rule.pass ? '#14532d44' : '#7f1d1d44', color: rule.pass ? '#86efac' : '#fca5a5' }}>{rule.pass ? 'PASS' : 'FAIL'}</span>
            </span>
          </div>
        ))}
      </div>
    </div>

    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))', gap: 12 }}>
      {/* PR diff analysis */}
      <div style={card}>
        <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>PR Diff Analysis</div>
        {(result.ci_gate?.pr_diff_analysis ?? []).map((d, i) => (
          <div key={`prd-${i}`} style={{ marginBottom: 8, paddingBottom: 8, borderBottom: i < (result.ci_gate?.pr_diff_analysis?.length ?? 0) - 1 ? '1px solid var(--line)' : 'none' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12 }}>
              <code style={{ fontSize: 10, background: 'var(--bg)', padding: '2px 5px', borderRadius: 4 }}>{d.file}</code>
              <span style={{ color: '#ef4444', fontSize: 11 }}>+{d.size_delta_kb}KB</span>
            </div>
            <div style={{ fontSize: 11, color: 'var(--muted)', marginTop: 3, display: 'flex', justifyContent: 'space-between' }}>
              <span>{d.impact}</span>
              <span style={{ borderRadius: 999, padding: '1px 7px', background: d.severity === 'critical' ? '#7f1d1d44' : d.severity === 'high' ? '#78350f44' : '#1e3a5f44', color: d.severity === 'critical' ? '#fca5a5' : d.severity === 'high' ? '#fcd34d' : '#93c5fd', fontSize: 10 }}>{d.severity}</span>
            </div>
          </div>
        ))}
      </div>

      {/* Gate history */}
      <div style={card}>
        <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Recent Gate History</div>
        {(result.ci_gate?.gate_history ?? []).map((h, i) => (
          <div key={`gh-${i}`} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontSize: 12, marginBottom: 7 }}>
            <span style={{ fontWeight: 600 }}>{h.pr}</span>
            <span style={{ color: 'var(--muted)' }}>LCP ╬ö {(h.lcp_delta_ms ?? 0) > 0 ? '+' : ''}{h.lcp_delta_ms}ms</span>
            <span style={{ borderRadius: 999, padding: '2px 9px', fontSize: 10, background: h.status === 'pass' ? '#14532d44' : h.status === 'fail' ? '#7f1d1d44' : '#78350f44', color: h.status === 'pass' ? '#86efac' : h.status === 'fail' ? '#fca5a5' : '#fcd34d' }}>{h.status?.toUpperCase()}</span>
            <span style={{ fontSize: 10, color: 'var(--muted)' }}>{h.merged ? 'merged' : 'blocked'}</span>
          </div>
        ))}
      </div>
    </div>

    {/* Bundle analysis */}
    {result.ci_gate?.bundle_analysis && (
      <div style={{ ...card, marginTop: 12 }}>
        <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 8 }}>Bundle Analysis</div>
        <div style={{ display: 'flex', gap: 16, fontSize: 12, flexWrap: 'wrap', marginBottom: 8 }}>
          <span>Total: <strong>{result.ci_gate.bundle_analysis.total_kb} KB</strong></span>
          <span>PR ╬ö: <strong style={{ color: '#ef4444' }}>+{result.ci_gate.bundle_analysis.delta_kb} KB</strong></span>
        </div>
        {(result.ci_gate.bundle_analysis.new_deps ?? []).length > 0 && (
          <div>
            <div style={{ fontSize: 11, color: 'var(--muted)', marginBottom: 6 }}>New dependencies added:</div>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
              {(result.ci_gate.bundle_analysis.new_deps ?? []).map(dep => (
                <code key={dep} style={{ fontSize: 11, background: '#78350f22', color: '#fcd34d', borderRadius: 4, padding: '3px 8px' }}>{dep}</code>
              ))}
            </div>
          </div>
        )}
      </div>
    )}
  </section>
  );
}


function SloTab({ result, card, isOfflinePreview }: PerfTabProps) {
  return (
  <section style={card}>
    <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 4 }}>SLO Guardrails</div>
    <div style={{ color: 'var(--muted)', fontSize: 12, marginBottom: 16 }}>Error budget burn rates, compliance trends and multi-window alert windows for CWV service-level objectives.</div>

    {/* Overall status */}
    <div style={{ ...card, marginBottom: 16, borderLeft: `4px solid ${result.slo_guardrails?.overall === 'healthy' ? '#22c55e' : result.slo_guardrails?.overall === 'critical' ? '#ef4444' : '#f59e0b'}` }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 8 }}>
        <div>
          <div style={{ fontWeight: 700, fontSize: 16 }}>Overall: <span style={{ color: result.slo_guardrails?.overall === 'healthy' ? '#22c55e' : '#f59e0b' }}>{(result.slo_guardrails?.overall ?? 'unknown').toUpperCase()}</span></div>
          <div style={{ fontSize: 12, color: 'var(--muted)', marginTop: 2 }}>7-day breach risk: <strong>{result.slo_guardrails?.breach_risk_next_7d ?? 'n/a'}</strong></div>
        </div>
        <div style={{ display: 'flex', gap: 10 }}>
          {[{ label: 'LCP Burn', value: result.slo_guardrails?.burn_rate?.lcp ?? 0 },
            { label: 'INP Burn', value: result.slo_guardrails?.burn_rate?.inp ?? 0 },
            { label: 'CLS Burn', value: result.slo_guardrails?.burn_rate?.cls ?? 0 }].map(b => (
            <div key={b.label} style={card}>
              <div style={{ fontSize: 10, color: 'var(--muted)' }}>{b.label}</div>
              <div style={{ fontWeight: 800, fontSize: 20, color: b.value > 1 ? '#ef4444' : '#22c55e' }}>{b.value}├ù</div>
            </div>
          ))}
        </div>
      </div>
    </div>

    {/* Targets vs Current */}
    <div style={{ ...card, marginBottom: 12 }}>
      <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>SLO Targets vs Current</div>
      <div style={{ overflowX: 'auto' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
          <thead>
            <tr style={{ borderBottom: '1px solid var(--line)', color: 'var(--muted)', fontSize: 11 }}>
              {['Metric','Target','Current','╬ö','Status'].map(h => (
                <th key={h} style={{ padding: '6px 10px', textAlign: 'left', fontWeight: 600 }}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {[
              { metric: 'LCP P75', target: `${result.slo_guardrails?.slo_targets?.lcp_p75_ms}ms`, current: `${result.slo_guardrails?.current?.lcp_p75_ms}ms`, delta: (result.slo_guardrails?.current?.lcp_p75_ms ?? 0) - (result.slo_guardrails?.slo_targets?.lcp_p75_ms ?? 0), pass: (result.slo_guardrails?.current?.lcp_p75_ms ?? 0) <= (result.slo_guardrails?.slo_targets?.lcp_p75_ms ?? 0) },
              { metric: 'INP P75', target: `${result.slo_guardrails?.slo_targets?.inp_p75_ms}ms`, current: `${result.slo_guardrails?.current?.inp_p75_ms}ms`, delta: (result.slo_guardrails?.current?.inp_p75_ms ?? 0) - (result.slo_guardrails?.slo_targets?.inp_p75_ms ?? 0), pass: (result.slo_guardrails?.current?.inp_p75_ms ?? 0) <= (result.slo_guardrails?.slo_targets?.inp_p75_ms ?? 0) },
              { metric: 'CLS P75', target: `${result.slo_guardrails?.slo_targets?.cls_p75}`, current: `${result.slo_guardrails?.current?.cls_p75}`, delta: (result.slo_guardrails?.current?.cls_p75 ?? 0) - (result.slo_guardrails?.slo_targets?.cls_p75 ?? 0), pass: (result.slo_guardrails?.current?.cls_p75 ?? 0) <= (result.slo_guardrails?.slo_targets?.cls_p75 ?? 0) },
              { metric: 'Availability', target: `${result.slo_guardrails?.slo_targets?.availability_pct}%`, current: `${result.slo_guardrails?.current?.availability_pct}%`, delta: (result.slo_guardrails?.current?.availability_pct ?? 0) - (result.slo_guardrails?.slo_targets?.availability_pct ?? 0), pass: (result.slo_guardrails?.current?.availability_pct ?? 0) >= (result.slo_guardrails?.slo_targets?.availability_pct ?? 0) },
            ].map(row => (
              <tr key={row.metric} style={{ borderBottom: '1px solid var(--line)' }}>
                <td style={{ padding: '7px 10px', fontWeight: 600 }}>{row.metric}</td>
                <td style={{ padding: '7px 10px', color: 'var(--muted)' }}>{row.target}</td>
                <td style={{ padding: '7px 10px', fontWeight: 700, color: row.pass ? '#22c55e' : '#ef4444' }}>{row.current}</td>
                <td style={{ padding: '7px 10px', color: row.pass ? '#22c55e' : '#ef4444' }}>{row.delta > 0 ? '+' : ''}{row.delta.toFixed(2)}</td>
                <td style={{ padding: '7px 10px' }}><span style={{ borderRadius: 999, padding: '2px 8px', fontSize: 10, background: row.pass ? '#14532d44' : '#7f1d1d44', color: row.pass ? '#86efac' : '#fca5a5' }}>{row.pass ? 'OK' : 'BREACH'}</span></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>

    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))', gap: 12, marginBottom: 12 }}>
      {/* Error budget */}
      <div style={card}>
        <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Error Budget Consumed</div>
        {(result.slo_guardrails?.error_budget ?? []).map((eb, i) => {
          const pct = Math.max(0, Math.min(120, 100 + (eb.remaining_pct ?? 0)));
          const over = (eb.remaining_pct ?? 0) < 0;
          return (
            <div key={`eb-${i}`} style={{ marginBottom: 10 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12, marginBottom: 4 }}>
                <span style={{ fontWeight: 600 }}>{eb.metric}</span>
                <span style={{ color: over ? '#ef4444' : '#22c55e', fontWeight: 700 }}>{over ? `${Math.abs(eb.remaining_pct ?? 0)}% over` : `${eb.remaining_pct}% remaining`}</span>
              </div>
              <div style={{ height: 6, background: 'var(--line)', borderRadius: 3, overflow: 'hidden' }}>
                <div style={{ width: `${Math.min(100, pct)}%`, height: '100%', background: over ? '#ef4444' : '#22c55e', borderRadius: 3 }} />
              </div>
              <div style={{ fontSize: 10, color: 'var(--muted)', marginTop: 2 }}>{eb.consumed_mins}min consumed of {eb.budget_mins}min budget</div>
            </div>
          );
        })}
      </div>

      {/* Alert windows */}
      <div style={card}>
        <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Multi-window Alert Status</div>
        {(result.slo_guardrails?.alert_windows ?? []).map((aw, i) => (
          <div key={`aw-${i}`} style={{ ...card, padding: 8, marginBottom: 8, display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontSize: 12 }}>
            <span style={{ fontWeight: 700, width: 36 }}>{aw.window}</span>
            <span style={{ color: 'var(--muted)' }}>LCP: <strong style={{ color: (aw.lcp_burn ?? 0) > 1.5 ? '#ef4444' : '#f59e0b' }}>{aw.lcp_burn}├ù</strong></span>
            <span style={{ color: 'var(--muted)' }}>INP: <strong style={{ color: (aw.inp_burn ?? 0) > 1.5 ? '#ef4444' : '#f59e0b' }}>{aw.inp_burn}├ù</strong></span>
            <span style={{ borderRadius: 999, padding: '2px 9px', fontSize: 10, background: aw.status === 'ok' ? '#14532d44' : aw.status === 'critical' ? '#7f1d1d44' : '#78350f44', color: aw.status === 'ok' ? '#86efac' : aw.status === 'critical' ? '#fca5a5' : '#fcd34d' }}>{aw.status?.toUpperCase()}</span>
          </div>
        ))}
      </div>
    </div>

    {/* Breach scenarios */}
    <div style={card}>
      <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Breach Scenarios</div>
      {(result.slo_guardrails?.breach_scenarios ?? []).map((bs, i) => (
        <div key={`bs-${i}`} style={{ ...card, padding: 10, marginBottom: 8, display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 10, flexWrap: 'wrap', fontSize: 12, borderLeft: `3px solid ${(bs.probability ?? 0) > 0.6 ? '#ef4444' : '#f59e0b'}` }}>
          <div><strong>{bs.scenario}</strong><div style={{ color: 'var(--muted)', marginTop: 2 }}>{bs.impact}</div></div>
          <div style={{ fontWeight: 800, color: (bs.probability ?? 0) > 0.6 ? '#ef4444' : '#f59e0b', flexShrink: 0 }}>{((bs.probability ?? 0) * 100).toFixed(0)}%</div>
        </div>
      ))}
    </div>
  </section>
  );
}


function RoiTab({ result, card, isOfflinePreview }: PerfTabProps) {
  return (
  <section style={card}>
    <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 4 }}>Fix Priority ROI Matrix</div>
    <div style={{ color: 'var(--muted)', fontSize: 12, marginBottom: 16 }}>Effort ├ù impact quadrant ranking every optimization opportunity by revenue recovery, performance gain and engineering cost.</div>

    {/* Summary KPIs */}
    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(160px, 1fr))', gap: 10, marginBottom: 16 }}>
      <div style={card}>
        <div style={{ color: 'var(--muted)', fontSize: 11 }}>Total Fixes</div>
        <div style={{ fontWeight: 800, fontSize: 26 }}>{(result.roi_matrix ?? []).length}</div>
      </div>
      <div style={card}>
        <div style={{ color: 'var(--muted)', fontSize: 11 }}>Max Perf Gain</div>
        <div style={{ fontWeight: 800, fontSize: 26, color: '#22c55e' }}>{(result.roi_matrix ?? []).reduce((s, r) => s + (r.estimated_gain_ms ?? 0), 0)}ms</div>
      </div>
      <div style={card}>
        <div style={{ color: 'var(--muted)', fontSize: 11 }}>Max Revenue Recovery</div>
        <div style={{ fontWeight: 800, fontSize: 22, color: '#22c55e' }}>${(result.roi_matrix ?? []).reduce((s, r) => s + (r.revenue_impact_usd ?? 0), 0).toLocaleString()}/mo</div>
      </div>
      <div style={card}>
        <div style={{ color: 'var(--muted)', fontSize: 11 }}>Sprint 1 Fixes</div>
        <div style={{ fontWeight: 800, fontSize: 26, color: '#6366f1' }}>{(result.roi_matrix ?? []).filter(r => r.sprint === 1).length}</div>
      </div>
    </div>

    {/* Priority score bars */}
    <div style={{ ...card, marginBottom: 12 }}>
      <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Priority Ranking (by score)</div>
      <MiniBarChart items={[...(result.roi_matrix ?? [])].sort((a, b) => (b.priority_score ?? 0) - (a.priority_score ?? 0)).map(r => ({
        label: r.title ?? '',
        value: r.priority_score ?? 0,
        max: 100,
        suffix: ` (${r.effort})`,
        color: (r.priority_score ?? 0) >= 85 ? '#22c55e' : (r.priority_score ?? 0) >= 70 ? '#f59e0b' : '#6366f1',
      }))} />
    </div>

    {/* Revenue gain bars */}
    <div style={{ ...card, marginBottom: 12 }}>
      <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Revenue Impact per Fix ($/mo)</div>
      <MiniBarChart items={[...(result.roi_matrix ?? [])].sort((a, b) => (b.revenue_impact_usd ?? 0) - (a.revenue_impact_usd ?? 0)).map(r => ({
        label: r.title ?? '',
        value: r.revenue_impact_usd ?? 0,
        max: 5000,
        suffix: '/mo',
        color: '#22c55e',
      }))} />
    </div>

    {/* Sprint breakdown */}
    {[1, 2, 3].map(sprint => {
      const sprintRows = (result.roi_matrix ?? []).filter(r => r.sprint === sprint);
      if (!sprintRows.length) return null;
      return (
        <div key={`sprint-${sprint}`} style={{ ...card, marginBottom: 12 }}>
          <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>
            Sprint {sprint}
            <span style={{ marginLeft: 8, fontSize: 11, color: 'var(--muted)', fontWeight: 400 }}>
              {sprintRows.reduce((s, r) => s + (r.estimated_gain_ms ?? 0), 0)}ms total gain ┬À ${sprintRows.reduce((s, r) => s + (r.revenue_impact_usd ?? 0), 0).toLocaleString()}/mo revenue
            </span>
          </div>
          <div style={{ display: 'grid', gap: 8 }}>
            {sprintRows.map((row, i) => (
              <div key={`roi-s${sprint}-${i}`} style={{ ...card, padding: 10, display: 'grid', gridTemplateColumns: '1fr auto auto auto auto', gap: 10, alignItems: 'center' }}>
                <div>
                  <div style={{ fontSize: 12, fontWeight: 700 }}>{row.title}</div>
                  <div style={{ display: 'flex', gap: 8, marginTop: 3 }}>
                    <span style={{ fontSize: 10, borderRadius: 999, padding: '2px 8px', background: 'var(--bg)', border: '1px solid var(--line)' }}>{row.effort}</span>
                    <span style={{ fontSize: 10, borderRadius: 999, padding: '2px 8px', background: 'var(--bg)', border: '1px solid var(--line)' }}>{row.category}</span>
                  </div>
                </div>
                <div style={{ textAlign: 'right', fontSize: 12 }}>
                  <div style={{ color: '#22c55e', fontWeight: 700 }}>-{row.estimated_gain_ms}ms</div>
                  <div style={{ color: 'var(--muted)', fontSize: 11 }}>perf gain</div>
                </div>
                <div style={{ textAlign: 'right', fontSize: 12 }}>
                  <div style={{ color: '#22c55e', fontWeight: 700 }}>${(row.revenue_impact_usd ?? 0).toLocaleString()}</div>
                  <div style={{ color: 'var(--muted)', fontSize: 11 }}>/mo</div>
                </div>
                <div style={{ textAlign: 'right', fontSize: 12 }}>
                  <div style={{ fontWeight: 700, color: (row.priority_score ?? 0) >= 85 ? '#22c55e' : '#f59e0b' }}>{row.priority_score}</div>
                  <div style={{ color: 'var(--muted)', fontSize: 11 }}>score</div>
                </div>
                <span style={{ borderRadius: 999, padding: '3px 9px', fontSize: 10, background: row.impact_level === 'high' ? '#14532d44' : row.impact_level === 'medium' ? '#78350f44' : '#1e1b4b44', color: row.impact_level === 'high' ? '#86efac' : row.impact_level === 'medium' ? '#fcd34d' : '#a5b4fc' }}>{row.impact_level}</span>
              </div>
            ))}
          </div>
        </div>
      );
    })}
  </section>
  );
}


function CopilotTab({ result, card, isOfflinePreview }: PerfTabProps) {
  return (
