    <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 4 }}>AI Performance Copilot</div>
    <div style={{ color: 'var(--muted)', fontSize: 12, marginBottom: 16 }}>AI-generated root-cause narrative, change attribution timeline, code-level hints and risk radar ÔÇö all wired to your live CWV data.</div>

    {/* AI confidence + status */}
    <div style={{ ...card, marginBottom: 16 }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 12, flexWrap: 'wrap' }}>
        <div style={{ flex: 1 }}>
          <div style={{ fontWeight: 700, fontSize: 15, marginBottom: 6 }}>{result.performance_copilot?.summary ?? 'No summary'}</div>
          <div style={{ color: 'var(--muted)', fontSize: 12, lineHeight: 1.6 }}>{result.performance_copilot?.narrative ?? ''}</div>
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4 }}>
          <div style={{ fontWeight: 800, fontSize: 28, color: (result.performance_copilot?.ai_confidence ?? 0) >= 80 ? '#22c55e' : '#f59e0b' }}>{result.performance_copilot?.ai_confidence ?? 0}%</div>
          <div style={{ fontSize: 10, color: 'var(--muted)' }}>AI confidence</div>
          {result.performance_copilot?.next_audit_eta && (
            <div style={{ fontSize: 10, color: 'var(--muted)', marginTop: 4 }}>Next audit: {new Date(result.performance_copilot.next_audit_eta).toLocaleDateString()}</div>
          )}
        </div>
      </div>
    </div>

    {/* What changed / why / actions */}
    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(240px, 1fr))', gap: 12, marginBottom: 16 }}>
      {[
        { title: 'What Changed', items: result.performance_copilot?.what_changed ?? [], color: '#6366f1' },
        { title: 'Why It Happened', items: result.performance_copilot?.why_it_happened ?? [], color: '#f59e0b' },
        { title: 'Recommended Actions', items: result.performance_copilot?.recommended_actions ?? [], color: '#22c55e' },
      ].map(section => (
        <div key={section.title} style={card}>
          <div style={{ fontWeight: 700, fontSize: 12, marginBottom: 8, borderBottom: `2px solid ${section.color}`, paddingBottom: 6 }}>{section.title}</div>
          {section.items.map((x, i) => (
            <div key={`${section.title}-${i}`} style={{ display: 'flex', gap: 6, alignItems: 'flex-start', fontSize: 12, marginBottom: 6 }}>
              <span style={{ color: section.color, flexShrink: 0 }}>ÔÇ║</span>
              <span>{x}</span>
            </div>
          ))}
        </div>
      ))}
    </div>

    {/* Change timeline */}
    {(result.performance_copilot?.change_timeline ?? []).length > 0 && (
      <div style={{ ...card, marginBottom: 16 }}>
        <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 12 }}>Performance Change Timeline</div>
        <div style={{ position: 'relative', paddingLeft: 20 }}>
          <div style={{ position: 'absolute', left: 8, top: 0, bottom: 0, width: 2, background: 'var(--line)', borderRadius: 2 }} />
          {(result.performance_copilot?.change_timeline ?? []).map((ct, i) => (
            <div key={`ct-${i}`} style={{ position: 'relative', marginBottom: 14, paddingLeft: 12 }}>
              <div style={{ position: 'absolute', left: -6, top: 4, width: 10, height: 10, borderRadius: '50%', background: ct.impact === 'positive' ? '#22c55e' : '#ef4444', border: '2px solid var(--bg)' }} />
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 8, flexWrap: 'wrap' }}>
                <div>
                  <div style={{ fontSize: 12, fontWeight: 600 }}>{ct.event}</div>
                  <div style={{ fontSize: 11, color: 'var(--muted)' }}>{ct.date}</div>
                </div>
                <span style={{ fontSize: 12, fontWeight: 700, color: ct.impact === 'positive' ? '#22c55e' : '#ef4444', flexShrink: 0 }}>
                  {(ct.score_delta ?? 0) > 0 ? '+' : ''}{ct.score_delta} score
                </span>
              </div>
            </div>
          ))}
        </div>
      </div>
    )}

    {/* Code hints */}
    {(result.performance_copilot?.code_hints ?? []).length > 0 && (
      <div style={{ ...card, marginBottom: 16 }}>
        <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Code-level Hints</div>
        <div style={{ display: 'grid', gap: 8 }}>
          {(result.performance_copilot?.code_hints ?? []).map((h, i) => (
            <div key={`ch-${i}`} style={{ ...card, padding: 10, borderLeft: `3px solid ${h.priority === 'critical' ? '#ef4444' : h.priority === 'high' ? '#f59e0b' : '#6366f1'}` }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 8, flexWrap: 'wrap', marginBottom: 4 }}>
                <code style={{ fontSize: 11, background: 'var(--bg)', padding: '2px 6px', borderRadius: 4 }}>{h.file}</code>
                <span style={{ display: 'flex', gap: 8, alignItems: 'center', fontSize: 11, flexShrink: 0 }}>
                  <span style={{ color: '#22c55e' }}>-{h.savings_ms}ms</span>
                  <span style={{ borderRadius: 999, padding: '2px 8px', background: h.priority === 'critical' ? '#7f1d1d44' : h.priority === 'high' ? '#78350f44' : '#1e1b4b44', color: h.priority === 'critical' ? '#fca5a5' : h.priority === 'high' ? '#fcd34d' : '#a5b4fc' }}>{h.priority}</span>
                </span>
              </div>
              <div style={{ fontSize: 12, color: 'var(--muted)' }}>{h.hint}</div>
            </div>
          ))}
        </div>
      </div>
    )}

    {/* Risk radar */}
    {(result.performance_copilot?.risk_radar ?? []).length > 0 && (
      <div style={{ ...card, marginBottom: 16 }}>
        <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Risk Radar</div>
        {(result.performance_copilot?.risk_radar ?? []).map((r, i) => (
          <div key={`rr-${i}`} style={{ marginBottom: 10 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12, marginBottom: 4 }}>
              <span><strong>{r.area}</strong> ÔÇö {r.risk}</span>
              <span style={{ color: (r.probability ?? 0) > 0.6 ? '#ef4444' : '#f59e0b', fontWeight: 700 }}>{((r.probability ?? 0) * 100).toFixed(0)}%</span>
            </div>
            <div style={{ height: 5, background: 'var(--line)', borderRadius: 3, overflow: 'hidden' }}>
              <div style={{ width: `${(r.probability ?? 0) * 100}%`, height: '100%', background: (r.probability ?? 0) > 0.6 ? '#ef4444' : '#f59e0b', borderRadius: 3 }} />
            </div>
          </div>
        ))}
      </div>
    )}

    {/* Execution playbook */}
    {(result.execution_playbook?.now ?? []).length > 0 && (
      <div style={card}>
        <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Execution Playbook</div>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))', gap: 12 }}>
          {[
            { label: 'Now', items: result.execution_playbook?.now ?? [], color: '#ef4444' },
            { label: 'Next Sprint', items: result.execution_playbook?.next ?? [], color: '#f59e0b' },
            { label: 'Later', items: result.execution_playbook?.later ?? [], color: '#6366f1' },
          ].map(phase => (
            <div key={phase.label}>
              <div style={{ fontSize: 11, color: phase.color, fontWeight: 700, marginBottom: 6, textTransform: 'uppercase', letterSpacing: '0.05em' }}>{phase.label}</div>
              {phase.items.map((x, i) => (
                <div key={`${phase.label}-${i}`} style={{ fontSize: 12, marginBottom: 5, display: 'flex', gap: 6, alignItems: 'flex-start' }}>
                  <span style={{ color: phase.color }}>ÔÇó</span>
                  <span>{x}</span>
                </div>
              ))}
            </div>
          ))}
        </div>
      </div>
    )}
  </section>
  );
}


function OpportunitiesTab({ result, card, isOfflinePreview, autoFixing, optimizeSite }: PerfTabProps) {
  return (
  <section style={card}>
    {/* Header + CTA */}
    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 16, flexWrap: 'wrap', gap: 8 }}>
      <div>
        <div style={{ fontWeight: 700, fontSize: 14 }}>Optimization Opportunities</div>
        <div style={{ fontSize: 12, color: 'var(--muted)', marginTop: 2 }}>Ranked by priority score ÔÇö effort vs impact vs revenue.</div>
      </div>
      <button type="button" onClick={optimizeSite} disabled={autoFixing} style={{ ...btn(true), background: '#7c3aed', color: '#fff' }}>
        {autoFixing ? 'Applying...' : 'Fix All Automatically'}
      </button>
    </div>

    {/* Totals KPI strip */}
    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(160px, 1fr))', gap: 10, marginBottom: 16 }}>
      {[
        { label: 'Total Opportunities', value: String((result.opportunities ?? []).length), color: 'var(--text)' },
        { label: 'Total Gain', value: `${(result.opportunities ?? []).reduce((s, o) => s + (o.estimated_gain_ms ?? 0), 0)}ms`, color: '#22c55e' },
        { label: 'Revenue Potential', value: `$${(result.opportunities ?? []).reduce((s, o) => s + (o.revenue_gain_usd ?? 0), 0).toLocaleString()}/mo`, color: '#22c55e' },
        { label: 'Quick Wins (low effort)', value: String((result.opportunities ?? []).filter(o => o.effort === 'low').length), color: '#3b82f6' },
      ].map(kpi => (
        <div key={kpi.label} style={card}>
          <div style={{ fontSize: 11, color: 'var(--muted)' }}>{kpi.label}</div>
          <div style={{ fontWeight: 800, fontSize: 20, color: kpi.color, marginTop: 4 }}>{kpi.value}</div>
        </div>
      ))}
    </div>

    {/* Gain bar chart */}
    <div style={{ ...card, marginBottom: 16 }}>
      <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Performance Gain by Fix (ms)</div>
      <MiniBarChart items={(result.opportunities ?? []).map(o => ({
        label: o.issue ?? '',
        value: o.estimated_gain_ms ?? 0,
        color: priorityColor(o.priority),
        suffix: 'ms',
        max: 300,
      }))} />
    </div>

    {/* Grouped by category */}
    {(() => {
      const byCategory = (result.opportunities ?? []).reduce<Record<string, typeof result.opportunities>>((acc, o) => {
        const cat = o.category ?? 'Other';
        acc[cat] = [...(acc[cat] ?? []), o];
        return acc;
      }, {});
      return (
        <div style={{ display: 'grid', gap: 12 }}>
          {Object.entries(byCategory).map(([cat, items]) => (
            <div key={cat} style={card}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10 }}>
                <div style={{ fontWeight: 700, fontSize: 13 }}>{cat}</div>
                <div style={{ fontSize: 11, color: 'var(--muted)' }}>
                  {(items ?? []).reduce((s, o) => s + (o.estimated_gain_ms ?? 0), 0)}ms total gain &nbsp;┬À&nbsp;
                  ${(items ?? []).reduce((s, o) => s + (o.revenue_gain_usd ?? 0), 0).toLocaleString()}/mo
                </div>
              </div>
              <div style={{ display: 'grid', gap: 8 }}>
                {(items ?? []).map((item, i) => (
                  <div key={`opp-${cat}-${i}`} style={{ ...card, padding: 12, borderLeft: `3px solid ${priorityColor(item.priority)}` }}>
                    <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 10, flexWrap: 'wrap' }}>
                      <div style={{ flex: 1 }}>
                        <div style={{ display: 'flex', gap: 8, alignItems: 'center', marginBottom: 4, flexWrap: 'wrap' }}>
                          <span style={badge(priorityColor(item.priority))}>{item.priority ?? 'low'}</span>
                          <span style={{ fontSize: 10, borderRadius: 999, padding: '2px 8px', background: 'var(--bg)', border: '1px solid var(--line)' }}>{item.effort ?? 'medium'} effort</span>
                          <span style={{ fontWeight: 700, fontSize: 13 }}>{item.issue}</span>
                        </div>
                        <div style={{ fontSize: 12, color: 'var(--muted)' }}>{item.impact}</div>
                      </div>
                      <div style={{ display: 'flex', gap: 16, alignItems: 'center', flexShrink: 0 }}>
                        {(item.estimated_gain_ms ?? 0) > 0 && (
                          <div style={{ textAlign: 'right' }}>
                            <div style={{ fontWeight: 700, color: '#22c55e', fontSize: 13 }}>-{item.estimated_gain_ms}ms</div>
                            <div style={{ fontSize: 10, color: 'var(--muted)' }}>perf gain</div>
                          </div>
                        )}
                        {(item.revenue_gain_usd ?? 0) > 0 && (
                          <div style={{ textAlign: 'right' }}>
                            <div style={{ fontWeight: 700, color: '#22c55e', fontSize: 13 }}>${(item.revenue_gain_usd ?? 0).toLocaleString()}</div>
                            <div style={{ fontSize: 10, color: 'var(--muted)' }}>/mo revenue</div>
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      );
    })()}
  </section>
  );
}


function AiFixesTab({ result, card, isOfflinePreview, autoFixing, autoFixResult, fixingItem, fixedItems, fixSingleItem, optimizeSite }: PerfTabProps) {
  return (
  <section style={{ display: 'grid', gap: 12 }}>
    {/* Header + Apply All */}
    <div style={{ ...card, display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: 10 }}>
      <div>
        <div style={{ fontWeight: 700, fontSize: 14 }}>AI Remediation Engine</div>
        {result.ai_remediation?.summary && (
          <div style={{ fontSize: 12, color: 'var(--muted)', marginTop: 4, maxWidth: 600 }}>{result.ai_remediation.summary}</div>
        )}
      </div>
      <button type="button" onClick={optimizeSite} disabled={autoFixing} style={{ ...btn(true), background: '#7c3aed', color: '#fff' }}>
        {autoFixing ? 'Optimizing...' : 'ÔÜí Apply All Fixes'}
      </button>
    </div>

    {/* Before / after score projection */}
    <div style={card}>
      <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Score Projection After All Fixes</div>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(180px, 1fr))', gap: 10 }}>
        {[
          { label: 'Performance Score', current: result.performance_score ?? 62, projected: Math.min(100, (result.performance_score ?? 62) + 24) },
          { label: 'LCP', current: 3800, projected: 2432, suffix: 'ms', lowerBetter: true },
          { label: 'Total Gain', current: 0, projected: (result.ai_remediation?.auto_fix_candidates ?? []).reduce((s, c) => s + (c.estimated_gain_ms ?? 0), 0), suffix: 'ms', gainOnly: true },
          { label: 'Fixes Available', current: 0, projected: (result.ai_remediation?.auto_fix_candidates ?? []).length, gainOnly: true },
        ].map(m => (
          <div key={m.label} style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 10, padding: 12 }}>
            <div style={{ fontSize: 10, color: 'var(--muted)', marginBottom: 4 }}>{m.label}</div>
            {m.gainOnly ? (
              <div style={{ fontWeight: 800, fontSize: 22, color: '#22c55e' }}>{m.projected}{m.suffix ?? ''}</div>
            ) : (
              <div style={{ display: 'flex', alignItems: 'baseline', gap: 8 }}>
                <span style={{ fontWeight: 700, fontSize: 18, color: 'var(--muted)', textDecoration: 'line-through' }}>{m.current}{m.suffix ?? ''}</span>
                <span style={{ fontWeight: 800, fontSize: 22, color: '#22c55e' }}>ÔåÆ {m.projected}{m.suffix ?? ''}</span>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>

    {/* Fix-by-category bar chart */}
    <div style={card}>
      <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Fixes by Category</div>
      <MiniBarChart items={(() => {
        const cats: Record<string, number> = {};
        (result.ai_remediation?.auto_fix_candidates ?? []).forEach(c => {
          const cat = (c.verification ?? 'Other').split('_')[0];
          cats[cat] = (cats[cat] ?? 0) + 1;
        });
        const colors = ['#6366f1','#22c55e','#f59e0b','#3b82f6','#ef4444','#ec4899'];
        return Object.entries(cats).map(([k, v], i) => ({ label: k, value: v, color: colors[i % colors.length], max: Math.max(...Object.values(cats)), suffix: ' fixes' }));
      })()} />
    </div>

    {/* Applied fixes result */}
    {autoFixResult && (
      <div style={{ ...card, background: '#14532d22', border: '1px solid #22c55e44' }}>
        <div style={{ fontWeight: 700, color: '#22c55e', marginBottom: 8 }}>Optimization Results</div>
        <div style={{ display: 'grid', gap: 6 }}>
          {autoFixResult.fixes_applied.map(fix => (
            <div key={fix.fix_id} style={{ display: 'flex', alignItems: 'center', gap: 10, fontSize: 12 }}>
              <span style={{ color: fix.status === 'applied' ? '#22c55e' : '#ef4444', fontWeight: 700 }}>{fix.status === 'applied' ? 'Ô£ô' : 'Ô£ù'}</span>
              <span style={{ flex: 1 }}>{fix.title}</span>
              {fix.actual_gain_ms > 0 && <span style={{ color: '#22c55e', fontWeight: 700 }}>-{fix.actual_gain_ms}ms</span>}
              <span style={badge(fix.status === 'applied' ? '#22c55e' : '#ef4444')}>{fix.status}</span>
            </div>
          ))}
        </div>
        <div style={{ marginTop: 10, fontSize: 12, display: 'flex', gap: 16 }}>
          <div>Total gain: <strong style={{ color: '#22c55e' }}>{autoFixResult.total_gain_ms}ms</strong></div>
          <div>New score: <strong style={{ color: '#22c55e' }}>{autoFixResult.new_performance_score}</strong></div>
        </div>
      </div>
    )}

    {/* Candidate list */}
    <div style={{ display: 'grid', gap: 10 }}>
      {(result.ai_remediation?.auto_fix_candidates ?? []).map((candidate, i) => {
        const isFixed = fixedItems.has(candidate.title ?? '');
        const isFixingThis = fixingItem === candidate.title;
        const confPct = Math.round((candidate.confidence ?? 0) * 100);
        const riskColor = confPct >= 90 ? '#22c55e' : confPct >= 70 ? '#f59e0b' : '#ef4444';
        const riskLabel = confPct >= 90 ? 'low-risk' : confPct >= 70 ? 'medium-risk' : 'high-risk';
        return (
          <div key={`${candidate.title}-${i}`} style={{ ...card, padding: 12, opacity: isFixed ? 0.55 : 1, borderLeft: `3px solid ${riskColor}` }}>
            <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 10, flexWrap: 'wrap' }}>
              <div style={{ flex: 1 }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 4, flexWrap: 'wrap' }}>
                  {isFixed && <span style={{ color: '#22c55e', fontWeight: 700, fontSize: 11 }}>Ô£ô Fixed</span>}
                  <span style={{ fontWeight: 700, fontSize: 13 }}>{candidate.title}</span>
                  <span style={badge(riskColor)}>{riskLabel}</span>
                  <span style={badge('#6366f1')}>{candidate.verification ?? 'general'}</span>
                </div>
                <div style={{ display: 'flex', gap: 12, fontSize: 11, color: 'var(--muted)', flexWrap: 'wrap' }}>
                  <span>Confidence: <strong style={{ color: riskColor }}>{confPct}%</strong></span>
                  <span>Est. gain: <strong style={{ color: '#22c55e' }}>-{candidate.estimated_gain_ms ?? 0}ms</strong></span>
                  <span>Verify: {candidate.verification}</span>
                </div>
                <div style={{ marginTop: 8, height: 5, background: 'var(--line)', borderRadius: 3, overflow: 'hidden' }}>
                  <div style={{ width: `${confPct}%`, height: '100%', background: riskColor, borderRadius: 3 }} />
                </div>
              </div>
              {!isFixed && (
                <button type="button" onClick={() => fixSingleItem(candidate)} disabled={isFixingThis || !!fixingItem} style={{ ...btn(), fontSize: 11, padding: '6px 12px' }}>
                  {isFixingThis ? 'Fixing...' : 'Fix This'}
                </button>
              )}
            </div>
          </div>
        );
      })}
    </div>

    {/* Verification plan */}
    {(result.ai_remediation?.verification_plan ?? []).length > 0 && (
      <div style={card}>
        <div style={{ fontWeight: 700, fontSize: 12, marginBottom: 8, color: 'var(--muted)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>Verification Plan</div>
        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
          {(result.ai_remediation?.verification_plan ?? []).map(item => (
            <span key={item} style={{ fontSize: 11, borderRadius: 999, padding: '5px 12px', background: 'var(--bg)', border: '1px solid var(--line)' }}>{item}</span>
          ))}
        </div>
      </div>
    )}
  </section>
  );
}


function ImagesTab({ result, card, isOfflinePreview }: PerfTabProps) {
  return (
  <section style={card}>
    <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 4 }}>Image Audit</div>
    <div style={{ fontSize: 12, color: 'var(--muted)', marginBottom: 16 }}>Format efficiency, LCP candidate analysis, alt text coverage, CDN delivery and bandwidth waste.</div>
    {result.image_audit ? (
      <div style={{ display: 'grid', gap: 14 }}>
        {/* KPI strip */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(150px, 1fr))', gap: 10 }}>
          {[
            { label: 'Total Images', value: String(result.image_audit.total_images ?? 0), color: 'var(--text)' },
            { label: 'Unoptimised', value: String(result.image_audit.unoptimized ?? 0), color: '#ef4444' },
            { label: 'Missing Alt', value: String(result.image_audit.missing_alt ?? 0), color: '#f59e0b' },
            { label: 'Bandwidth Wasted', value: `${result.image_audit.bandwidth_wasted_mb ?? 0} MB`, color: '#ef4444' },
            { label: 'Lazy Loaded', value: `${((result.image_audit.lazy_loaded_pct ?? 0) * 100).toFixed(0)}%`, color: '#3b82f6' },
            { label: 'Next-gen Format', value: `${((result.image_audit.next_gen_adoption_pct ?? 0) * 100).toFixed(0)}%`, color: (result.image_audit.next_gen_adoption_pct ?? 0) >= 0.8 ? '#22c55e' : '#f59e0b' },
            { label: 'CDN Coverage', value: `${((result.image_audit.cdn_coverage_pct ?? 0) * 100).toFixed(0)}%`, color: '#6366f1' },
          ].map(kpi => (
            <div key={kpi.label} style={card}>
              <div style={{ fontSize: 11, color: 'var(--muted)' }}>{kpi.label}</div>
              <div style={{ fontWeight: 800, fontSize: 18, color: kpi.color, marginTop: 4 }}>{kpi.value}</div>
            </div>
          ))}
        </div>

        {/* LCP image callout */}
        {result.image_audit.lcp_image && (
          <div style={{ ...card, borderLeft: '3px solid #f59e0b', padding: 12 }}>
            <div style={{ fontWeight: 700, fontSize: 12, marginBottom: 4 }}>LCP Image Candidate</div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 10, flexWrap: 'wrap' }}>
              <code style={{ fontSize: 11, color: '#f59e0b' }}>{result.image_audit.lcp_image}</code>
              <div style={{ display: 'flex', gap: 10, fontSize: 11 }}>
                <span style={{ color: '#ef4444' }}>Missing fetchpriority=&quot;high&quot;</span>
                <span>┬À</span>
                <span style={{ color: '#f59e0b' }}>Serving JPEG ÔÇö upgrade to AVIF</span>
              </div>
            </div>
          </div>
        )}

        {/* Savings table */}
        {(result.image_audit.oversized ?? []).length > 0 && (
          <div style={card}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Compression Opportunities</div>
            <div style={{ overflowX: 'auto' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
                <thead>
                  <tr style={{ borderBottom: '1px solid var(--line)' }}>
                    {['Asset', 'Format', 'Size', 'Recommend', 'Savings KB', 'Savings %', 'Decode', 'LCP'].map(h => (
                      <th key={h} style={{ textAlign: 'left', padding: '6px 10px', fontSize: 10, color: 'var(--muted)', fontWeight: 600 }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {(result.image_audit.oversized ?? []).map((img, i) => (
                    <tr key={`img-${i}`} style={{ borderBottom: '1px solid var(--line)' }}>
                      <td style={{ padding: '7px 10px', fontFamily: 'monospace', fontSize: 11, color: 'var(--muted)', maxWidth: 180, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{img.url}</td>
                      <td style={{ padding: '7px 10px' }}><span style={{ borderRadius: 999, padding: '2px 8px', background: 'var(--bg)', border: '1px solid var(--line)', fontSize: 10 }}>{img.format}</span></td>
                      <td style={{ padding: '7px 10px', fontWeight: 700 }}>{img.size_kb} KB</td>
                      <td style={{ padding: '7px 10px', color: '#22c55e', fontWeight: 700 }}>{img.recommended_format}</td>
                      <td style={{ padding: '7px 10px', color: '#22c55e', fontWeight: 700 }}>-{img.savings_kb} KB</td>
                      <td style={{ padding: '7px 10px', color: '#22c55e' }}>{img.savings_pct}%</td>
                      <td style={{ padding: '7px 10px' }}>{img.decode_time_ms}ms</td>
                      <td style={{ padding: '7px 10px' }}>{img.lcp_candidate ? <span style={{ color: '#f59e0b', fontWeight: 700 }}>LCP</span> : 'ÔÇö'}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* Format breakdown + per-page audit side by side */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: 12 }}>
          {Object.keys(result.image_audit.format_breakdown ?? {}).length > 0 && (
            <div style={card}>
              <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Format Breakdown</div>
              <MiniBarChart items={Object.entries(result.image_audit.format_breakdown ?? {}).map(([fmt, cnt]) => ({
                label: fmt.toUpperCase(),
                value: cnt,
                color: fmt === 'webp' || fmt === 'avif' ? '#22c55e' : '#f59e0b',
                max: (result.image_audit?.total_images ?? 1),
              }))} />
            </div>
          )}
          {(result.image_audit.per_page_audit ?? []).length > 0 && (
            <div style={card}>
              <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Per-Page Audit</div>
              <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
                <thead>
                  <tr style={{ borderBottom: '1px solid var(--line)' }}>
                    {['Page', 'Images', 'Missing Alt', 'Unoptimised'].map(h => (
                      <th key={h} style={{ textAlign: 'left', padding: '4px 8px', fontSize: 10, color: 'var(--muted)' }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {(result.image_audit.per_page_audit ?? []).map((p, i) => (
                    <tr key={`pp-${i}`} style={{ borderBottom: '1px solid var(--line)' }}>
                      <td style={{ padding: '6px 8px', fontFamily: 'monospace', fontSize: 11 }}>{p.page}</td>
                      <td style={{ padding: '6px 8px' }}>{p.count}</td>
                      <td style={{ padding: '6px 8px', color: (p.missing_alt ?? 0) > 0 ? '#f59e0b' : '#22c55e', fontWeight: 700 }}>{p.missing_alt}</td>
                      <td style={{ padding: '6px 8px', color: (p.unoptimized ?? 0) > 0 ? '#ef4444' : '#22c55e', fontWeight: 700 }}>{p.unoptimized}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>

        {/* Issues */}
        {(result.image_audit.issues ?? []).length > 0 && (
          <div style={card}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 8 }}>Issues</div>
            <div style={{ display: 'grid', gap: 6 }}>
              {(result.image_audit.issues ?? []).map((issue, i) => {
                const col = severityColor(issue.severity);
                return (
                  <div key={`img-issue-${i}`} style={{ ...card, padding: 10, borderLeft: `3px solid ${col}`, fontSize: 12 }}>
                    <span style={badge(col)}>{issue.severity}</span>
                    <span style={{ marginLeft: 6 }}>{issue.message}</span>
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </div>
    ) : (
      <div style={{ color: 'var(--muted)', fontSize: 12 }}>No image audit data available.</div>
    )}
  </section>
  );
}


function SecurityTab({ result, card, isOfflinePreview }: PerfTabProps) {
  return (
  <section style={card}>
    <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 4 }}>Security Audit</div>
    <div style={{ fontSize: 12, color: 'var(--muted)', marginBottom: 16 }}>Threat score, TLS strength, CSP directives, CORS policy, SRI coverage, cookies and known CVEs.</div>
    {result.security_audit ? (
      <div style={{ display: 'grid', gap: 14 }}>
        {/* Threat score banner */}
        <div style={{ ...card, borderLeft: `4px solid ${(result.security_audit.threat_score ?? 0) >= 70 ? '#ef4444' : (result.security_audit.threat_score ?? 0) >= 40 ? '#f59e0b' : '#22c55e'}`, display: 'flex', alignItems: 'center', gap: 20, padding: 16 }}>
          <div>
            <div style={{ fontSize: 11, color: 'var(--muted)' }}>Threat Score</div>
            <div style={{ fontWeight: 900, fontSize: 40, lineHeight: 1, color: (result.security_audit.threat_score ?? 0) >= 70 ? '#ef4444' : (result.security_audit.threat_score ?? 0) >= 40 ? '#f59e0b' : '#22c55e' }}>{result.security_audit.threat_score ?? 0}</div>
            <div style={{ fontSize: 11, color: 'var(--muted)' }}>/100</div>
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(140px, 1fr))', gap: 8, flex: 1 }}>
            {[
              { label: 'HTTPS', value: result.security_audit.https ? 'Enabled' : 'Missing', ok: !!result.security_audit.https },
              { label: 'Mixed Content', value: `${result.security_audit.mixed_content_count ?? 0} issues`, ok: (result.security_audit.mixed_content_count ?? 0) === 0 },
              { label: 'CSP Score', value: `${result.security_audit.csp_score ?? 0}/100`, ok: (result.security_audit.csp_score ?? 0) >= 70 },
              { label: 'SRI Coverage', value: `${result.security_audit.subresource_integrity_pct ?? 0}%`, ok: (result.security_audit.subresource_integrity_pct ?? 0) >= 80 },
            ].map(k => (
              <div key={k.label} style={{ ...card, padding: 8 }}>
                <div style={{ fontSize: 10, color: 'var(--muted)' }}>{k.label}</div>
                <div style={{ fontWeight: 700, fontSize: 14, color: k.ok ? '#22c55e' : '#ef4444', marginTop: 2 }}>{k.value}</div>
              </div>
            ))}
          </div>
        </div>

        {/* TLS info */}
        {result.security_audit.tls_info && (
          <div style={{ ...card, padding: 12 }}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 8 }}>TLS Configuration</div>
            <div style={{ display: 'flex', gap: 16, flexWrap: 'wrap', fontSize: 12 }}>
              <span>Version: <strong>{result.security_audit.tls_info.version}</strong></span>
              <span>Cipher: <strong>{result.security_audit.tls_info.cipher}</strong></span>
              {result.security_audit.tls_info.cert_expires && <span>Cert Expires: <strong>{new Date(result.security_audit.tls_info.cert_expires).toLocaleDateString()}</strong></span>}
              <span>Grade: <strong>{result.security_audit.tls_info.grade ?? 'ÔÇö'}</strong></span>
            </div>
          </div>
        )}

        {/* Cookies table */}
        {result.security_audit.cookies && (
          <div style={card}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Cookie Security ({result.security_audit.cookies.total} total)</div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 8 }}>
              {[
                { label: 'Secure flag', val: result.security_audit.cookies.secure ?? 0, total: result.security_audit.cookies.total ?? 0, color: '#22c55e' },
                { label: 'HttpOnly flag', val: result.security_audit.cookies.httponly ?? 0, total: result.security_audit.cookies.total ?? 0, color: '#3b82f6' },
                { label: 'SameSite set', val: result.security_audit.cookies.samesite ?? 0, total: result.security_audit.cookies.total ?? 0, color: '#6366f1' },
              ].map(c => {
                const pct = Math.round(c.val / Math.max(c.total, 1) * 100);
                return (
                  <div key={c.label} style={card}>
                    <div style={{ fontSize: 11, color: 'var(--muted)' }}>{c.label}</div>
                    <div style={{ fontWeight: 700, fontSize: 16, color: pct < 100 ? '#f59e0b' : c.color }}>{c.val}/{c.total}</div>
                    <div style={{ marginTop: 4, height: 4, background: 'var(--line)', borderRadius: 2, overflow: 'hidden' }}>
                      <div style={{ width: `${pct}%`, height: '100%', background: pct < 100 ? '#f59e0b' : c.color, borderRadius: 2 }} />
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* CSP directives */}
        {(result.security_audit.csp_directives ?? []).length > 0 && (
          <div style={card}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>CSP Directives ({result.security_audit.csp_directives?.length ?? 0})</div>
            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
              <thead>
                <tr style={{ borderBottom: '1px solid var(--line)' }}>
                  {['Directive', 'Value', 'Status', 'Risk'].map(h => (
                    <th key={h} style={{ textAlign: 'left', padding: '5px 10px', fontSize: 10, color: 'var(--muted)', fontWeight: 600 }}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {(result.security_audit.csp_directives ?? []).map((d, i) => {
                  const riskColor = d.risk === 'high' ? '#ef4444' : d.risk === 'medium' ? '#f59e0b' : '#22c55e';
                  const statusColor = d.status === 'missing' ? '#ef4444' : d.status === 'weak' ? '#f59e0b' : '#22c55e';
                  return (
                    <tr key={`csp-${i}`} style={{ borderBottom: '1px solid var(--line)' }}>
                      <td style={{ padding: '6px 10px', fontFamily: 'monospace', fontSize: 11, fontWeight: 700 }}>{d.directive}</td>
                      <td style={{ padding: '6px 10px', fontFamily: 'monospace', fontSize: 10, color: 'var(--muted)', maxWidth: 200, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{d.value ?? 'ÔÇö'}</td>
                      <td style={{ padding: '6px 10px' }}><span style={badge(statusColor)}>{d.status}</span></td>
                      <td style={{ padding: '6px 10px' }}><span style={badge(riskColor)}>{d.risk}</span></td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}

        {/* CORS issues */}
        {(result.security_audit.cors_issues ?? []).length > 0 && (
          <div style={card}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>CORS Policy Issues</div>
            {(result.security_audit.cors_issues ?? []).map((c, i) => {
              const rc = c.risk === 'high' ? '#ef4444' : c.risk === 'medium' ? '#f59e0b' : '#22c55e';
              return (
                <div key={`cors-${i}`} style={{ ...card, padding: 10, borderLeft: `3px solid ${rc}`, marginBottom: 8 }}>
                  <div style={{ display: 'flex', gap: 8, alignItems: 'center', marginBottom: 4, flexWrap: 'wrap' }}>
                    <span style={badge(rc)}>{c.risk}</span>
                    <span style={{ fontFamily: 'monospace', fontSize: 11 }}>{c.endpoint}</span>
                    <span style={{ fontSize: 10, borderRadius: 999, padding: '2px 8px', background: 'var(--bg)', border: '1px solid var(--line)' }}>{c.method}</span>
                  </div>
                  <div style={{ fontSize: 12, color: 'var(--muted)' }}>{c.issue}</div>
                </div>
              );
            })}
          </div>
        )}

        {/* Missing SRI */}
        {(result.security_audit.sri_missing ?? []).length > 0 && (
          <div style={card}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 8 }}>Missing Subresource Integrity ({result.security_audit.sri_missing?.length})</div>
            <div style={{ display: 'grid', gap: 4 }}>
              {(result.security_audit.sri_missing ?? []).map((s, i) => (
                <div key={`sri-${i}`} style={{ padding: '5px 10px', background: '#7f1d1d22', border: '1px solid #ef444433', borderRadius: 6, fontFamily: 'monospace', fontSize: 11, color: '#fca5a5' }}>{s}</div>
              ))}
            </div>
          </div>
        )}

        {/* HTTP Headers */}
        {Object.keys(result.security_audit.headers ?? {}).length > 0 && (
          <div style={card}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>HTTP Security Headers</div>
            <div style={{ display: 'grid', gap: 6 }}>
              {Object.entries(result.security_audit.headers ?? {}).map(([name, hdr]) => {
                const col = headerColor(hdr.present, hdr.severity);
                return (
                  <div key={name} style={{ ...card, padding: '8px 12px', display: 'grid', gridTemplateColumns: '1fr auto auto', alignItems: 'center', gap: 10, fontSize: 12 }}>
                    <div style={{ fontFamily: 'monospace', fontSize: 11 }}>{name}</div>
                    {hdr.present && hdr.value && <div style={{ color: 'var(--muted)', fontSize: 10, fontFamily: 'monospace' }}>{hdr.value}</div>}
                    <span style={badge(col)}>{hdr.present ? 'present' : 'missing'}</span>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* Vulnerabilities */}
        {(result.security_audit.vulnerabilities ?? []).length > 0 && (
          <div style={card}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 8 }}>Vulnerabilities</div>
            <div style={{ display: 'grid', gap: 8 }}>
              {(result.security_audit.vulnerabilities ?? []).map((v, i) => {
                const col = severityColor(v.severity);
                return (
                  <div key={`sec-vuln-${i}`} style={{ ...card, padding: 12, borderLeft: `3px solid ${col}` }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 4, flexWrap: 'wrap' }}>
                      <span style={badge(col)}>{v.severity}</span>
                      {v.cve && <span style={{ fontFamily: 'monospace', fontSize: 10, borderRadius: 4, padding: '2px 6px', background: '#1e1b4b44', color: '#a5b4fc' }}>{v.cve}</span>}
                      <span style={{ fontWeight: 700, fontSize: 13 }}>{v.issue}</span>
                    </div>
                    <div style={{ fontSize: 12, color: 'var(--muted)' }}>{v.detail}</div>
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </div>
    ) : (
      <div style={{ color: 'var(--muted)', fontSize: 12 }}>No security audit data available.</div>
    )}
  </section>
  );
}


function JavascriptTab({ result, card, isOfflinePreview }: PerfTabProps) {
  return (
  <section style={card}>
    <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 4 }}>JavaScript Audit</div>
    <div style={{ fontSize: 12, color: 'var(--muted)', marginBottom: 16 }}>Bundle size, coverage, tree-shaking, main thread cost, long tasks and blocking scripts.</div>
    {result.js_audit ? (
      <div style={{ display: 'grid', gap: 14 }}>
        {/* KPI strip */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(150px, 1fr))', gap: 10 }}>
          {[
            { label: 'Total JS', value: `${result.js_audit.total_kb ?? 0} KB`, color: 'var(--text)' },
            { label: 'Unused JS', value: `${result.js_audit.unused_kb ?? 0} KB`, color: '#ef4444' },
            { label: 'Unused %', value: `${(result.js_audit.unused_pct ?? 0).toFixed(1)}%`, color: '#ef4444' },
            { label: 'Parse Time', value: `${result.js_audit.parse_time_ms ?? 0}ms`, color: '#f59e0b' },
            { label: 'Exec Time', value: `${result.js_audit.execution_time_ms ?? 0}ms`, color: '#f59e0b' },
            { label: 'Third-party JS', value: `${result.js_audit.third_party_kb ?? 0} KB`, color: '#6366f1' },
            { label: 'Main Thread Cost', value: `${result.js_audit.main_thread_cost_ms ?? 0}ms`, color: (result.js_audit.main_thread_cost_ms ?? 0) > 1500 ? '#ef4444' : '#22c55e' },
          ].map(kpi => (
            <div key={kpi.label} style={card}>
              <div style={{ fontSize: 11, color: 'var(--muted)' }}>{kpi.label}</div>
              <div style={{ fontWeight: 800, fontSize: 18, color: kpi.color, marginTop: 4 }}>{kpi.value}</div>
            </div>
          ))}
        </div>

        {/* Compression savings */}
        {result.js_audit.compression && (
          <div style={card}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Compression Savings</div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 8 }}>
              {[
                { label: 'Raw', value: result.js_audit.compression.raw_kb, color: '#ef4444' },
                { label: 'Gzip', value: result.js_audit.compression.gzip_kb, color: '#f59e0b' },
                { label: 'Brotli', value: result.js_audit.compression.brotli_kb, color: '#22c55e' },
              ].map(c => {
                const pct = Math.round(((c.value as number | undefined ?? 0) / Math.max(result.js_audit?.compression?.raw_kb ?? 1, 1)) * 100);
                return (
                  <div key={c.label} style={card}>
                    <div style={{ fontSize: 11, color: 'var(--muted)' }}>{c.label}</div>
                    <div style={{ fontWeight: 700, fontSize: 16, color: c.color }}>{c.value} KB</div>
                    <div style={{ marginTop: 4, height: 4, background: 'var(--line)', borderRadius: 2, overflow: 'hidden' }}>
                      <div style={{ width: `${pct}%`, height: '100%', background: c.color, borderRadius: 2 }} />
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* Bundle modules */}
        {(result.js_audit.bundle_modules ?? []).length > 0 && (
          <div style={card}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Bundle Modules (tree-shaking analysis)</div>
            <div style={{ overflowX: 'auto' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
                <thead>
                  <tr style={{ borderBottom: '1px solid var(--line)' }}>
                    {['Module', 'Size KB', 'Unused %', 'Tree-shakeable', 'Type'].map(h => (
                      <th key={h} style={{ textAlign: 'left', padding: '5px 10px', fontSize: 10, color: 'var(--muted)', fontWeight: 600 }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {(result.js_audit.bundle_modules ?? []).map((m, i) => (
                    <tr key={`mod-${i}`} style={{ borderBottom: '1px solid var(--line)' }}>
                      <td style={{ padding: '6px 10px', fontFamily: 'monospace', fontSize: 11 }}>{m.module}</td>
                      <td style={{ padding: '6px 10px', fontWeight: 700 }}>{m.size_kb}</td>
                      <td style={{ padding: '6px 10px' }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                          <div style={{ width: 60, height: 4, background: 'var(--line)', borderRadius: 2, overflow: 'hidden', flexShrink: 0 }}>
                            <div style={{ width: `${m.unused_pct ?? 0}%`, height: '100%', background: (m.unused_pct ?? 0) > 50 ? '#ef4444' : '#f59e0b', borderRadius: 2 }} />
                          </div>
                          <span style={{ color: (m.unused_pct ?? 0) > 50 ? '#ef4444' : 'var(--text)' }}>{m.unused_pct}%</span>
                        </div>
                      </td>
                      <td style={{ padding: '6px 10px' }}><span style={{ color: m.tree_shakeable ? '#22c55e' : '#ef4444' }}>{m.tree_shakeable ? 'Yes' : 'No'}</span></td>
                      <td style={{ padding: '6px 10px' }}><span style={{ borderRadius: 999, padding: '2px 8px', background: 'var(--bg)', border: '1px solid var(--line)', fontSize: 10 }}>{m.type}</span></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* Long tasks */}
        {(result.js_audit.long_tasks ?? []).length > 0 && (
          <div style={card}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Long Tasks (blocking main thread)</div>
            <div style={{ display: 'grid', gap: 8 }}>
              {(result.js_audit.long_tasks ?? []).map((t, i) => (
                <div key={`lt-${i}`} style={{ ...card, padding: 10 }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 6, gap: 8, flexWrap: 'wrap' }}>
                    <div>
                      <div style={{ fontSize: 12, fontWeight: 700 }}>{t.task}</div>
                      <div style={{ fontSize: 11, color: 'var(--muted)' }}>Culprit: {t.culprit} ┬À starts at {t.start_ms}ms</div>
                    </div>
                    <span style={{ color: '#ef4444', fontWeight: 700, fontSize: 13 }}>{t.duration_ms}ms</span>
                  </div>
                  <div style={{ height: 4, background: 'var(--line)', borderRadius: 2, overflow: 'hidden' }}>
                    <div style={{ width: `${Math.min((t.duration_ms ?? 0) / 5, 100)}%`, height: '100%', background: '#ef4444', borderRadius: 2 }} />
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Blocking scripts + opportunities */}
        {(result.js_audit.blocking_scripts ?? []).length > 0 && (
          <div style={card}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 8 }}>Render-Blocking Scripts</div>
            <div style={{ display: 'grid', gap: 4 }}>
              {(result.js_audit.blocking_scripts ?? []).map(s => (
                <div key={s} style={{ padding: '6px 10px', background: '#7f1d1d22', border: '1px solid #ef444444', borderRadius: 6, fontSize: 12, color: '#fca5a5', fontFamily: 'monospace' }}>{s}</div>
              ))}
            </div>
          </div>
        )}
        {(result.js_audit.opportunities ?? []).length > 0 && (
          <div style={card}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 8 }}>Optimisation Opportunities</div>
            <div style={{ display: 'grid', gap: 8 }}>
              {(result.js_audit.opportunities ?? []).map((op, i) => (
                <div key={`jsop-${i}`} style={{ ...card, padding: 10, display: 'grid', gridTemplateColumns: '1fr auto auto', alignItems: 'center', gap: 10, fontSize: 12 }}>
                  <div style={{ fontWeight: 600 }}>{op.title}</div>
                  {(op.savings_kb ?? 0) > 0 && <div style={{ color: '#22c55e' }}>Ôåô{op.savings_kb} KB</div>}
                  {(op.savings_ms ?? 0) > 0 && <div style={{ color: '#3b82f6' }}>-{op.savings_ms}ms</div>}
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    ) : (
      <div style={{ color: 'var(--muted)', fontSize: 12 }}>No JavaScript audit data available.</div>
    )}
  </section>
  );
}


function CssTab({ result, card, isOfflinePreview }: PerfTabProps) {
  return (
  <section style={card}>
    <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 4 }}>CSS Audit</div>
    <div style={{ fontSize: 12, color: 'var(--muted)', marginBottom: 16 }}>Unused coverage, file-level breakdown, render-blocking sheets, animation jank risks and critical inline %.</div>
    {result.css_audit ? (
      <div style={{ display: 'grid', gap: 14 }}>
        {/* KPI strip */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(140px, 1fr))', gap: 10 }}>
          {[
            { label: 'Total CSS', value: `${result.css_audit.total_kb ?? 0} KB`, color: 'var(--text)' },
            { label: 'Unused CSS', value: `${result.css_audit.unused_kb ?? 0} KB`, color: '#f59e0b' },
            { label: 'Unused %', value: `${(result.css_audit.unused_pct ?? 0).toFixed(1)}%`, color: '#f59e0b' },
            { label: 'Critical Path', value: `${result.css_audit.critical_path_kb ?? 0} KB`, color: 'var(--text)' },
            { label: 'Critical Inline', value: `${result.css_audit.critical_inline_pct ?? 0}%`, color: (result.css_audit.critical_inline_pct ?? 0) >= 60 ? '#22c55e' : '#f59e0b' },
            { label: 'Selectors', value: String(result.css_audit.selector_count ?? 0), color: 'var(--text)' },
            { label: 'Rules', value: String(result.css_audit.rule_count ?? 0), color: 'var(--text)' },
            { label: '@font-face', value: String(result.css_audit.font_face_count ?? 0), color: (result.css_audit.font_face_count ?? 0) > 6 ? '#f59e0b' : 'var(--text)' },
            { label: 'Blocking Files', value: String((result.css_audit.render_blocking ?? []).length), color: (result.css_audit.render_blocking ?? []).length > 0 ? '#ef4444' : '#22c55e' },
          ].map(kpi => (
            <div key={kpi.label} style={card}>
              <div style={{ fontSize: 11, color: 'var(--muted)' }}>{kpi.label}</div>
              <div style={{ fontWeight: 800, fontSize: 18, color: kpi.color, marginTop: 4 }}>{kpi.value}</div>
            </div>
          ))}
        </div>

        {/* Critical inline % progress */}
        <div style={card}>
          <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 6 }}>Critical CSS Inlined</div>
          <div style={{ height: 8, background: 'var(--line)', borderRadius: 4, overflow: 'hidden' }}>
            <div style={{ width: `${result.css_audit.critical_inline_pct ?? 0}%`, height: '100%', background: (result.css_audit.critical_inline_pct ?? 0) >= 60 ? '#22c55e' : '#f59e0b', borderRadius: 4 }} />
          </div>
          <div style={{ fontSize: 11, color: 'var(--muted)', marginTop: 4 }}>{result.css_audit.critical_inline_pct ?? 0}% critical CSS inlined ÔÇö target ÔëÑ60%</div>
        </div>

        {/* File breakdown table */}
        {(result.css_audit.file_breakdown ?? []).length > 0 && (
          <div style={card}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>File Breakdown</div>
            <div style={{ overflowX: 'auto' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
                <thead>
                  <tr style={{ borderBottom: '1px solid var(--line)' }}>
                    {['File', 'Total KB', 'Unused KB', 'Unused %', 'Render-Blocking'].map(h => (
                      <th key={h} style={{ textAlign: 'left', padding: '5px 10px', fontSize: 10, color: 'var(--muted)', fontWeight: 600 }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {(result.css_audit.file_breakdown ?? []).map((f, i) => (
                    <tr key={`cssf-${i}`} style={{ borderBottom: '1px solid var(--line)' }}>
                      <td style={{ padding: '6px 10px', fontFamily: 'monospace', fontSize: 11 }}>{f.file}</td>
                      <td style={{ padding: '6px 10px', fontWeight: 700 }}>{f.total_kb}</td>
                      <td style={{ padding: '6px 10px', color: '#f59e0b' }}>{f.unused_kb}</td>
                      <td style={{ padding: '6px 10px' }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                          <div style={{ width: 60, height: 4, background: 'var(--line)', borderRadius: 2, overflow: 'hidden' }}>
                            <div style={{ width: `${f.unused_pct ?? 0}%`, height: '100%', background: (f.unused_pct ?? 0) > 60 ? '#ef4444' : '#f59e0b', borderRadius: 2 }} />
                          </div>
                          <span>{f.unused_pct}%</span>
                        </div>
                      </td>
                      <td style={{ padding: '6px 10px' }}>{f.render_blocking ? <span style={badge('#ef4444')}>Blocking</span> : <span style={{ color: '#22c55e' }}>No</span>}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* Animation jank risks */}
        {(result.css_audit.animation_jank_risks ?? []).length > 0 && (
          <div style={card}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 8 }}>Animation Jank Risks</div>
            <div style={{ display: 'grid', gap: 6 }}>
              {(result.css_audit.animation_jank_risks ?? []).map((r, i) => (
                <div key={`jank-${i}`} style={{ ...card, padding: 10, borderLeft: '3px solid #f59e0b', fontSize: 12 }}>
                  <span style={badge('#f59e0b')}>jank</span>
                  <span style={{ marginLeft: 8 }}>{r}</span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Render-blocking + opportunities */}
        {(result.css_audit.render_blocking ?? []).length > 0 && (
          <div style={card}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 8 }}>Render-Blocking Stylesheets</div>
            <div style={{ display: 'grid', gap: 4 }}>
              {(result.css_audit.render_blocking ?? []).map(s => (
                <div key={s} style={{ padding: '6px 10px', background: '#7f1d1d22', border: '1px solid #ef444444', borderRadius: 6, fontSize: 12, color: '#fca5a5', fontFamily: 'monospace' }}>{s}</div>
              ))}
            </div>
          </div>
        )}
        {(result.css_audit.opportunities ?? []).length > 0 && (
          <div style={card}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 8 }}>Optimisation Opportunities</div>
            <div style={{ display: 'grid', gap: 8 }}>
              {(result.css_audit.opportunities ?? []).map((op, i) => (
                <div key={`cssop-${i}`} style={{ ...card, padding: 10, display: 'grid', gridTemplateColumns: '1fr auto auto', alignItems: 'center', gap: 10, fontSize: 12 }}>
                  <div style={{ fontWeight: 600 }}>{op.title}</div>
                  {(op.savings_kb ?? 0) > 0 && <div style={{ color: '#22c55e' }}>Ôåô{op.savings_kb} KB</div>}
                  {(op.savings_ms ?? 0) > 0 && <div style={{ color: '#3b82f6' }}>-{op.savings_ms}ms</div>}
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    ) : (
      <div style={{ color: 'var(--muted)', fontSize: 12 }}>No CSS audit data available.</div>
    )}
  </section>
  );
}


function InputValidationTab({ result, card, isOfflinePreview }: PerfTabProps) {
  return (
  <section style={card}>
    <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 4 }}>Input Validation Audit</div>
    <div style={{ fontSize: 12, color: 'var(--muted)', marginBottom: 16 }}>OWASP Top-10 coverage, form-level CSRF/server-validation audit, sanitization % and open-redirect risks.</div>
    {result.input_validation_audit ? (
      <div style={{ display: 'grid', gap: 14 }}>
        {/* KPI strip */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(150px, 1fr))', gap: 10 }}>
          {[
            { label: 'Forms Found', value: String(result.input_validation_audit.forms_found ?? 0), color: 'var(--text)' },
            { label: 'CSRF Protected', value: `${result.input_validation_audit.csrf_protected ?? 0}/${result.input_validation_audit.forms_found ?? 0}`, color: (result.input_validation_audit.csrf_protected ?? 0) === (result.input_validation_audit.forms_found ?? 0) ? '#22c55e' : '#f59e0b' },
            { label: 'Server Validated', value: `${result.input_validation_audit.server_side_validated ?? 0}/${result.input_validation_audit.forms_found ?? 0}`, color: '#3b82f6' },
            { label: 'Sanitization %', value: `${result.input_validation_audit.sanitization_pct ?? 0}%`, color: (result.input_validation_audit.sanitization_pct ?? 0) >= 80 ? '#22c55e' : '#f59e0b' },
            { label: 'XSS Risks', value: String(result.input_validation_audit.xss_risks ?? 0), color: (result.input_validation_audit.xss_risks ?? 0) > 0 ? '#ef4444' : '#22c55e' },
            { label: 'Injection Risks', value: String(result.input_validation_audit.injection_risks ?? 0), color: (result.input_validation_audit.injection_risks ?? 0) > 0 ? '#ef4444' : '#22c55e' },
            { label: 'Open Redirects', value: String(result.input_validation_audit.open_redirect_risks ?? 0), color: (result.input_validation_audit.open_redirect_risks ?? 0) > 0 ? '#ef4444' : '#22c55e' },
          ].map(kpi => (
            <div key={kpi.label} style={card}>
              <div style={{ fontSize: 11, color: 'var(--muted)' }}>{kpi.label}</div>
              <div style={{ fontWeight: 800, fontSize: 18, color: kpi.color, marginTop: 4 }}>{kpi.value}</div>
            </div>
          ))}
        </div>

        {/* OWASP Coverage table */}
        {(result.input_validation_audit.owasp_coverage ?? []).length > 0 && (
          <div style={card}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>OWASP Top-10 Coverage</div>
            <div style={{ overflowX: 'auto' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
                <thead>
                  <tr style={{ borderBottom: '1px solid var(--line)' }}>
                    {['ID', 'Vulnerability', 'Status', 'Risk Level'].map(h => (
                      <th key={h} style={{ textAlign: 'left', padding: '5px 10px', fontSize: 10, color: 'var(--muted)', fontWeight: 600 }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {(result.input_validation_audit.owasp_coverage ?? []).map((o, i) => {
                    const statusCol = o.status === 'pass' ? '#22c55e' : o.status === 'warn' ? '#f59e0b' : '#ef4444';
                    const riskCol = o.risk_level === 'critical' ? '#ef4444' : o.risk_level === 'high' ? '#f97316' : o.risk_level === 'medium' ? '#f59e0b' : '#22c55e';
                    return (
                      <tr key={`owasp-${i}`} style={{ borderBottom: '1px solid var(--line)' }}>
                        <td style={{ padding: '6px 10px', fontFamily: 'monospace', fontSize: 11, fontWeight: 700 }}>{o.id}</td>
                        <td style={{ padding: '6px 10px' }}>{o.name}</td>
                        <td style={{ padding: '6px 10px' }}><span style={badge(statusCol)}>{o.status}</span></td>
                        <td style={{ padding: '6px 10px' }}><span style={badge(riskCol)}>{o.risk_level}</span></td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* Form audit table */}
        {(result.input_validation_audit.form_audit ?? []).length > 0 && (
          <div style={card}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Form-by-Form Audit</div>
            <div style={{ overflowX: 'auto' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
                <thead>
                  <tr style={{ borderBottom: '1px solid var(--line)' }}>
                    {['Form ID', 'Action', 'CSRF', 'Client Val.', 'Server Val.', 'Inputs', 'Risk'].map(h => (
                      <th key={h} style={{ textAlign: 'left', padding: '5px 10px', fontSize: 10, color: 'var(--muted)', fontWeight: 600 }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {(result.input_validation_audit.form_audit ?? []).map((f, i) => {
                    const rc = f.risk === 'high' ? '#ef4444' : f.risk === 'medium' ? '#f59e0b' : '#22c55e';
                    return (
                      <tr key={`form-${i}`} style={{ borderBottom: '1px solid var(--line)' }}>
                        <td style={{ padding: '6px 10px', fontFamily: 'monospace', fontSize: 11 }}>{f.form_id}</td>
                        <td style={{ padding: '6px 10px', fontFamily: 'monospace', fontSize: 10, color: 'var(--muted)' }}>{f.action}</td>
                        <td style={{ padding: '6px 10px' }}><span style={{ color: f.csrf ? '#22c55e' : '#ef4444', fontWeight: 700 }}>{f.csrf ? 'Yes' : 'No'}</span></td>
                        <td style={{ padding: '6px 10px' }}><span style={{ color: f.client_val ? '#22c55e' : '#f59e0b' }}>{f.client_val ? 'Yes' : 'No'}</span></td>
                        <td style={{ padding: '6px 10px' }}><span style={{ color: f.server_val ? '#22c55e' : '#ef4444', fontWeight: 700 }}>{f.server_val ? 'Yes' : 'No'}</span></td>
                        <td style={{ padding: '6px 10px' }}>{f.inputs}</td>
                        <td style={{ padding: '6px 10px' }}><span style={badge(rc)}>{f.risk}</span></td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* Field issues */}
        {(result.input_validation_audit.issues ?? []).length > 0 && (
          <div style={card}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 8 }}>Field-level Issues</div>
            <div style={{ display: 'grid', gap: 8 }}>
              {(result.input_validation_audit.issues ?? []).map((issue, i) => {
                const col = severityColor(issue.severity);
                return (
                  <div key={`iv-${i}`} style={{ ...card, padding: 12, borderLeft: `3px solid ${col}` }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 4, flexWrap: 'wrap' }}>
                      <span style={badge(col)}>{issue.severity}</span>
                      <span style={{ fontFamily: 'monospace', fontSize: 11, color: 'var(--muted)' }}>{issue.name}</span>
                      <span style={{ fontSize: 11, color: 'var(--muted)' }}>({issue.type})</span>
                    </div>
                    <div style={{ fontSize: 12 }}>{issue.issue}</div>
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </div>
    ) : (
      <div style={{ color: 'var(--muted)', fontSize: 12 }}>No input validation audit data available.</div>
    )}
  </section>
  );
}


function LatencyTab({ result, card, isOfflinePreview }: PerfTabProps) {
  return (
  <section style={{ display: 'grid', gap: 12 }}>
    {result.latency_audit ? (
      <>
        {/* Cache + Compression row */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: 12 }}>
          {result.latency_audit.cache_stats && (
            <div style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 14 }}>
              <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Cache Performance</div>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8 }}>
                {[
                  { label: 'Hit Rate', value: `${((result.latency_audit.cache_stats.hit_rate ?? 0) * 100).toFixed(0)}%`, color: (result.latency_audit.cache_stats.hit_rate ?? 0) >= 0.8 ? '#22c55e' : '#f59e0b' },
                  { label: 'Miss Penalty', value: `${result.latency_audit.cache_stats.miss_penalty_ms ?? 0}ms`, color: '#ef4444' },
                  { label: 'Stale Rate', value: `${((result.latency_audit.cache_stats.stale_rate ?? 0) * 100).toFixed(0)}%`, color: '#f59e0b' },
                  { label: 'Cache-Control', value: result.latency_audit.cache_stats.stale_rate != null ? `${Math.round((1 - (result.latency_audit.cache_stats.stale_rate ?? 0)) * 100)}% valid` : 'ÔÇö', color: 'var(--text)' },
                ].map(c => (
                  <div key={c.label} style={{ background: 'var(--bg)', border: '1px solid var(--line)', borderRadius: 8, padding: 8 }}>
                    <div style={{ fontSize: 10, color: 'var(--muted)' }}>{c.label}</div>
                    <div style={{ fontWeight: 700, fontSize: 16, color: c.color }}>{c.value}</div>
                  </div>
                ))}
              </div>
            </div>
          )}
          {result.latency_audit.compression_stats && (
            <div style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 14 }}>
              <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Compression Coverage</div>
              <MiniBarChart items={[
                { label: 'Brotli', value: result.latency_audit.compression_stats.brotli_pct ?? 0, color: '#22c55e', max: 100, suffix: '%' },
                { label: 'Gzip', value: result.latency_audit.compression_stats.gzip_pct ?? 0, color: '#3b82f6', max: 100, suffix: '%' },
                { label: 'None', value: result.latency_audit.compression_stats.none_pct ?? 0, color: '#ef4444', max: 100, suffix: '%' },
              ]} />
            </div>
          )}
        </div>

        {/* Waterfall */}
        {(result.latency_audit.waterfall ?? []).length > 0 && (
          <div style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 14 }}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 12 }}>Request Waterfall</div>
            {(() => {
              const wf = result.latency_audit?.waterfall ?? [];
              const maxEnd = Math.max(...wf.map(e => (e.start_ms ?? 0) + (e.duration_ms ?? 0)));
              return wf.map((entry, i) => {
                const startPct = ((entry.start_ms ?? 0) / maxEnd) * 100;
                const widthPct = ((entry.duration_ms ?? 0) / maxEnd) * 100;
                const typeColor: Record<string, string> = { document: '#6366f1', script: '#f59e0b', css: '#3b82f6', image: '#22c55e', font: '#a855f7', api: '#f97316' };
                const col = typeColor[entry.type ?? 'api'] ?? '#94a3b8';
                return (
                  <div key={`wf-${i}`} style={{ marginBottom: 6 }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 10, color: 'var(--muted)', marginBottom: 2 }}>
                      <span style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', maxWidth: '55%' }}>{entry.name}</span>
                      <span>{entry.duration_ms}ms ┬À {entry.size_kb}KB</span>
                    </div>
                    <div style={{ height: 8, background: 'var(--line)', borderRadius: 2, overflow: 'hidden', position: 'relative' }}>
                      <div style={{ position: 'absolute', left: `${startPct}%`, width: `${widthPct}%`, height: '100%', background: col, borderRadius: 2 }} />
                    </div>
                  </div>
                );
              });
            })()}
          </div>
        )}

        {/* Percentile cards */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))', gap: 12 }}>
          {[
            { title: 'Overall Request', key: 'overall', threshold: 2500 },
            { title: 'DNS', key: 'dns', threshold: 100 },
            { title: 'TCP Handshake', key: 'tcp', threshold: 200 },
            { title: 'TLS Negotiation', key: 'tls', threshold: 300 },
            { title: 'TTFB', key: 'ttfb', threshold: 600 },
            { title: 'LCP', key: 'lcp', threshold: 2500 },
            { title: 'FCP', key: 'fcp', threshold: 1800 },
            { title: 'CDN Edge', key: 'cdn_edge_latency', threshold: 50 },
          ].map(({ title, key, threshold }) => {
            const d = result.latency_audit?.[key as keyof LatencyAudit] as LatencyPercentiles | undefined;
            return (
              <div key={key} style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 14 }}>
                <div style={{ fontWeight: 700, fontSize: 12, marginBottom: 10 }}>{title}</div>
                <LatencyPercentileBar p50={d?.p50} p75={d?.p75} p95={d?.p95} p99={d?.p99} threshold={threshold} />
              </div>
            );
          })}
        </div>

        {(result.latency_audit.endpoints ?? []).length > 0 && (
          <div style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 14 }}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 12 }}>API Endpoint Latency</div>
            <div style={{ display: 'grid', gap: 10 }}>
              {(result.latency_audit.endpoints ?? []).map((ep, i) => (
                <div key={`ep-${i}`} style={{ borderBottom: '1px solid var(--line)', paddingBottom: 10 }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 6, fontSize: 12 }}>
                    <span style={{ fontWeight: 700 }}><span style={{ color: '#3b82f6', marginRight: 6 }}>{ep.method}</span>{ep.url}</span>
                    <span style={{ color: (ep.error_rate ?? 0) > 0.01 ? '#ef4444' : '#22c55e', fontWeight: 700 }}>err {((ep.error_rate ?? 0) * 100).toFixed(1)}%</span>
                  </div>
                  <LatencyPercentileBar p50={ep.p50} p75={ep.p75} p95={ep.p95} p99={ep.p99} />
                </div>
              ))}
            </div>
          </div>
        )}

        {(result.latency_audit.db_query_distribution ?? []).length > 0 && (
          <div style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 14 }}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 12 }}>DB Query Distribution</div>
            <MiniBarChart items={(result.latency_audit.db_query_distribution ?? []).map(q => ({
              label: (q.query ?? '').slice(0, 28),
              value: q.p95 ?? 0,
              color: (q.p95 ?? 0) > 100 ? '#f97316' : '#3b82f6',
              suffix: 'ms p95',
            }))} />
          </div>
        )}
      </>
    ) : (
      <div style={{ color: 'var(--muted)', fontSize: 12 }}>No latency audit data available.</div>
    )}
  </section>
  );
}


function OutdatedTab({ result, card, isOfflinePreview }: PerfTabProps) {
  return (
  <section style={{ display: 'grid', gap: 12 }}>
    {result.outdated_audit ? (
      <>
        {/* Security risk banner */}
        <div style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 14, display: 'flex', gap: 20, alignItems: 'center', flexWrap: 'wrap' }}>
          <div>
            <div style={{ fontSize: 11, color: 'var(--muted)' }}>Security Risk Score</div>
            <div style={{ fontWeight: 900, fontSize: 44, lineHeight: 1, color: (result.outdated_audit.security_risk_score ?? 0) >= 60 ? '#ef4444' : '#f59e0b' }}>{result.outdated_audit.security_risk_score ?? 0}</div>
            <div style={{ fontSize: 11, color: 'var(--muted)' }}>/100</div>
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(130px, 1fr))', gap: 8, flex: 1 }}>
            {[
              { label: 'Total Deps', value: result.outdated_audit.total_deps ?? 0, color: 'var(--text)' },
              { label: 'Outdated', value: result.outdated_audit.outdated_count ?? 0, color: '#f59e0b' },
              { label: 'Critical', value: result.outdated_audit.critical_outdated ?? 0, color: '#ef4444' },
              { label: 'CVEs Found', value: result.outdated_audit.cve_count ?? 0, color: '#ef4444' },
            ].map(kpi => (
              <div key={kpi.label} style={{ background: 'var(--bg)', border: '1px solid var(--line)', borderRadius: 8, padding: 8 }}>
                <div style={{ fontSize: 10, color: 'var(--muted)' }}>{kpi.label}</div>
                <div style={{ fontWeight: 700, fontSize: 20, color: kpi.color }}>{kpi.value}</div>
              </div>
            ))}
          </div>
        </div>

        {/* CVE table */}
        {(result.outdated_audit.cves ?? []).length > 0 && (
          <div style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 14 }}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Known CVEs</div>
            <div style={{ overflowX: 'auto' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
                <thead>
                  <tr style={{ borderBottom: '1px solid var(--line)' }}>
                    {['Package', 'CVE ID', 'Severity', 'CVSS', 'Patched in'].map(h => (
                      <th key={h} style={{ textAlign: 'left', padding: '5px 10px', fontSize: 10, color: 'var(--muted)', fontWeight: 600 }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {(result.outdated_audit.cves ?? []).map((c, i) => {
                    const sc = c.severity === 'critical' ? '#ef4444' : c.severity === 'high' ? '#f97316' : c.severity === 'medium' ? '#f59e0b' : '#22c55e';
                    return (
                      <tr key={`cve-${i}`} style={{ borderBottom: '1px solid var(--line)' }}>
                        <td style={{ padding: '6px 10px', fontFamily: 'monospace', fontSize: 11, fontWeight: 700 }}>{c.pkg}</td>
                        <td style={{ padding: '6px 10px' }}><span style={{ fontFamily: 'monospace', fontSize: 10, borderRadius: 4, padding: '2px 6px', background: '#1e1b4b44', color: '#a5b4fc' }}>{c.cve}</span></td>
                        <td style={{ padding: '6px 10px' }}><span style={badge(sc)}>{c.severity}</span></td>
                        <td style={{ padding: '6px 10px', fontWeight: 700, color: sc }}>{c.cvss}</td>
                        <td style={{ padding: '6px 10px', color: '#22c55e', fontFamily: 'monospace', fontSize: 11 }}>{c.patched_in}</td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* Upgrade matrix */}
        {(result.outdated_audit.upgrade_matrix ?? []).length > 0 && (
          <div style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 14 }}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Upgrade Effort Matrix</div>
            <div style={{ overflowX: 'auto' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
                <thead>
                  <tr style={{ borderBottom: '1px solid var(--line)' }}>
                    {['Package', 'From', 'To', 'Breaking Changes', 'Effort', 'Security Fix'].map(h => (
                      <th key={h} style={{ textAlign: 'left', padding: '5px 10px', fontSize: 10, color: 'var(--muted)', fontWeight: 600 }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {(result.outdated_audit.upgrade_matrix ?? []).map((u, i) => {
                    const effortColor = u.effort === 'high' ? '#ef4444' : u.effort === 'medium' ? '#f59e0b' : '#22c55e';
                    return (
                      <tr key={`um-${i}`} style={{ borderBottom: '1px solid var(--line)' }}>
                        <td style={{ padding: '6px 10px', fontFamily: 'monospace', fontSize: 11, fontWeight: 700 }}>{u.name}</td>
                        <td style={{ padding: '6px 10px', fontFamily: 'monospace', fontSize: 10, color: 'var(--muted)' }}>{u.from_ver}</td>
                        <td style={{ padding: '6px 10px', fontFamily: 'monospace', fontSize: 10, color: '#22c55e', fontWeight: 700 }}>{u.to_ver}</td>
                        <td style={{ padding: '6px 10px', color: (u.breaking_changes ?? 0) > 0 ? '#f59e0b' : '#22c55e' }}>{u.breaking_changes}</td>
                        <td style={{ padding: '6px 10px' }}><span style={badge(effortColor)}>{u.effort}</span></td>
                        <td style={{ padding: '6px 10px' }}>{u.security_fix ? <span style={{ color: '#22c55e', fontWeight: 700 }}>Yes</span> : 'ÔÇö'}</td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* Dependencies list */}
        <div style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 14 }}>
          <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>All Outdated Dependencies</div>
          <div style={{ display: 'grid', gap: 6 }}>
            {(result.outdated_audit.deps ?? []).map((d, i) => (
              <div key={`dep-${i}`} style={{ display: 'grid', gridTemplateColumns: '1fr auto auto auto', gap: 10, alignItems: 'center', fontSize: 12, borderBottom: '1px solid var(--line)', paddingBottom: 6 }}>
                <div>
                  <span style={{ fontWeight: 700 }}>{d.name}</span>
                  <span style={{ color: 'var(--muted)', marginLeft: 6, fontSize: 10 }}>({d.type})</span>
                  {d.has_cve && <span style={{ marginLeft: 6, fontFamily: 'monospace', fontSize: 10, borderRadius: 4, padding: '1px 5px', background: '#450a0a44', color: '#fca5a5' }}>CVE</span>}
                </div>
                <span>{d.current} ÔåÆ <strong style={{ color: '#3b82f6' }}>{d.latest}</strong></span>
                <span style={{ color: 'var(--muted)', fontSize: 10 }}>{d.versions_behind ?? '?'} versions behind</span>
                <span style={{ background: depSeverityColor(d.severity), color: '#fff', borderRadius: 4, padding: '1px 7px', fontSize: 10, fontWeight: 700 }}>{d.severity}</span>
              </div>
            ))}
          </div>
        </div>

        {(result.outdated_audit.deprecated_apis ?? []).length > 0 && (
          <div style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 14 }}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Deprecated APIs</div>
            {(result.outdated_audit.deprecated_apis ?? []).map((a, i) => (
              <div key={`api-${i}`} style={{ marginBottom: 10, fontSize: 12 }}>
                <div style={{ fontWeight: 700, color: '#f97316' }}>{a.api}</div>
                <div style={{ color: 'var(--muted)' }}>Used in: {a.used_in} ┬À EOL: {a.eol}</div>
                <div>Use: <em>{a.alternative}</em></div>
              </div>
            ))}
          </div>
        )}

        {(result.outdated_audit.legacy_patterns ?? []).length > 0 && (
          <div style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 14 }}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Legacy Patterns</div>
            {(result.outdated_audit.legacy_patterns ?? []).map((p, i) => (
              <div key={`pat-${i}`} style={{ marginBottom: 10, fontSize: 12 }}>
                <div style={{ fontWeight: 700 }}>{p.pattern}</div>
                <div style={{ color: 'var(--muted)' }}>{p.file}</div>
                <div style={{ color: '#3b82f6' }}>ÔåÆ {p.recommendation}</div>
              </div>
            ))}
          </div>
        )}
      </>
    ) : (
      <div style={{ color: 'var(--muted)', fontSize: 12 }}>No outdated audit data available.</div>
    )}
  </section>
  );
}


function WorkflowTab({ result, card, isOfflinePreview }: PerfTabProps) {
  return (
  <section style={{ display: 'grid', gap: 12 }}>
    {result.workflow_audit ? (
      <>
        {/* Pipeline banner + MTTD/MTTR KPIs */}
        <div style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 14, display: 'flex', gap: 20, alignItems: 'center', flexWrap: 'wrap' }}>
          <div>
            <div style={{ fontSize: 11, color: 'var(--muted)' }}>Pipeline Status</div>
            <div style={{ fontWeight: 900, fontSize: 26, color: pipelineStatusColor(result.workflow_audit.pipeline_status) }}>{result.workflow_audit.pipeline_status ?? 'n/a'}</div>
            <div style={{ fontSize: 10, color: 'var(--muted)' }}>{result.workflow_audit.last_run ? new Date(result.workflow_audit.last_run).toLocaleString() : ''}</div>
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(120px, 1fr))', gap: 8, flex: 1 }}>
            {[
              { label: 'Test Coverage', value: `${result.workflow_audit.test_coverage_pct ?? 0}%`, color: (result.workflow_audit.test_coverage_pct ?? 0) >= 80 ? '#22c55e' : '#f59e0b' },
              { label: 'Mean Deploy', value: `${result.workflow_audit.mean_deploy_mins ?? 0}m`, color: 'var(--text)' },
              { label: 'Mean Recovery (MTTR)', value: `${result.workflow_audit.mean_recovery_mins ?? 0}m`, color: (result.workflow_audit.mean_recovery_mins ?? 0) > 60 ? '#ef4444' : '#22c55e' },
              { label: 'Flaky Tests', value: String((result.workflow_audit.flaky_tests ?? []).length), color: (result.workflow_audit.flaky_tests ?? []).length > 0 ? '#f59e0b' : '#22c55e' },
            ].map(kpi => (
              <div key={kpi.label} style={{ background: 'var(--bg)', border: '1px solid var(--line)', borderRadius: 8, padding: 8 }}>
                <div style={{ fontSize: 10, color: 'var(--muted)' }}>{kpi.label}</div>
                <div style={{ fontWeight: 700, fontSize: 18, color: kpi.color }}>{kpi.value}</div>
              </div>
            ))}
          </div>
        </div>

        {/* Build trend */}
        {(result.workflow_audit.build_trend ?? []).length > 0 && (
          <div style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 14 }}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Build Trend (7 days)</div>
            <div style={{ display: 'flex', gap: 8, alignItems: 'flex-end', height: 80 }}>
              {(result.workflow_audit.build_trend ?? []).map((b, i) => {
                const barColor = b.status === 'fail' ? '#ef4444' : b.status === 'warn' ? '#f59e0b' : '#22c55e';
                const maxMins = Math.max(...(result.workflow_audit?.build_trend ?? []).map(x => x.duration_mins ?? 0));
                const heightPct = Math.round(((b.duration_mins ?? 0) / maxMins) * 100);
                return (
                  <div key={`bt-${i}`} style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4 }}>
                    <div style={{ fontSize: 9, color: barColor, fontWeight: 700 }}>{b.duration_mins}m</div>
                    <div style={{ width: '100%', height: `${heightPct}%`, minHeight: 4, background: barColor, borderRadius: '4px 4px 0 0' }} />
                    <div style={{ fontSize: 9, color: 'var(--muted)' }}>{b.date}</div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* Test coverage bar */}
        <div style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 14 }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
            <div style={{ fontWeight: 700, fontSize: 13 }}>Test Coverage</div>
            <div style={{ fontWeight: 700, fontSize: 16, color: (result.workflow_audit.test_coverage_pct ?? 0) >= 80 ? '#22c55e' : '#f59e0b' }}>{result.workflow_audit.test_coverage_pct ?? 0}%</div>
          </div>
          <div style={{ height: 10, background: 'var(--line)', borderRadius: 4, overflow: 'hidden' }}>
            <div style={{ width: `${result.workflow_audit.test_coverage_pct ?? 0}%`, height: '100%', background: (result.workflow_audit.test_coverage_pct ?? 0) >= 80 ? '#22c55e' : '#f59e0b', borderRadius: 4 }} />
          </div>
          <div style={{ fontSize: 11, color: 'var(--muted)', marginTop: 6 }}>Target ÔëÑ80% ÔÇö currently {result.workflow_audit.test_coverage_pct ?? 0}%</div>
        </div>

        {/* Flaky tests */}
        {(result.workflow_audit.flaky_tests ?? []).length > 0 && (
          <div style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 14 }}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Flaky Tests</div>
            <div style={{ display: 'grid', gap: 8 }}>
              {(result.workflow_audit.flaky_tests ?? []).map((t, i) => {
                const flakePct = Math.round((t.flakiness_rate ?? 0) * 100);
                return (
                  <div key={`flaky-${i}`} style={{ background: 'var(--bg)', border: '1px solid var(--line)', borderRadius: 8, padding: 10 }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 8, marginBottom: 6, flexWrap: 'wrap' }}>
                      <div>
                        <div style={{ fontSize: 12, fontWeight: 700, fontFamily: 'monospace' }}>{t.test}</div>
                        <div style={{ fontSize: 10, color: 'var(--muted)' }}>{t.suite} ┬À last failed {t.last_failed}</div>
                      </div>
                      <div style={{ fontWeight: 700, fontSize: 14, color: flakePct >= 15 ? '#ef4444' : '#f59e0b' }}>{flakePct}% flaky</div>
                    </div>
                    <div style={{ height: 4, background: 'var(--line)', borderRadius: 2, overflow: 'hidden' }}>
                      <div style={{ width: `${flakePct}%`, height: '100%', background: flakePct >= 15 ? '#ef4444' : '#f59e0b', borderRadius: 2 }} />
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* Pipeline steps */}
        <div style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 14 }}>
          <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Pipeline Steps</div>
          <MiniBarChart items={(result.workflow_audit.steps ?? []).map(s => ({
            label: s.name ?? '',
            value: s.duration_ms ?? 0,
            color: stepColor(s.passed, s.status),
            suffix: 'ms',
          }))} />
        </div>

        {/* PR Checks */}
        <div style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 14 }}>
          <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>PR Checks</div>
          <div style={{ display: 'grid', gap: 8 }}>
            {(result.workflow_audit.pr_checks ?? []).map((c, i) => (
              <div key={`prc-${i}`} style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12, alignItems: 'center' }}>
                <span>{c.check} {c.required && <span style={{ color: '#ef4444', fontSize: 10 }}>(required)</span>}</span>
                <span style={{ fontWeight: 700, color: c.status === 'pass' ? '#22c55e' : '#ef4444' }}>{c.status?.toUpperCase()}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Deployments */}
        <div style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 14 }}>
          <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Deployment History</div>
          <div style={{ display: 'grid', gap: 8 }}>
            {(result.workflow_audit.deployments ?? []).map((d, i) => (
              <div key={`dep-${i}`} style={{ display: 'grid', gridTemplateColumns: 'auto 1fr auto auto', gap: 10, alignItems: 'center', fontSize: 12 }}>
                <span style={{ fontWeight: 700 }}>{d.version}</span>
                <span style={{ color: 'var(--muted)' }}>{d.deployed_at ? new Date(d.deployed_at).toLocaleString() : ''}</span>
                <span style={{ color: d.rollback ? '#ef4444' : '#22c55e', fontWeight: 700 }}>{d.rollback ? 'rolled back' : d.status}</span>
                <span style={{ fontWeight: 700, color: perfDeltaColor(d.perf_delta_ms) }}>{(d.perf_delta_ms ?? 0) > 0 ? '+' : ''}{d.perf_delta_ms}ms</span>
              </div>
            ))}
          </div>
        </div>

        {result.workflow_audit.integration_health && (
          <div style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 14 }}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Integration Health</div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(150px, 1fr))', gap: 8 }}>
              {Object.entries(result.workflow_audit.integration_health).map(([svc, health]) => (
                <div key={svc} style={{ background: 'var(--bg)', border: '1px solid var(--line)', borderRadius: 8, padding: '8px 12px', fontSize: 12 }}>
                  <div style={{ color: 'var(--muted)', fontSize: 10 }}>{svc}</div>
                  <div style={{ fontWeight: 700, color: integrationHealthColor(health) }}>{health}</div>
                </div>
              ))}
            </div>
          </div>
        )}
      </>
    ) : (
      <div style={{ color: 'var(--muted)', fontSize: 12 }}>No workflow audit data available.</div>
    )}
  </section>
  );
}


function DataAnalysisTab({ result, card, isOfflinePreview }: PerfTabProps) {
  return (
  <section style={{ display: 'grid', gap: 12 }}>
    {result.data_analysis ? (
      <>
        {/* Search Console KPIs */}
        {result.data_analysis.search_console && (
          <div style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 14 }}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Search Console Summary</div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(150px, 1fr))', gap: 10, marginBottom: 14 }}>
              {[
                { label: 'Impressions', value: (result.data_analysis.search_console.impressions ?? 0).toLocaleString(), color: '#6366f1' },
                { label: 'Clicks', value: (result.data_analysis.search_console.clicks ?? 0).toLocaleString(), color: '#22c55e' },
                { label: 'CTR', value: `${((result.data_analysis.search_console.ctr_pct ?? 0)).toFixed(1)}%`, color: '#3b82f6' },
                { label: 'Avg Position', value: (result.data_analysis.search_console.avg_position ?? 0).toFixed(1), color: '#f59e0b' },
              ].map(kpi => (
                <div key={kpi.label} style={{ background: 'var(--bg)', border: '1px solid var(--line)', borderRadius: 8, padding: 10 }}>
                  <div style={{ fontSize: 10, color: 'var(--muted)' }}>{kpi.label}</div>
                  <div style={{ fontWeight: 800, fontSize: 20, color: kpi.color, marginTop: 4 }}>{kpi.value}</div>
                </div>
              ))}
            </div>
            {(result.data_analysis.search_console.top_queries ?? []).length > 0 && (
              <>
                <div style={{ fontWeight: 700, fontSize: 12, marginBottom: 8 }}>Top Queries</div>
                <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
                  <thead>
                    <tr style={{ borderBottom: '1px solid var(--line)' }}>
                      {['Query', 'Impressions', 'Clicks', 'CTR', 'Position'].map(h => (
                        <th key={h} style={{ textAlign: 'left', padding: '4px 8px', fontSize: 10, color: 'var(--muted)', fontWeight: 600 }}>{h}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {(result.data_analysis.search_console.top_queries ?? []).map((q, i) => (
                      <tr key={`q-${i}`} style={{ borderBottom: '1px solid var(--line)' }}>
                        <td style={{ padding: '5px 8px', fontWeight: 600 }}>{q.query}</td>
                        <td style={{ padding: '5px 8px' }}>ÔÇö</td>
                        <td style={{ padding: '5px 8px', color: '#22c55e' }}>{q.clicks}</td>
                        <td style={{ padding: '5px 8px' }}>ÔÇö</td>
                        <td style={{ padding: '5px 8px', color: (q.position ?? 99) <= 3 ? '#22c55e' : '#f59e0b' }}>{(q.position ?? 0).toFixed(1)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </>
            )}
          </div>
        )}

        {/* Retention cohorts */}
        {(result.data_analysis.retention ?? []).length > 0 && (
          <div style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 14 }}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>User Retention Cohorts</div>
            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
              <thead>
                <tr style={{ borderBottom: '1px solid var(--line)' }}>
                  {['Cohort Week', 'D1 Retention', 'D7 Retention', 'D30 Retention'].map(h => (
                    <th key={h} style={{ textAlign: 'left', padding: '5px 10px', fontSize: 10, color: 'var(--muted)', fontWeight: 600 }}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {(result.data_analysis.retention ?? []).map((r, i) => {
                  const d1c = (r.d1_pct ?? 0) >= 50 ? '#22c55e' : (r.d1_pct ?? 0) >= 30 ? '#f59e0b' : '#ef4444';
                  const d7c = (r.d7_pct ?? 0) >= 20 ? '#22c55e' : (r.d7_pct ?? 0) >= 10 ? '#f59e0b' : '#ef4444';
                  const d30c = (r.d30_pct ?? 0) >= 10 ? '#22c55e' : (r.d30_pct ?? 0) >= 5 ? '#f59e0b' : '#ef4444';
                  return (
                    <tr key={`ret-${i}`} style={{ borderBottom: '1px solid var(--line)' }}>
                      <td style={{ padding: '6px 10px', fontWeight: 600 }}>{r.week}</td>
                      <td style={{ padding: '6px 10px', fontWeight: 700, color: d1c }}>{r.d1_pct}%</td>
                      <td style={{ padding: '6px 10px', fontWeight: 700, color: d7c }}>{r.d7_pct}%</td>
                      <td style={{ padding: '6px 10px', fontWeight: 700, color: d30c }}>{r.d30_pct}%</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}

        {/* Revenue by channel */}
        {(result.data_analysis.revenue_by_channel ?? []).length > 0 && (
          <div style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 14 }}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Revenue by Channel</div>
            <MiniBarChart items={(result.data_analysis.revenue_by_channel ?? []).map(c => ({
              label: c.channel ?? '',
              value: c.revenue_usd ?? 0,
              color: '#22c55e',
              max: Math.max(...(result.data_analysis?.revenue_by_channel ?? []).map(x => x.revenue_usd ?? 0)),
              suffix: ' USD',
            }))} />
            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12, marginTop: 12 }}>
              <thead>
                <tr style={{ borderBottom: '1px solid var(--line)' }}>
                  {['Channel', 'Revenue', 'Sessions', 'Conv. Rate'].map(h => (
                    <th key={h} style={{ textAlign: 'left', padding: '4px 8px', fontSize: 10, color: 'var(--muted)', fontWeight: 600 }}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {(result.data_analysis.revenue_by_channel ?? []).map((c, i) => (
                  <tr key={`rev-${i}`} style={{ borderBottom: '1px solid var(--line)' }}>
                    <td style={{ padding: '5px 8px', fontWeight: 600 }}>{c.channel}</td>
                    <td style={{ padding: '5px 8px', color: '#22c55e', fontWeight: 700 }}>${(c.revenue_usd ?? 0).toLocaleString()}</td>
                    <td style={{ padding: '5px 8px' }}>{(c.sessions ?? 0).toLocaleString()}</td>
                    <td style={{ padding: '5px 8px', color: '#3b82f6' }}>{((c.conv_rate ?? 0) * 100).toFixed(1)}%</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* Existing: cohort trend, funnel, anomalies, segment */}
        {(result.data_analysis.cohort_trend ?? []).length > 0 && (
          <div style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 14 }}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 8 }}>Performance Score ÔÇö Weekly Cohort Trend</div>
            <AreaChart
              points={(result.data_analysis.cohort_trend ?? []).map(c => c.score ?? 0)}
              labels={(result.data_analysis.cohort_trend ?? []).map(c => c.period ?? '')}
              color="#3b82f6"
              height={80}
            />
            <div style={{ marginTop: 10 }}>
              <div style={{ fontWeight: 700, fontSize: 12, marginBottom: 6 }}>LCP Trend (ms)</div>
              <AreaChart
                points={(result.data_analysis.cohort_trend ?? []).map(c => c.lcp ?? 0)}
                labels={(result.data_analysis.cohort_trend ?? []).map(c => c.period ?? '')}
                color="#f97316"
                height={72}
              />
            </div>
          </div>
        )}

        {(result.data_analysis.funnel ?? []).length > 0 && (
          <div style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 14 }}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Conversion Funnel</div>
            <div style={{ display: 'grid', gap: 8 }}>
              {(result.data_analysis.funnel ?? []).map((step, i) => {
                const maxUsers = result.data_analysis?.funnel?.[0]?.users ?? 1;
                const pct = (step.users ?? 0) / maxUsers;
                return (
                  <div key={`fn-${i}`} style={{ display: 'flex', alignItems: 'center', gap: 10, fontSize: 12 }}>
                    <div style={{ width: 120, textAlign: 'right', color: 'var(--muted)', flexShrink: 0 }}>{step.name}</div>
                    <div style={{ flex: 1, height: 20, background: 'var(--line)', borderRadius: 4, overflow: 'hidden' }}>
                      <div style={{ width: `${pct * 100}%`, height: '100%', background: funnelBarColor(pct, i === 0), borderRadius: 4 }} />
                    </div>
                    <div style={{ width: 60, fontWeight: 700 }}>{(step.users ?? 0).toLocaleString()}</div>
                    {i > 0 && <div style={{ width: 64, color: '#ef4444', fontSize: 11 }}>-{step.drop_pct?.toFixed(1)}%</div>}
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {(result.data_analysis.anomalies ?? []).length > 0 && (
          <div style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 14 }}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Anomaly Detection</div>
            {(result.data_analysis.anomalies ?? []).map((a, i) => (
              <div key={`anm-${i}`} style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12, alignItems: 'center', borderBottom: '1px solid var(--line)', paddingBottom: 8, marginBottom: 8 }}>
                <span style={{ fontWeight: 700, color: '#f97316' }}>{a.metric}</span>
                <span>Detected: {a.ts ? new Date(a.ts).toLocaleString() : 'n/a'}</span>
                <span>Actual: <strong>{a.value}</strong> ┬À Expected: <strong>{a.expected}</strong></span>
                <span style={{ background: a.severity === 'high' ? '#ef4444' : '#f59e0b', color: '#fff', borderRadius: 4, padding: '1px 7px', fontSize: 10, fontWeight: 700 }}>{a.severity}</span>
              </div>
            ))}
          </div>
        )}

        {result.data_analysis.segment_breakdown && (
          <div style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 14 }}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Traffic Segment Breakdown</div>
            <MiniBarChart items={Object.entries(result.data_analysis.segment_breakdown).map(([seg, d]) => ({
              label: seg,
              value: d.sessions ?? 0,
              suffix: ' sess',
            }))} />
          </div>
        )}

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(180px, 1fr))', gap: 10 }}>
          <div style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 14, textAlign: 'center' }}>
            <div style={{ fontSize: 11, color: 'var(--muted)' }}>Bot Traffic</div>
            <div style={{ fontWeight: 800, fontSize: 22, color: (result.data_analysis.bot_traffic_pct ?? 0) > 15 ? '#ef4444' : '#f59e0b' }}>{result.data_analysis.bot_traffic_pct}%</div>
          </div>
          <div style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 14, textAlign: 'center' }}>
            <div style={{ fontSize: 11, color: 'var(--muted)' }}>Crawl Efficiency</div>
            <div style={{ fontWeight: 800, fontSize: 22, color: '#22c55e' }}>{result.data_analysis.crawl_efficiency}%</div>
          </div>
        </div>
      </>
    ) : (
      <div style={{ color: 'var(--muted)', fontSize: 12 }}>No data analysis available.</div>
    )}
  </section>
  );
}


