      {autoFixResult && (
        <div style={{ marginTop: 12, fontSize: 12, color: 'var(--muted)' }}>
          Last run: {new Date(autoFixResult.applied_at).toLocaleString()} &middot; {autoFixResult.fixes_applied.length} fixes applied &middot; {autoFixResult.total_gain_ms}ms total gain
        </div>
      )}
    </div>
  </section>
  );
}


