export default function PerformanceAuditPage() {
  const [url, setUrl] = useState('https://example.com');
  const [targetDevice, setTargetDevice] = useState<'mobile' | 'desktop'>('mobile');
  const [targetRegion, setTargetRegion] = useState('lhr1');
  const [connection, setConnection] = useState('4g');
  const [browser, setBrowser] = useState('chrome');
  const [notes, setNotes] = useState('');

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [isOfflinePreview, setIsOfflinePreview] = useState(false);
  const [result, setResult] = useState<PerformanceAuditResponse | null>(null);
  const [tab, setTab] = useState<Tab>('summary');

  const [autoFixing, setAutoFixing] = useState(false);
  const [autoFixResult, setAutoFixResult] = useState<AutoFixResult | null>(null);
  const [autoFixError, setAutoFixError] = useState('');

  const [historyLoading, setHistoryLoading] = useState(false);
  const [historyData, setHistoryData] = useState<HistoryResponse | null>(null);

  const [fixingItem, setFixingItem] = useState<string | null>(null);
  const [fixedItems, setFixedItems] = useState<Set<string>>(new Set());

  const card: React.CSSProperties = {
    background: 'var(--bg-soft)',
    border: '1px solid var(--line)',
    borderRadius: 12,
    padding: 16,
  };
  const inputStyle: React.CSSProperties = {
    width: '100%',
    padding: '8px 10px',
    borderRadius: 8,
    border: '1px solid var(--line)',
    background: 'var(--bg)',
    color: 'var(--text)',
    boxSizing: 'border-box',
  };

  const runAudit = useCallback(async () => {
    setLoading(true);
    setError('');
    setIsOfflinePreview(false);
    setAutoFixResult(null);
    setFixedItems(new Set());
    try {
      const response = await apiSend<PerformanceAuditResponse>(
        '/seo-platform/performance/audit',
        'POST',
        { url: url.trim(), target_device: targetDevice, target_region: targetRegion, connection, browser, notes: notes.trim() },
        DEFAULT_TENANT_ID
      );
      setResult(response);
      setIsOfflinePreview(false);
      setTab('summary');
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Performance audit failed.';
      if (isNetworkFetchFailure(message)) {
        setError('Live backend is unreachable. Showing offline preview sample data. Start FastAPI on :8001 and re-run for real results.');
        setIsOfflinePreview(true);
        setResult(
          offlineAuditFallback({
            url: url.trim() || 'https://example.com',
            targetDevice,
            targetRegion,
          })
        );
        setTab('summary');
      } else {
        setError(message);
        setIsOfflinePreview(false);
        setResult(null);
      }
    } finally {
      setLoading(false);
    }
  }, [url, targetDevice, targetRegion, connection, browser, notes]);

  const optimizeSite = useCallback(async () => {
    if (!result) return;
    setAutoFixing(true);
    setAutoFixError('');
    try {
      const candidates = result.ai_remediation?.auto_fix_candidates ?? [];
      const response = await apiSend<AutoFixResult>(
        '/seo-platform/performance/auto-fix',
        'POST',
        { url: result.url, candidates },
        DEFAULT_TENANT_ID
      );
      setAutoFixResult(response);
      setTab('ai-fixes');
    } catch (err) {
      setAutoFixError(err instanceof Error ? err.message : 'Auto-fix failed.');
    } finally {
      setAutoFixing(false);
    }
  }, [result]);

  const fixSingleItem = useCallback(async (candidate: AutoFixCandidate) => {
    if (!result || !candidate.title) return;
    const key = candidate.title;
    setFixingItem(key);
    try {
      await apiSend<AutoFixResult>(
        '/seo-platform/performance/auto-fix',
        'POST',
        { url: result.url, candidates: [candidate] },
        DEFAULT_TENANT_ID
      );
      setFixedItems(prev => new Set(prev).add(key));
    } catch { /* per-item error is non-critical */ }
    setFixingItem(null);
  }, [result]);

  const loadHistory = useCallback(async () => {
    if (!url) return;
    setHistoryLoading(true);
    try {
      const data = await apiGet<HistoryResponse>(
        `/seo-platform/performance/history?url=${encodeURIComponent(url.trim())}`,
        DEFAULT_TENANT_ID
      );
      setHistoryData(data);
      setTab('history');
    } catch { /* silent */ }
    setHistoryLoading(false);
  }, [url]);

  const exportReport = useCallback(() => {
    if (!result) return;
    const lines = [
      'Performance Audit Report',
      '========================',
      `URL: ${result.url}`,
      `Audited: ${result.audited_at ?? 'n/a'}`,
      `Device: ${result.target_device} | Region: ${result.target_region}`,
      '',
      `Performance Score: ${result.performance_score} (${scoreGrade(result.performance_score)})`,
      '',
      'Core Web Vitals',
      `  LCP: ${result.core_web_vitals?.lcp_ms ?? 0}ms`,
      `  INP: ${result.core_web_vitals?.inp_ms ?? 0}ms`,
      `  CLS: ${result.core_web_vitals?.cls ?? 0}`,
      `  TTFB: ${result.core_web_vitals?.ttfb_ms ?? 0}ms`,
      '',
      'Lighthouse',
      `  Performance: ${result.lighthouse?.performance ?? 0}`,
      `  SEO: ${result.lighthouse?.seo ?? 0}`,
      `  Best Practices: ${result.lighthouse?.best_practices ?? 0}`,
      '',
      'Opportunities',
      ...(result.opportunities ?? []).map(o => `  [${o.priority}] ${o.issue}: ${o.impact}`),
      '',
      'AI Remediation',
      result.ai_remediation?.summary ?? '',
      ...(result.ai_remediation?.auto_fix_candidates ?? []).map(c =>
        `  - ${c.title} (confidence: ${c.confidence}, gain: ${c.estimated_gain_ms}ms)`
      ),
    ].join('\n');
    const blob = new Blob([lines], { type: 'text/plain' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `performance-audit-${Date.now()}.txt`;
    a.click();
    URL.revokeObjectURL(a.href);
  }, [result]);

  const TABS: { id: Tab; label: string }[] = [
    { id: 'summary', label: 'Summary' },
    { id: 'waterfall', label: 'Waterfall' },
    { id: 'filmstrip', label: 'Filmstrip' },
    { id: 'rum', label: 'RUM' },
    { id: 'causality', label: 'Causality' },
    { id: 'agents', label: 'Synthetic Agents' },
    { id: 'prediction', label: 'Prediction' },
    { id: 'global', label: 'Global Mesh' },
    { id: 'business', label: 'Business Impact' },
    { id: 'ci-gate', label: 'CI Gate' },
    { id: 'slo', label: 'SLO Guardrails' },
    { id: 'roi', label: 'ROI Matrix' },
    { id: 'copilot', label: 'Perf Copilot' },
    { id: 'opportunities', label: result?.opportunities?.length ? `Opportunities (${result.opportunities.length})` : 'Opportunities' },
    { id: 'ai-fixes', label: 'AI Auto-Fix' },
    { id: 'images', label: result?.image_audit ? `Images (${result.image_audit.unoptimized ?? 0} issues)` : 'Images' },
    { id: 'security', label: result?.security_audit ? `Security (CSP ${result.security_audit.csp_score ?? 0})` : 'Security' },
    { id: 'javascript', label: result?.js_audit ? `JavaScript (${result.js_audit.unused_pct?.toFixed(0) ?? 0}% unused)` : 'JavaScript' },
    { id: 'css', label: result?.css_audit ? `CSS (${result.css_audit.unused_pct?.toFixed(0) ?? 0}% unused)` : 'CSS' },
    { id: 'input-validation', label: result?.input_validation_audit ? `Input Val. (${(result.input_validation_audit.xss_risks ?? 0) + (result.input_validation_audit.injection_risks ?? 0)} risks)` : 'Input Validation' },
    { id: 'latency', label: result?.latency_audit ? `Latency (p99 ${result.latency_audit.overall?.p99 ?? 0}ms)` : 'Latency' },
    { id: 'outdated', label: result?.outdated_audit ? `Outdated (${result.outdated_audit.outdated_count ?? 0})` : 'Outdated' },
    { id: 'workflow', label: result?.workflow_audit ? `Workflow (${result.workflow_audit.pipeline_status ?? 'n/a'})` : 'Workflow' },
    { id: 'data-analysis', label: 'Data Analysis' },
    { id: 'core-seo', label: result?.core_seo_suite ? `Core SEO (${result.core_seo_suite.coverage ?? 0}%)` : 'Core SEO' },
    { id: 'content-blogging', label: result?.content_blog_suite ? `Content (${result.content_blog_suite.opportunity_count ?? 0})` : 'Content & Blogging' },
    { id: 'ai-optimization', label: result?.ai_optimization_suite ? `AI SEO (${result.ai_optimization_suite.coverage ?? 0}%)` : 'AI Optimization' },
    { id: 'search-experience', label: result?.search_experience_suite ? `Search X (${result.search_experience_suite.coverage ?? 0}%)` : 'Search Experience' },
    { id: 'vertical-seo', label: result?.vertical_seo_suite ? `Verticals (${result.vertical_seo_suite.coverage ?? 0}%)` : 'Vertical SEO' },
    { id: 'platform-ops', label: result?.platform_ops_suite ? `Platform (${result.platform_ops_suite.opportunity_count ?? 0})` : 'Platform Ops' },
    { id: 'accessibility', label: result?.accessibility_audit ? `Accessibility (${result.accessibility_audit.wcag_score ?? 0})` : 'Accessibility' },
    { id: 'competitor-intel', label: result?.competitor_intel ? `Competitor (${result.competitor_intel.keyword_gap ?? 0} gaps)` : 'Competitor Intel' },
    { id: 'schema-entities', label: result?.schema_entities ? `Schema (${result.schema_entities.validated ?? 0}/${result.schema_entities.total_schemas ?? 0})` : 'Schema & Entities' },
    { id: 'technical-deep', label: result?.technical_deep ? `Tech Deep (${result.technical_deep.crawl_efficiency_pct ?? 0}%)` : 'Technical Deep' },
    { id: 'trust-revenue', label: result?.trust_revenue ? `Trust ($${((result.trust_revenue.seo_revenue_total_usd ?? 0) / 1000).toFixed(0)}k)` : 'Trust & Revenue' },
    { id: 'ux-conversion', label: result?.ux_conversion ? `UX (${result.ux_conversion.ux_score ?? 0})` : 'UX & Conversion' },
    { id: 'growth-landing', label: result?.growth_landing ? `Growth (${result.growth_landing.playbook_score ?? 0})` : 'Growth & Landing' },
    { id: 'live-intelligence', label: result?.live_intelligence ? `Live (p${result.live_intelligence.avg_position ?? 0})` : 'Live Intel' },
    { id: 'history', label: 'History' },
    { id: 'monitoring', label: 'Monitoring' },
    { id: 'keywords', label: 'Keywords' },
    { id: 'seo-ranking', label: 'SEO Ranking' },
    { id: 'ai-models-ranking', label: 'AI Models Ranking' },
    { id: 'hashtags', label: 'Hashtags' },
    { id: 'visibility', label: 'Visibility' },
    { id: 'leads', label: 'Leads' },
    { id: 'clicks', label: 'Clicks' },
    { id: 'trends-vs-platform', label: 'Trends vs Platform' },
    { id: 'power-ranking', label: 'Power Ranking' },
    { id: 'autonomous', label: 'Autonomous' },
  ];

  return (
    <main style={{ minHeight: '100vh', background: 'var(--bg)', color: 'var(--text)', padding: 24 }}>
      <div style={{ maxWidth: 1060, margin: '0 auto' }}>

        {/* Header */}
        <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', marginBottom: 20, flexWrap: 'wrap', gap: 12 }}>
          <div>
            <h1 style={{ margin: 0, fontSize: 22, fontWeight: 800 }}>GTmetrix-Style Performance Audit</h1>
            <p style={{ color: 'var(--muted)', margin: '4px 0 0', fontSize: 13 }}>
              Lighthouse scoring ┬À Core Web Vitals ┬À Waterfall ┬À Filmstrip ┬À AI Auto-Fix ┬À Global Testing
            </p>
          </div>
          {result && (
            <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
              <button type="button" style={btn()} onClick={loadHistory} disabled={historyLoading}>
                {historyLoading ? 'Loading...' : 'History'}
              </button>
              <button type="button" style={btn()} onClick={exportReport}>Export Report</button>
              <button
                type="button"
                onClick={optimizeSite}
                disabled={autoFixing}
                style={{ ...btn(true), background: '#7c3aed', color: '#fff' }}
              >
                {autoFixing ? 'Optimizing...' : 'Optimize Site'}
              </button>
            </div>
          )}
        </div>

        {/* Config Panel */}
        <section style={{ ...card, marginBottom: 16 }}>
          <div style={{ display: 'grid', gap: 10 }}>
            <div>
              <label htmlFor="perf-url" style={{ display: 'block', fontSize: 12, fontWeight: 700, marginBottom: 4 }}>Website URL</label>
              <input
                id="perf-url" value={url}
                onChange={e => setUrl(e.target.value)}
                placeholder="https://example.com"
                style={inputStyle}
                onKeyDown={e => e.key === 'Enter' && runAudit()}
              />
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(180px, 1fr))', gap: 10 }}>
              <div>
                <label htmlFor="perf-device" style={{ display: 'block', fontSize: 12, fontWeight: 700, marginBottom: 4 }}>Device</label>
                <select id="perf-device" value={targetDevice} onChange={e => setTargetDevice(e.target.value as 'mobile' | 'desktop')} style={inputStyle}>
                  <option value="mobile">Mobile</option>
                  <option value="desktop">Desktop</option>
                </select>
              </div>
              <div>
                <label htmlFor="perf-region" style={{ display: 'block', fontSize: 12, fontWeight: 700, marginBottom: 4 }}>Test Location</label>
                <select id="perf-region" value={targetRegion} onChange={e => setTargetRegion(e.target.value)} style={inputStyle}>
                  {REGIONS.map(r => <option key={r.value} value={r.value}>{r.label}</option>)}
                </select>
              </div>
              <div>
                <label htmlFor="perf-conn" style={{ display: 'block', fontSize: 12, fontWeight: 700, marginBottom: 4 }}>Connection Speed</label>
                <select id="perf-conn" value={connection} onChange={e => setConnection(e.target.value)} style={inputStyle}>
                  {CONNECTIONS.map(c => <option key={c.value} value={c.value}>{c.label}</option>)}
                </select>
              </div>
              <div>
                <label htmlFor="perf-browser" style={{ display: 'block', fontSize: 12, fontWeight: 700, marginBottom: 4 }}>Browser</label>
                <select id="perf-browser" value={browser} onChange={e => setBrowser(e.target.value)} style={inputStyle}>
                  <option value="chrome">Chrome</option>
                  <option value="firefox">Firefox</option>
                  <option value="safari">Safari</option>
                  <option value="edge">Edge</option>
                </select>
              </div>
            </div>
            <div style={{ display: 'flex', gap: 10, alignItems: 'flex-end', flexWrap: 'wrap' }}>
              <div style={{ flex: 1, minWidth: 200 }}>
                <label htmlFor="perf-notes" style={{ display: 'block', fontSize: 12, fontWeight: 700, marginBottom: 4 }}>Notes (optional)</label>
                <input id="perf-notes" value={notes} onChange={e => setNotes(e.target.value)} style={inputStyle} placeholder="e.g. focus on mobile LCP" />
              </div>
              <button type="button" onClick={runAudit} disabled={loading} style={{ ...btn(true), whiteSpace: 'nowrap' }}>
                {loading ? 'Auditing...' : 'Run Audit'}
              </button>
            </div>
            {error && (
              <div
                style={{
                  color: isOfflinePreview ? '#fde68a' : '#fca5a5',
                  fontSize: 12,
                  padding: '6px 10px',
                  background: isOfflinePreview ? '#78350f33' : '#7f1d1d22',
                  borderRadius: 6,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  gap: 10,
                  flexWrap: 'wrap',
                }}
              >
                <span>{error}</span>
                {isOfflinePreview && (
                  <button type="button" onClick={runAudit} disabled={loading} style={btn(true)}>
                    Retry Live Backend
                  </button>
                )}
              </div>
            )}
          </div>
        </section>

        {loading && (
          <section style={{ ...card, marginBottom: 16, textAlign: 'center', padding: 40 }}>
            <div style={{ fontSize: 14, color: 'var(--muted)', marginBottom: 8 }}>Running performance audit...</div>
            <div style={{ fontSize: 12, color: 'var(--muted)' }}>
              Testing {targetDevice} from {REGIONS.find(r => r.value === targetRegion)?.label ?? targetRegion} on {connection.toUpperCase()}
            </div>
          </section>
        )}

        {result && !loading && (
          <>
            {/* Score Row */}
            <section style={{ ...card, marginBottom: 16 }}>
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: 12, marginBottom: 16 }}>
                <div>
                  <div style={{ fontSize: 12, color: 'var(--muted)' }}>{result.url}</div>
                  <div style={{ fontSize: 11, color: 'var(--muted)' }}>
                    {result.audited_at ? new Date(result.audited_at).toLocaleString() : ''} &middot; {result.target_device} &middot; {REGIONS.find(r => r.value === result.target_region)?.label ?? result.target_region}
                  </div>
                </div>
                <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
                  {isOfflinePreview && <span style={badge('#f59e0b')}>Offline Preview</span>}
                  {result.history?.regression_detected && (
                    <span style={badge('#ef4444')}>Regression Detected</span>
                  )}
                  {result.alerts?.status === 'healthy' && (
                    <span style={badge('#22c55e')}>All alerts healthy</span>
                  )}
                </div>
              </div>
              <div style={{ display: 'flex', gap: 24, flexWrap: 'wrap', justifyContent: 'center' }}>
                <ScoreGauge score={result.performance_score} label="GTmetrix Score" />
                {result.lighthouse?.performance !== undefined && (
                  <ScoreGauge score={result.lighthouse.performance} label="Performance" />
                )}
                {result.lighthouse?.seo !== undefined && (
                  <ScoreGauge score={result.lighthouse.seo} label="SEO" />
                )}
                {result.lighthouse?.best_practices !== undefined && (
                  <ScoreGauge score={result.lighthouse.best_practices} label="Best Practices" />
                )}
                {result.lighthouse?.accessibility !== undefined && (
                  <ScoreGauge score={result.lighthouse.accessibility} label="Accessibility" />
                )}
              </div>
            </section>

            {/* Auto-fix banner */}
            {autoFixResult && (
              <section style={{ ...card, marginBottom: 16, background: '#14532d22', border: '1px solid #22c55e44' }}>
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: 8 }}>
                  <div>
                    <div style={{ fontWeight: 700, color: '#22c55e', marginBottom: 4 }}>Site Optimization Applied</div>
                    <div style={{ fontSize: 12, color: 'var(--muted)' }}>
                      {autoFixResult.fixes_applied.filter(f => f.status === 'applied').length} fixes applied &middot; Total gain: {autoFixResult.total_gain_ms}ms &middot; New score: {autoFixResult.new_performance_score}
                    </div>
                  </div>
                  {autoFixResult.rerun_recommended && (
                    <button type="button" style={btn(true)} onClick={runAudit}>Re-run Audit</button>
                  )}
                </div>
              </section>
            )}
            {autoFixError && (
              <section style={{ ...card, marginBottom: 16, background: '#7f1d1d22' }}>
                <div style={{ color: '#fca5a5', fontSize: 12 }}>{autoFixError}</div>
              </section>
            )}

            {/* Core Web Vitals */}
            <section style={{ marginBottom: 16 }}>
              <div style={{ fontSize: 12, fontWeight: 700, marginBottom: 8, color: 'var(--muted)', textTransform: 'uppercase', letterSpacing: 1 }}>Core Web Vitals</div>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(160px, 1fr))', gap: 10 }}>
                {[
                  { key: 'lcp', label: 'LCP', value: result.core_web_vitals?.lcp_ms ?? 0, unit: 'ms', desc: 'Largest Contentful Paint' },
                  { key: 'inp', label: 'INP', value: result.core_web_vitals?.inp_ms ?? 0, unit: 'ms', desc: 'Interaction to Next Paint' },
                  { key: 'cls', label: 'CLS', value: result.core_web_vitals?.cls ?? 0, unit: '', desc: 'Cumulative Layout Shift' },
                  { key: 'ttfb', label: 'TTFB', value: result.core_web_vitals?.ttfb_ms ?? 0, unit: 'ms', desc: 'Time to First Byte' },
                ].map(({ key, value, unit, desc }) => {
                  const status = cwvStatus(key, value);
                  const color = cwvColor(status);
                  return (
                    <div key={key} style={{ ...card, padding: 12, borderLeft: `3px solid ${color}` }}>
                      <div style={{ fontSize: 11, color: 'var(--muted)', marginBottom: 2 }}>{desc}</div>
                      <div style={{ fontSize: 22, fontWeight: 800, color }}>{value}{unit}</div>
                      <span style={badge(color)}>{status.replace('-', ' ')}</span>
                    </div>
                  );
                })}
              </div>
            </section>

            {/* Field Web Vitals */}
            {result.field_web_vitals && (
              <section style={{ ...card, marginBottom: 16 }}>
                <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Field Data (Real User Monitoring)</div>
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(150px, 1fr))', gap: 8, fontSize: 12 }}>
                  <div><div style={{ color: 'var(--muted)' }}>LCP p75</div><div style={{ fontWeight: 700, fontSize: 16 }}>{result.field_web_vitals.lcp_p75_ms ?? 0}ms</div></div>
                  <div><div style={{ color: 'var(--muted)' }}>INP p75</div><div style={{ fontWeight: 700, fontSize: 16 }}>{result.field_web_vitals.inp_p75_ms ?? 0}ms</div></div>
                  <div><div style={{ color: 'var(--muted)' }}>CLS p75</div><div style={{ fontWeight: 700, fontSize: 16 }}>{result.field_web_vitals.cls_p75 ?? 0}</div></div>
                  <div><div style={{ color: 'var(--muted)' }}>RUM Samples</div><div style={{ fontWeight: 700, fontSize: 16 }}>{(result.field_web_vitals.sample_size ?? 0).toLocaleString()}</div></div>
                  <div><div style={{ color: 'var(--muted)' }}>Period</div><div style={{ fontWeight: 700, fontSize: 16 }}>{result.field_web_vitals.period ?? 'n/a'}</div></div>
                  <div><div style={{ color: 'var(--muted)' }}>Source</div><div style={{ fontWeight: 700, fontSize: 16 }}>{result.field_web_vitals.source ?? 'n/a'}</div></div>
                </div>
              </section>
            )}

            {/* Page Stats */}
            <section style={{ ...card, marginBottom: 16 }}>
              <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>Page Stats</div>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(140px, 1fr))', gap: 8, fontSize: 12 }}>
                <div><div style={{ color: 'var(--muted)' }}>Total Requests</div><div style={{ fontWeight: 700, fontSize: 18 }}>{result.waterfall?.requests ?? 0}</div></div>
                <div><div style={{ color: 'var(--muted)' }}>Transfer Size</div><div style={{ fontWeight: 700, fontSize: 18 }}>{result.waterfall?.transfer_kb ?? 0} KB</div></div>
                <div><div style={{ color: 'var(--muted)' }}>Render-blocking</div><div style={{ fontWeight: 700, fontSize: 18 }}>{(result.waterfall?.render_blocking ?? []).length}</div></div>
                <div><div style={{ color: 'var(--muted)' }}>Trend</div><div style={{ fontWeight: 700, fontSize: 18 }}>{result.history?.trend ?? 'n/a'}</div></div>
              </div>
            </section>

            {/* Tab bar */}
            <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap', marginBottom: 12 }}>
              {TABS.map(t => (
                <button
                  key={t.id}
                  type="button"
                  onClick={() => setTab(t.id)}
                  style={{
                    padding: '7px 14px',
                    borderRadius: 8,
                    border: '1px solid var(--line)',
                    background: tab === t.id ? 'var(--brand)' : 'var(--bg)',
                    color: tab === t.id ? '#00101e' : 'var(--text)',
                    fontWeight: 700,
                    fontSize: 12,
                    cursor: 'pointer',
                  }}
                >
                  {t.label}
                </button>
              ))}
            </div>

            {/* Summary */}
            {tab === 'summary' && <SummaryTab result={result} card={card} isOfflinePreview={isOfflinePreview} autoFixing={autoFixing} autoFixResult={autoFixResult} autoFixError={autoFixError} fixingItem={fixingItem} fixedItems={fixedItems} fixSingleItem={fixSingleItem} optimizeSite={optimizeSite} />}

            {/* Waterfall */}
            {tab === 'waterfall' && <WaterfallTab result={result} card={card} isOfflinePreview={isOfflinePreview} autoFixing={autoFixing} autoFixResult={autoFixResult} autoFixError={autoFixError} fixingItem={fixingItem} fixedItems={fixedItems} fixSingleItem={fixSingleItem} optimizeSite={optimizeSite} />}

            {/* Filmstrip */}
            {tab === 'filmstrip' && <FilmstripTab result={result} card={card} isOfflinePreview={isOfflinePreview} autoFixing={autoFixing} autoFixResult={autoFixResult} autoFixError={autoFixError} fixingItem={fixingItem} fixedItems={fixedItems} fixSingleItem={fixSingleItem} optimizeSite={optimizeSite} />}

            {/* RUM */}
            {tab === 'rum' && <RumTab result={result} card={card} isOfflinePreview={isOfflinePreview} autoFixing={autoFixing} autoFixResult={autoFixResult} autoFixError={autoFixError} fixingItem={fixingItem} fixedItems={fixedItems} fixSingleItem={fixSingleItem} optimizeSite={optimizeSite} />}

            {/* Causality */}
            {tab === 'causality' && <CausalityTab result={result} card={card} isOfflinePreview={isOfflinePreview} autoFixing={autoFixing} autoFixResult={autoFixResult} autoFixError={autoFixError} fixingItem={fixingItem} fixedItems={fixedItems} fixSingleItem={fixSingleItem} optimizeSite={optimizeSite} />}

            {/* Synthetic Agents */}
            {tab === 'agents' && <AgentsTab result={result} card={card} isOfflinePreview={isOfflinePreview} autoFixing={autoFixing} autoFixResult={autoFixResult} autoFixError={autoFixError} fixingItem={fixingItem} fixedItems={fixedItems} fixSingleItem={fixSingleItem} optimizeSite={optimizeSite} />}

            {/* Prediction */}
            {tab === 'prediction' && <PredictionTab result={result} card={card} isOfflinePreview={isOfflinePreview} autoFixing={autoFixing} autoFixResult={autoFixResult} autoFixError={autoFixError} fixingItem={fixingItem} fixedItems={fixedItems} fixSingleItem={fixSingleItem} optimizeSite={optimizeSite} />}

            {/* Global */}
