'use client';

import { useEffect, useRef, useState } from 'react';
import { apiGet, DEFAULT_TENANT_ID } from '../../lib/platform-api';

// ÔöÇÔöÇ Types ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

interface SeoModule {
  key: string;
  display_name: string;
  group: string;
  description: string;
  route_path: string;
  badge?: string;
  implemented: boolean;
  backend_ready: boolean;
  frontend_ready: boolean;
  database_ready: boolean;
  integrations: string[];
}

interface ModulesResponse {
  total: number;
  implemented: number;
  modules: SeoModule[];
  groups: { group: string; items: SeoModule[] }[];
}

interface SlaData {
  compliance_pct: number;
  status: 'green' | 'amber' | 'red';
  uptime_seconds: number;
  breached_paths: string[];
}

interface IntelData {
  health_score: number;
  health_grade: string;
  sla_status: string;
  sla_compliance_pct: number;
  model_count: number;
  anomalies: { latency_spikes: unknown[]; high_retry_jobs: number; recovery_queue_depth: number };
  governance: { lineage_events: number; active_prompt_versions: number };
  ranked_actions: { priority: string; area: string; action: string }[];
  retrieved_at: string;
}

interface MetricsData {
  uptime_seconds: number;
  latency: { path_count: number; sample_count: number };
  sla: SlaData;
  models: { count: number; providers: string[] };
}

// ÔöÇÔöÇ Constants ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

const GROUP_COLORS: Record<string, string> = {
  'Search Intelligence':        '#3b82f6',
  'Experience Optimization':    '#8b5cf6',
  'Growth & Governance':        '#06b6d4',
  'Core Foundations':           '#22c55e',
  'Expansion Modules':          '#f59e0b',
  'SaaS Platform':              '#ec4899',
  'Monitoring & Observability': '#14b8a6',
  'Schema & Optimization':      '#a78bfa',
  'Content & Distribution':     '#fb923c',
  'Accessibility & Media':      '#34d399',
  'Performance & Audits':       '#f43f5e',
};

const C = {
  bg:     'var(--bg, #0f172a)',
  card:   'var(--card, #1e293b)',
  border: 'var(--line, #334155)',
  text:   'var(--text, #f1f5f9)',
  muted:  'var(--muted, #64748b)',
  green:  '#22c55e',
  amber:  '#f59e0b',
  red:    '#ef4444',
  blue:   '#3b82f6',
  purple: '#8b5cf6',
  cyan:   '#06b6d4',
};

// ÔöÇÔöÇ Helpers ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

function moduleScore(m: SeoModule): number {
  let s = 0;
  if (m.implemented)    s += 40;
  if (m.backend_ready)  s += 25;
  if (m.frontend_ready) s += 25;
  if (m.database_ready) s += 5;
  const intBonus = Math.min(5, m.integrations.length * 1);
  return Math.min(100, s + intBonus);
}

function gradeColor(g: string) {
  if (g === 'A+' || g === 'A') return C.green;
  if (g === 'B') return C.cyan;
  if (g === 'C') return C.amber;
  return C.red;
}

function statusColor(s: string) {
  if (s === 'green') return C.green;
  if (s === 'amber') return C.amber;
  return C.red;
}

function priorityColor(p: string) {
  if (p === 'high')   return C.red;
  if (p === 'medium') return C.amber;
  return C.cyan;
}

function fmtUptime(sec: number) {
  const h = Math.floor(sec / 3600);
  const m = Math.floor((sec % 3600) / 60);
  return `${h}h ${m}m`;
}

// ÔöÇÔöÇ Components ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

function BigRing({ score, grade, label }: { score: number; grade: string; label: string }) {
  const r = 58;
  const circ = 2 * Math.PI * r;
  const dash = (score / 100) * circ;
  const color = gradeColor(grade);
  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 10 }}>
      <svg width={148} height={148} viewBox="0 0 148 148">
        <defs>
          <linearGradient id="big-grad" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor={color} stopOpacity={0.5} />
            <stop offset="100%" stopColor={color} />
          </linearGradient>
        </defs>
        <circle cx={74} cy={74} r={r} fill="none" stroke={C.border} strokeWidth={11} />
        <circle cx={74} cy={74} r={r} fill="none" stroke="url(#big-grad)" strokeWidth={11}
          strokeDasharray={`${dash} ${circ}`} strokeLinecap="round"
          transform="rotate(-90 74 74)" style={{ transition: 'stroke-dasharray 1s ease' }} />
        <text x={74} y={66} textAnchor="middle" fill={color} fontSize={36} fontWeight={900}>{score}</text>
        <text x={74} y={86} textAnchor="middle" fill={C.muted} fontSize={14}>/100</text>
      </svg>
      <div style={{ background: color + '22', border: `2px solid ${color}`, borderRadius: 8, padding: '4px 20px', fontSize: 20, fontWeight: 800, color, letterSpacing: 3 }}>
        {grade}
      </div>
      <div style={{ fontSize: 12, color: C.muted }}>{label}</div>
    </div>
  );
}

function MiniGauge({ value, label, color }: { value: number; label: string; color: string }) {
  const pct = Math.min(100, Math.max(0, value));
  const r = 26;
  const circ = 2 * Math.PI * r;
  const dash = (pct / 100) * circ;
  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 3 }}>
      <svg width={64} height={64} viewBox="0 0 64 64">
        <circle cx={32} cy={32} r={r} fill="none" stroke={C.border} strokeWidth={6} />
        <circle cx={32} cy={32} r={r} fill="none" stroke={color} strokeWidth={6}
          strokeDasharray={`${dash} ${circ}`} strokeLinecap="round"
          transform="rotate(-90 32 32)" style={{ transition: 'stroke-dasharray 0.8s ease' }} />
        <text x={32} y={36} textAnchor="middle" fill={C.text} fontSize={12} fontWeight={700}>{Math.round(pct)}</text>
      </svg>
      <span style={{ fontSize: 10, color: C.muted, textAlign: 'center', maxWidth: 64 }}>{label}</span>
    </div>
  );
}

function StatPill({ label, value, color }: { label: string; value: string | number; color?: string }) {
  return (
    <div style={{ background: C.card, border: `1px solid ${C.border}`, borderRadius: 10, padding: '12px 16px', textAlign: 'center', minWidth: 110 }}>
      <div style={{ fontSize: 22, fontWeight: 800, color: color ?? C.text }}>{value}</div>
      <div style={{ fontSize: 10, color: C.muted, marginTop: 3, textTransform: 'uppercase', letterSpacing: 0.8 }}>{label}</div>
    </div>
  );
}

function ProgressBar({ value, color, label }: { value: number; color: string; label?: string }) {
  return (
    <div>
      {label && (
        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 4 }}>
          <span style={{ fontSize: 11, color: C.muted }}>{label}</span>
          <span style={{ fontSize: 11, fontWeight: 700, color }}>{value}%</span>
        </div>
      )}
      <div style={{ background: C.border, borderRadius: 8, height: 8, overflow: 'hidden' }}>
        <div style={{ width: `${value}%`, height: '100%', background: color, borderRadius: 8, transition: 'width 1s ease' }} />
      </div>
    </div>
  );
}

function ModuleCard({ m, globalIdx }: { m: SeoModule; globalIdx: number }) {
  const score = moduleScore(m);
  const color = GROUP_COLORS[m.group] ?? C.blue;
  const r = 22;
  const circ = 2 * Math.PI * r;
  const dash = (score / 100) * circ;

  return (
    <a href={m.route_path} style={{ textDecoration: 'none' }}>
      <div
        style={{
          background: C.card,
          border: `1px solid ${C.border}`,
          borderRadius: 12,
          padding: '14px 16px',
          display: 'flex',
          gap: 12,
          alignItems: 'flex-start',
          cursor: 'pointer',
          transition: 'border-color 0.2s',
          position: 'relative',
          overflow: 'hidden',
          height: '100%',
          boxSizing: 'border-box',
        }}
        onMouseEnter={e => { (e.currentTarget as HTMLDivElement).style.borderColor = color; }}
        onMouseLeave={e => { (e.currentTarget as HTMLDivElement).style.borderColor = C.border; }}
      >
        <div style={{ position: 'absolute', top: 8, right: 10, fontSize: 10, color: C.muted, fontWeight: 600 }}>#{globalIdx + 1}</div>

        <div style={{ flexShrink: 0 }}>
          <svg width={56} height={56} viewBox="0 0 56 56">
            <circle cx={28} cy={28} r={r} fill="none" stroke={C.border} strokeWidth={5} />
            <circle cx={28} cy={28} r={r} fill="none" stroke={color} strokeWidth={5}
              strokeDasharray={`${dash} ${circ}`} strokeLinecap="round"
              transform="rotate(-90 28 28)" />
            <text x={28} y={32} textAnchor="middle" fill={color} fontSize={12} fontWeight={800}>{score}</text>
          </svg>
        </div>

        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 6, flexWrap: 'wrap', marginBottom: 4 }}>
            <div style={{ fontSize: 13, fontWeight: 700, color: C.text, lineHeight: 1.3 }}>{m.display_name}</div>
            {m.badge && (
              <span style={{ background: color + '22', color, border: `1px solid ${color}44`, borderRadius: 4, padding: '1px 6px', fontSize: 9, fontWeight: 700 }}>{m.badge}</span>
            )}
          </div>
          <div style={{ fontSize: 11, color: C.muted, lineHeight: 1.4, marginBottom: 8,
            display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical', overflow: 'hidden' }}>
            {m.description}
          </div>
          <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap' }}>
            {([
              { label: 'Backend',  ok: m.backend_ready },
              { label: 'Frontend', ok: m.frontend_ready },
              { label: 'DB',       ok: m.database_ready },
              { label: 'AI',       ok: m.implemented },
            ] as { label: string; ok: boolean }[]).map(({ label, ok }) => (
              <span key={label} style={{
                fontSize: 9, fontWeight: 700, padding: '2px 6px', borderRadius: 4,
                background: ok ? C.green + '18' : C.red + '18',
                color: ok ? C.green : C.red,
                border: `1px solid ${ok ? C.green : C.red}33`,
              }}>{ok ? 'Ô£ô' : 'Ô£ù'} {label}</span>
            ))}
          </div>
          {m.integrations.length > 0 && (
            <div style={{ marginTop: 6, display: 'flex', gap: 4, flexWrap: 'wrap' }}>
              {m.integrations.slice(0, 4).map(i => (
                <span key={`item-${i}`} style={{ fontSize: 9, color: C.muted, background: C.border + '55', borderRadius: 4, padding: '1px 5px' }}>{i}</span>
              ))}
              {m.integrations.length > 4 && <span style={{ fontSize: 9, color: C.muted }}>+{m.integrations.length - 4}</span>}
            </div>
          )}
        </div>
      </div>
    </a>
  );
}

function computePlatformScore(modules: SeoModule[]): { score: number; grade: string } {
  if (!modules.length) return { score: 0, grade: 'D' };
  const avg = Math.round(modules.reduce((s, m) => s + moduleScore(m), 0) / modules.length);
  const grade = avg >= 95 ? 'A+' : avg >= 90 ? 'A' : avg >= 80 ? 'B' : avg >= 70 ? 'C' : 'D';
  return { score: avg, grade };
}

