            {intel.ranked_actions.map((a, i) => (
              <div key={`item-${i}`} style={{
                display: 'flex', gap: 12, padding: '10px 14px',
                background: priorityColor(a.priority) + '10',
                border: `1px solid ${priorityColor(a.priority)}33`,
