            ))}
          </div>
        </div>
      )}

      {/* Footer */}
      <div style={{ borderTop: `1px solid ${C.border}`, paddingTop: 16, display: 'flex', justifyContent: 'space-between', flexWrap: 'wrap', gap: 8 }}>
        <div style={{ fontSize: 10, color: C.muted }}>
          SEO Platform Matrix ┬À {totalModules} modules ┬À Grade {platformGrade} ┬À {platformScore}/100 ┬À DeepSeek R1 + FastAPI + Next.js + PostgreSQL + OpenSearch
        </div>
        {lastRefresh && <div style={{ fontSize: 10, color: C.muted }}>Refreshed {lastRefresh} ┬À auto 60s</div>}
      </div>
    </div>
  );
}

