  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<RagResult | null>(null);
  const [error, setError] = useState('');

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setLoading(true); setError(''); setResult(null);
    try {
      const data = await apiSend<RagResult>(
        '/seo-platform/rag-search/query', 'POST',
        { query, site_domain: siteDomain, content_corpus: contentCorpus, top_k: topK, notes },
        DEFAULT_TENANT_ID,
      );
      setResult(data);
    } catch (e) { setError(e instanceof Error ? e.message : 'Search failed'); }
    finally { setLoading(false); }
  }

  const INTENT_COLORS: Record<string, string> = {
    informational: 'bg-blue-100 text-blue-700',
    navigational: 'bg-purple-100 text-purple-700',
    transactional: 'bg-green-100 text-green-700',
    commercial: 'bg-orange-100 text-orange-700',
  };

  return (
    <div className="max-w-4xl mx-auto p-6 space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-gray-900">RAG Site Search Engine</h1>
        <p className="text-gray-500 mt-1">Semantic site search powered by retrieval and reasoning ÔÇö find answers, not just keywords.</p>
      </div>

      <form onSubmit={handleSubmit} className="bg-white rounded-xl border border-gray-200 p-6 space-y-4">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Search Query *</label>
          <input
            type="text" value={query} onChange={e => setQuery(e.target.value)} required
            placeholder="e.g. how does AI SEO improve rankings?"
            className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
        </div>
        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Site Domain (optional)</label>
            <input
              type="text" value={siteDomain} onChange={e => setSiteDomain(e.target.value)}
              placeholder="example.com"
              className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Top-K Results: {topK}</label>
            <input
              type="range" min={1} max={20} value={topK} onChange={e => setTopK(Number(e.target.value))}
              className="w-full mt-2"
            />
          </div>
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Content Corpus (optional)</label>
          <textarea value={contentCorpus} onChange={e => setContentCorpus(e.target.value)} rows={5}
            placeholder="Paste your site content, page excerpts, or sitemap data. The AI will perform semantic retrieval over this corpus to find the most relevant results."
            className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500" />
          <p className="text-xs text-gray-400 mt-1">Leave empty to get AI-generated representative results based on your domain.</p>
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Notes</label>
          <textarea value={notes} onChange={e => setNotes(e.target.value)} rows={2}
            placeholder="Search context, audience, intent..."
            className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500" />
        </div>
        <button type="submit" disabled={loading || !query}
          className="w-full bg-blue-600 text-white py-2 px-4 rounded-lg text-sm font-medium hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors">
          {loading ? 'SearchingÔÇª' : 'Run Semantic Search'}
        </button>
      </form>

      {error && <div className="bg-red-50 border border-red-200 text-red-700 rounded-lg px-4 py-3 text-sm">{error}</div>}

      {result && (
        <div className="space-y-4">
          {/* Query meta */}
          <div className="bg-white rounded-xl border border-gray-200 p-5 flex items-center gap-4">
            <div className="flex-1">
              <div className="text-sm font-medium text-gray-700 mb-1">Query: <span className="text-blue-600">"{result.query}"</span></div>
              <div className="flex items-center gap-2 flex-wrap">
                <span className={`text-xs px-2 py-0.5 rounded-full font-medium capitalize ${INTENT_COLORS[result.intent] ?? 'bg-gray-100 text-gray-600'}`}>{result.intent} intent</span>
                {result.entities_detected.map((e, i) => (
                  <span key={`item-${i}`} className="text-xs bg-gray-100 text-gray-600 px-2 py-0.5 rounded-full">{e}</span>
                ))}
              </div>
            </div>
            <div className="text-center">
              <div className={`text-2xl font-bold ${result.confidence >= 0.8 ? 'text-green-600' : result.confidence >= 0.6 ? 'text-yellow-600' : 'text-red-600'}`}>
                {Math.round(result.confidence * 100)}%
              </div>
              <div className="text-xs text-gray-500">Confidence</div>
            </div>
          </div>

          {/* Answer Synthesis */}
          <div className="bg-blue-50 rounded-xl border border-blue-200 p-6">
            <h2 className="text-sm font-semibold text-blue-800 mb-2">Synthesized Answer</h2>
            <p className="text-sm text-blue-900 leading-relaxed">{result.answer_synthesis}</p>
          </div>

          {/* Search Results */}
          <div className="bg-white rounded-xl border border-gray-200 p-6">
            <h2 className="text-base font-semibold text-gray-800 mb-3">Search Results ({result.search_results.length})</h2>
            <div className="space-y-4">
              {result.search_results.map((r, i) => (
                <div key={`item-${i}`} className="border border-gray-100 rounded-lg p-4 hover:border-blue-200 transition-colors">
                  <div className="flex items-start justify-between gap-3">
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-1">
                        <span className="text-xs bg-blue-600 text-white rounded-full w-5 h-5 flex items-center justify-center font-bold flex-shrink-0">{r.rank}</span>
                        <span className="text-sm font-medium text-blue-700">{r.title}</span>
                      </div>
                      <div className="text-xs text-gray-400 font-mono mb-2">{r.url}</div>
                      <p className="text-sm text-gray-600">{r.snippet}</p>
                      <p className="text-xs text-gray-400 mt-1 italic">Why: {r.reasoning}</p>
                    </div>
                    <div className="text-center flex-shrink-0">
                      <div className={`text-sm font-bold ${r.relevance_score >= 0.8 ? 'text-green-600' : r.relevance_score >= 0.6 ? 'text-yellow-600' : 'text-red-500'}`}>
                        {Math.round(r.relevance_score * 100)}%
                      </div>
                      <div className="text-xs text-gray-400">relevance</div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Related Queries */}
          <div className="bg-white rounded-xl border border-gray-200 p-6">
            <h2 className="text-base font-semibold text-gray-800 mb-3">Related Queries</h2>
            <div className="flex flex-wrap gap-2">
              {result.related_queries.map((q, i) => (
                <button key={`item-${i}`} type="button" onClick={() => setQuery(q)}
                  className="text-xs bg-gray-100 hover:bg-blue-50 hover:text-blue-700 text-gray-700 px-3 py-1.5 rounded-full border border-gray-200 hover:border-blue-300 transition-colors">
                  {q}
                </button>
              ))}
            </div>
          </div>

          <p className="text-xs text-gray-400 text-right">
            Searched: {new Date(result.searched_at).toLocaleString()} ┬À ID: {result.analysis_id.slice(0, 8)}
          </p>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";

interface Theme {
  theme: string;
  sentiment: "positive" | "negative" | "neutral";
  frequency: number;
  example_quote: string;
}

interface ResponseTemplate {
  scenario: string;
  template: string;
}

interface ReviewResult {
  analysis_id: string;
  reputation_score: number;
  sentiment: { overall: string; positive_pct: number; neutral_pct: number; negative_pct: number };
  themes: Theme[];
  review_summary: { total_reviews: number; avg_rating: number; platform_breakdown: Record<string, number> };
  response_templates: ResponseTemplate[];
  reputation_risks: string[];
  quick_wins: string[];
  recommended_tools: string[];
  brand: string;
  platforms: string[];
  analyzed_at: string;
}

const PLATFORMS = ["google", "trustpilot", "yelp", "tripadvisor", "g2", "capterra"];

export default function ReviewReputationPage() {
  const [brand, setBrand] = useState("");
  const [reviewsText, setReviewsText] = useState("");
  const [platforms, setPlatforms] = useState<string[]>(["google", "trustpilot"]);
  const [notes, setNotes] = useState("");
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<ReviewResult | null>(null);
  const [error, setError] = useState("");

  function togglePlatform(p: string) {
    setPlatforms((prev) => (prev.includes(p) ? prev.filter((x) => x !== p) : [...prev, p]));
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setLoading(true);
    setError("");
    setResult(null);
    try {
      const res = await fetch("/api/fastapi/seo-platform/reviews/analyze", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ brand, reviews_text: reviewsText, platforms, notes }),
      });
      if (!res.ok) throw new Error(`Error ${res.status}: ${res.statusText}`);
      setResult(await res.json());
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : "Request failed");
    } finally {
      setLoading(false);
    }
  }

  const score = result?.reputation_score ?? 0;
  const scoreColor = score >= 80 ? "text-green-600" : score >= 60 ? "text-yellow-600" : "text-red-600";

  return (
    <div className="max-w-4xl mx-auto p-6 space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-gray-900">Review & Reputation Engine</h1>
        <p className="text-gray-500 mt-1">Review mining, sentiment analysis, and reputation response workflows.</p>
      </div>

      <form onSubmit={handleSubmit} className="bg-white rounded-xl border border-gray-200 p-6 space-y-4">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Brand Name *</label>
          <input
            type="text"
            value={brand}
            onChange={(e) => setBrand(e.target.value)}
            placeholder="e.g. Nuxtron AI"
            className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
            required
          />
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Platforms</label>
          <div className="flex flex-wrap gap-2">
            {PLATFORMS.map((p) => (
              <button
                key={p}
                type="button"
                onClick={() => togglePlatform(p)}
                className={`px-3 py-1 rounded-full text-xs font-medium border transition-colors ${
                  platforms.includes(p)
                    ? "bg-blue-600 text-white border-blue-600"
                    : "bg-white text-gray-600 border-gray-300 hover:border-blue-400"
                }`}
              >
                {p.charAt(0).toUpperCase() + p.slice(1)}
              </button>
            ))}
          </div>
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Paste Reviews (optional)</label>
          <textarea
            value={reviewsText}
            onChange={(e) => setReviewsText(e.target.value)}
            rows={6}
            placeholder={"Paste raw review text here. If left empty, AI will generate representative analysis.\n\n\"Great product, love the quality!\"\n\"Shipping was extremely slow, 2 weeks late.\"\n\"Support team resolved my issue quickly.\""}
            className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Notes</label>
          <textarea
            value={notes}
            onChange={(e) => setNotes(e.target.value)}
            rows={2}
            placeholder="Additional context..."
            className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
        </div>
        <button
          type="submit"
          disabled={loading || !brand}
          className="w-full bg-blue-600 text-white py-2 px-4 rounded-lg text-sm font-medium hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
        >
          {loading ? "Analyzing reviewsÔÇª" : "Analyze Reviews"}
        </button>
      </form>

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-700 rounded-lg px-4 py-3 text-sm">{error}</div>
      )}

      {result && (
        <div className="space-y-4">
          {/* Score + Sentiment */}
          <div className="bg-white rounded-xl border border-gray-200 p-6">
            <div className="flex items-center gap-8">
              <div className="text-center">
                <div className={`text-4xl font-bold ${scoreColor}`}>{score}</div>
                <div className="text-xs text-gray-500 mt-1">Reputation Score</div>
              </div>
              <div className="flex-1">
                <div className="flex items-center gap-2 mb-2">
                  <span className="text-sm font-medium text-gray-700">Overall Sentiment:</span>
                  <span className={`text-sm font-bold capitalize ${result.sentiment.overall === "positive" ? "text-green-600" : result.sentiment.overall === "negative" ? "text-red-600" : "text-yellow-600"}`}>
                    {result.sentiment.overall}
                  </span>
                </div>
                <div className="flex gap-2 h-4 rounded-full overflow-hidden">
                  <div className="bg-green-500" style={{ width: `${result.sentiment.positive_pct}%` }} />
                  <div className="bg-gray-300" style={{ width: `${result.sentiment.neutral_pct}%` }} />
                  <div className="bg-red-400" style={{ width: `${result.sentiment.negative_pct}%` }} />
                </div>
                <div className="flex gap-4 mt-1 text-xs text-gray-500">
                  <span className="text-green-600">Ôû▓ {result.sentiment.positive_pct}% positive</span>
                  <span className="text-gray-500">ÔùÅ {result.sentiment.neutral_pct}% neutral</span>
                  <span className="text-red-500">Ôû╝ {result.sentiment.negative_pct}% negative</span>
                </div>
              </div>
              <div className="text-center">
                <div className="text-2xl font-bold text-gray-800">{result.review_summary.avg_rating.toFixed(1)}Ôÿà</div>
                <div className="text-xs text-gray-500">{result.review_summary.total_reviews} reviews</div>
              </div>
            </div>
          </div>

          {/* Themes */}
          <div className="bg-white rounded-xl border border-gray-200 p-6">
            <h2 className="text-base font-semibold text-gray-800 mb-3">Review Themes</h2>
            <div className="space-y-3">
              {result.themes.map((t, i) => (
                <div key={`item-${i}`} className="border border-gray-100 rounded-lg p-3">
                  <div className="flex items-center justify-between mb-1">
                    <span className="text-sm font-medium text-gray-800">{t.theme}</span>
                    <div className="flex items-center gap-2">
                      <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${t.sentiment === "positive" ? "bg-green-100 text-green-700" : t.sentiment === "negative" ? "bg-red-100 text-red-700" : "bg-gray-100 text-gray-600"}`}>
                        {t.sentiment}
                      </span>
                      <span className="text-xs text-gray-500">{t.frequency} mentions</span>
                    </div>
                  </div>
                  <p className="text-xs text-gray-500 italic">"{t.example_quote}"</p>
                </div>
              ))}
            </div>
          </div>

          {/* Platform Breakdown */}
          <div className="bg-white rounded-xl border border-gray-200 p-6">
            <h2 className="text-base font-semibold text-gray-800 mb-3">Platform Breakdown</h2>
            <div className="grid grid-cols-3 gap-3">
              {Object.entries(result.review_summary.platform_breakdown).map(([platform, count]) => (
                <div key={platform} className="bg-gray-50 rounded-lg p-3 text-center">
                  <div className="text-xl font-bold text-gray-800">{count}</div>
                  <div className="text-xs text-gray-500 capitalize mt-0.5">{platform}</div>
                </div>
              ))}
            </div>
          </div>

          {/* Response Templates */}
          <div className="bg-white rounded-xl border border-gray-200 p-6">
            <h2 className="text-base font-semibold text-gray-800 mb-3">Response Templates</h2>
            <div className="space-y-3">
              {result.response_templates.map((t, i) => (
                <div key={`item-${i}`} className="border border-gray-200 rounded-lg p-3">
                  <div className="text-xs font-mono text-blue-600 mb-1">{t.scenario}</div>
                  <p className="text-sm text-gray-700">{t.template}</p>
                </div>
              ))}
            </div>
          </div>

          {/* Risks */}
          {result.reputation_risks.length > 0 && (
            <div className="bg-red-50 rounded-xl border border-red-200 p-6">
              <h2 className="text-base font-semibold text-red-800 mb-3">Reputation Risks</h2>
              <ul className="space-y-2">
                {result.reputation_risks.map((r, i) => (
                  <li key={`item-${i}`} className="flex items-start gap-2 text-sm text-red-700"><span>ÔÜá</span>{r}</li>
                ))}
              </ul>
            </div>
          )}

          {/* Quick Wins */}
          <div className="bg-green-50 rounded-xl border border-green-200 p-6">
            <h2 className="text-base font-semibold text-green-800 mb-3">Quick Wins</h2>
            <ul className="space-y-2">
              {result.quick_wins.map((w, i) => (
                <li key={`item-${i}`} className="flex items-start gap-2 text-sm text-green-700"><span className="mt-0.5">Ô£ô</span>{w}</li>
              ))}
            </ul>
          </div>

          <p className="text-xs text-gray-400 text-right">
            Analyzed: {new Date(result.analyzed_at).toLocaleString()} ┬À ID: {result.analysis_id.slice(0, 8)}
          </p>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState } from 'react';
import { apiGet, apiSend, DEFAULT_TENANT_ID } from '../../lib/platform-api';

const SCHEMA_TYPES = [
  'Article', 'FAQPage', 'HowTo', 'Product', 'LocalBusiness', 'Organization',
  'Person', 'VideoObject', 'Event', 'Recipe', 'Review', 'BreadcrumbList',
  'WebSite', 'WebPage', 'SoftwareApplication', 'Course', 'JobPosting', 'NewsArticle',
];

export default function SchemasPage() {
  const [schemaType, setSchemaType] = useState('Article');
  const [url, setUrl] = useState('');
  const [content, setContent] = useState('');
  const [result, setResult] = useState<Record<string, unknown> | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [copied, setCopied] = useState(false);

  async function generate() {
    if (!content) { setError('Content is required.'); return; }
    setLoading(true); setError('');
    try {
      const data = await apiSend<Record<string, unknown>>(
        '/seo-platform/schemas/generate', 'POST',
        { schema_type: schemaType, url, content },
        DEFAULT_TENANT_ID,
      );
      setResult(data);
    } catch (e) { setError(e instanceof Error ? e.message : 'Generation failed'); }
    finally { setLoading(false); }
  }

  function copySchema() {
    const schema = result?.schema_json ?? result;
    navigator.clipboard.writeText(JSON.stringify(schema, null, 2));
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  }

  const card = { background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 16, marginBottom: 16 };
  const inp = { width: '100%', padding: '8px 10px', borderRadius: 8, border: '1px solid var(--line)', background: 'var(--bg)', color: 'var(--text)', marginBottom: 10, boxSizing: 'border-box' as const };

  return (
    <main style={{ minHeight: '100vh', background: 'var(--bg)', color: 'var(--text)', padding: 24 }}>
      <div style={{ maxWidth: 900, margin: '0 auto' }}>
        <h1 style={{ marginTop: 0 }}>Schema Markup Generator</h1>
        <p style={{ color: 'var(--muted)' }}>Generate valid Schema.org JSON-LD for 18+ schema types to boost rich snippet eligibility.</p>
        {error && <div style={{ ...card, color: '#f87171' }}>{error}</div>}
        <section style={card}>
          <label style={{ display: 'block', fontSize: 12, fontWeight: 600, marginBottom: 4 }}>Schema Type</label>
          <select value={schemaType} onChange={e => setSchemaType(e.target.value)}
            style={{ ...inp, cursor: 'pointer' }}>
            {SCHEMA_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
          </select>
          <label style={{ display: 'block', fontSize: 12, fontWeight: 600, marginBottom: 4 }}>Page URL (optional)</label>
          <input style={inp} value={url} onChange={e => setUrl(e.target.value)} placeholder="https://your-site.com/page" />
          <label style={{ display: 'block', fontSize: 12, fontWeight: 600, marginBottom: 4 }}>Page Content</label>
          <textarea style={{ ...inp, minHeight: 140 }} value={content} onChange={e => setContent(e.target.value)} placeholder="Paste your page content here to generate accurate schema..." />
          <button onClick={generate} disabled={loading}
            style={{ padding: '8px 16px', borderRadius: 8, border: 'none', background: 'var(--brand)', color: '#00101e', fontWeight: 700, cursor: 'pointer', opacity: loading ? 0.7 : 1 }}>
            {loading ? 'GeneratingÔÇª' : `Generate ${schemaType} Schema`}
          </button>
        </section>
        {result && (
          <section style={card}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                <strong style={{ fontSize: 14 }}>Generated {result.schema_type as string} Schema JSON-LD</strong>
                {(result.schema_score as number) !== undefined && (
                  <span style={{ fontSize: 12, fontWeight: 700, padding: '3px 10px', borderRadius: 99, background: 'rgba(34,197,94,0.15)', color: '#22c55e', border: '1px solid rgba(34,197,94,0.3)' }}>
                    Score: {result.schema_score as number}/100
                  </span>
                )}
                {(result.validation as {valid?: boolean; warnings?: string[]} | undefined)?.valid !== undefined && (
                  <span style={{ fontSize: 12, fontWeight: 700, padding: '3px 10px', borderRadius: 99,
                    background: (result.validation as {valid: boolean}).valid ? 'rgba(34,197,94,0.15)' : 'rgba(239,68,68,0.15)',
                    color: (result.validation as {valid: boolean}).valid ? '#22c55e' : '#ef4444',
                    border: `1px solid ${(result.validation as {valid: boolean}).valid ? 'rgba(34,197,94,0.3)' : 'rgba(239,68,68,0.3)'}`
                  }}>
                    {(result.validation as {valid: boolean}).valid ? 'Ô£ô Valid' : 'ÔÜá Invalid'}
                  </span>
                )}
              </div>
              <button onClick={copySchema}
                style={{ padding: '5px 12px', borderRadius: 6, border: '1px solid var(--line)', background: 'var(--bg)', color: 'var(--text)', cursor: 'pointer', fontSize: 12, fontWeight: 600 }}>
                {copied ? 'Ô£ô Copied!' : 'Copy JSON-LD'}
              </button>
            </div>
            <pre style={{ background: 'var(--bg)', borderRadius: 8, padding: 14, fontSize: 12, color: 'var(--muted)', whiteSpace: 'pre-wrap', wordBreak: 'break-word', margin: 0, border: '1px solid var(--line)' }}>
              {JSON.stringify(result?.schema_json ?? result, null, 2)}
            </pre>
            {(result.validation as {warnings?: string[]} | undefined)?.warnings?.length ? (
              <div style={{ marginTop: 12 }}>
