                </div>
              ))}
            </div>
          </div>
        </section>

        <div style={{ display: 'grid', gridTemplateColumns: '1.1fr 1fr', gap: 10, marginBottom: 10 }}>
          <section style={card}>
            <h3 style={{ marginTop: 0 }}>1) Data Collection & Telemetry</h3>
            <div style={{ fontSize: 13, marginBottom: 6 }}>
              Endpoints: {collection?.telemetry.endpoints_servers_network_devices.endpoint_count ?? 0} ┬À Servers:{' '}
              {collection?.telemetry.endpoints_servers_network_devices.server_events ?? 0} ┬À Network devices:{' '}
              {collection?.telemetry.endpoints_servers_network_devices.network_events ?? 0}
