                          justifyContent: 'space-between',
                          fontSize: 13,
                          marginBottom: 8,
                        }}
                      >
                        <span style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                          <span
                            style={{
                              width: 10,
                              height: 10,
                              borderRadius: '50%',
                              background: SENTIMENT_COLORS[s],
                              display: 'inline-block',
                            }}
                          />
