            </Card>

            {/* Existing rules */}
            <Card>
              <SectionTitle>Existing Rules ({rules.length})</SectionTitle>
              {rules.length === 0 ? (
                <p style={{ color: 'var(--muted)', fontSize: 13 }}>No rules yet.</p>
              ) : (
                rules.map((r) => (
                  <div
