  "platform": "linkedin",
  "query": "brand name",
  "author_handle": "@user",
  "text": "mention content",
  "sentiment": "negative",
  "engagement_count": 150
}`}</pre>
            </div>
          </Card>
        )}

        {/* Auto-refresh indicator */}
        <div
          style={{
            marginTop: 24,
