  readonly titleAnimIn: string;
  readonly setTitleAnimIn: React.Dispatch<React.SetStateAction<string>>;
  readonly titleAnimOut: string;
  readonly setTitleAnimOut: React.Dispatch<React.SetStateAction<string>>;
  readonly titleDuration: number;
  readonly setTitleDuration: React.Dispatch<React.SetStateAction<number>>;
  readonly subtitles: SubtitleItem[];
  readonly setSubtitles: React.Dispatch<React.SetStateAction<SubtitleItem[]>>;
  readonly subtitleFormat: "srt" | "vtt";
  readonly setSubtitleFormat: React.Dispatch<React.SetStateAction<"srt" | "vtt">>;
};
function MotionPanel({ titleText, setTitleText, titlePreset, setTitlePreset, titleAnimIn, setTitleAnimIn, titleAnimOut, setTitleAnimOut, titleDuration, setTitleDuration, subtitles, setSubtitles, subtitleFormat, setSubtitleFormat }: Readonly<MotionPanelProps>) {
  return (
    <>
        <section className="advanced-panel" aria-label="Text and motion graphics">
          <div className="adv-panel-head">
            <h2 className="adv-panel-title">Text &amp; Motion Graphics</h2>
          </div>
          <div className="adv-panel-body">
            <details className="editor-accordion" open>
              <summary>Animated Titles</summary>
              <div className="editor-accordion-body fx-grid">
                <div className="transition-grid">
                  {[
                    'none',
                    'Typewriter',
                    'Slide Up',
                    'Fade In',
                    'Scale Pop',
                    'Glitch Reveal',
                    'Word by Word',
                    'Kinetic',
                  ].map((preset) => (
                    <button
                      key={preset}
                      type="button"
                      className={`transition-chip${titlePreset === preset ? ' active' : ''}`}
                      onClick={() => setTitlePreset(preset)}
                    >
                      {preset === 'none' ? 'None' : preset}
                    </button>
                  ))}
                </div>
                <label className="fx-label">
                  Title Text
                  <input
                    type="text"
                    className="captions-select"
                    value={titleText}
                    onChange={(e) => setTitleText(e.target.value)}
                    style={{ borderRadius: 10, padding: '8px 10px' }}
                  />
                </label>
                <label className="fx-label">
                  Animate In
                  <select
                    className="captions-select"
                    value={titleAnimIn}
                    onChange={(e) => setTitleAnimIn(e.target.value)}
                  >
                    {['fade', 'slide', 'scale', 'bounce', 'typewriter'].map((a) => (
                      <option key={a} value={a}>
                        {a}
                      </option>
                    ))}
                  </select>
                </label>
                <label className="fx-label">
                  Animate Out
                  <select
                    className="captions-select"
                    value={titleAnimOut}
                    onChange={(e) => setTitleAnimOut(e.target.value)}
                  >
                    {['fade', 'slide', 'scale', 'shrink'].map((a) => (
                      <option key={a} value={a}>
                        {a}
                      </option>
                    ))}
                  </select>
                </label>
                <label className="fx-label">
                  Duration <span>{titleDuration}ms</span>
                  <input
                    type="range"
                    min="500"
                    max="10000"
                    step="250"
                    value={titleDuration}
                    onChange={(e) => setTitleDuration(Number(e.target.value))}
                  />
                </label>
              </div>
            </details>

            <details className="editor-accordion" open>
              <summary>Subtitles / Captions</summary>
              <div className="editor-accordion-body fx-grid">
                <label className="fx-label">
                  Export format
                  <select
                    className="captions-select"
                    value={subtitleFormat}
                    onChange={(e) => setSubtitleFormat(e.target.value as 'srt' | 'vtt')}
                  >
                    <option value="srt">SRT</option>
                    <option value="vtt">VTT</option>
                  </select>
                </label>
                <div className="subtitle-list">
                  {subtitles.map((sub) => (
                    <div key={sub.id} className="subtitle-row">
                      <span className="subtitle-time">
                        {sub.start}s ÔÇô {sub.end}s
                      </span>
                      <input
                        type="text"
                        className="subtitle-input"
                        value={sub.text}
                        onChange={(e) => {
                          const val = e.target.value;
                          setSubtitles((ss) => ss.map((s) => (s.id === sub.id ? { ...s, text: val } : s)));
                        }}
                      />
                      <button
                        type="button"
                        className="fx-reset-btn"
                        onClick={() => setSubtitles((ss) => ss.filter((s) => s.id !== sub.id))}
                      >
                        Ô£ò
                      </button>
                    </div>
                  ))}
                  <button
                    type="button"
                    className="captions-generate-btn"
                    onClick={() => {
                      const last = subtitles[subtitles.length - 1];
                      const newStart = last ? last.end : 0;
                      setSubtitles((ss) => [
                        ...ss,
                        { id: `sub-${Date.now()}`, start: newStart, end: newStart + 4, text: 'New subtitle line' },
                      ]);
                    }}
                  >
                    + Add subtitle
                  </button>
                  <button
                    type="button"
                    className="captions-generate-btn captions-generate-btn-strong"
                    onClick={() => {
                      const content =
                        subtitleFormat === 'srt'
                          ? subtitles
                              .map((s, i) => `${i + 1}\n00:00:0${s.start},000 --> 00:00:0${s.end},000\n${s.text}`)
                              .join('\n\n')
                          : `WEBVTT\n\n${subtitles
                              .map((s) => `00:00:0${s.start}.000 --> 00:00:0${s.end}.000\n${s.text}`)
                              .join('\n\n')}`;
                      const blob = new Blob([content], { type: 'text/plain' });
                      const url = URL.createObjectURL(blob);
                      const a = document.createElement('a');
                      a.href = url;
                      a.download = `subtitles.${subtitleFormat}`;
                      a.click();
                      URL.revokeObjectURL(url);
                    }}
                  >
                    Export {subtitleFormat.toUpperCase()}
                  </button>
                </div>
              </div>
            </details>
          </div>
        </section>
    </>
  );
}

