type ScheduleCalendarPanelProps = {
  readonly setCalendarWeekStart: React.Dispatch<React.SetStateAction<Date>>;
  readonly isScheduleLoading: boolean;
  readonly loadScheduledPosts: () => Promise<void>;
  readonly scheduleError: string;
  readonly slides: Slide[];
  readonly weekDays: Date[];
  readonly weekDayKeys: string[];
  readonly timeSlots: number[];
  readonly scheduledPostsByCell: Map<string, ScheduledPost[]>;
  readonly activeDropCell: string;
  readonly onDraftCardDragStart: React.DragEventHandler<HTMLElement>;
  readonly onCellDragOver: (event: React.DragEvent<HTMLElement>, cellKey: string) => void;
  readonly onCellDragLeave: (cellKey: string) => void;
  readonly onCellDrop: (event: React.DragEvent<HTMLElement>, day: Date, hour: number) => Promise<void>;
  readonly onScheduledCardDragStart: React.DragEventHandler<HTMLElement>;
  readonly onDeleteScheduledPostClick: React.MouseEventHandler<HTMLButtonElement>;
  readonly formatCalendarDate: (date: Date, options: Intl.DateTimeFormatOptions) => string;
};
function ScheduleCalendarPanel({ setCalendarWeekStart, isScheduleLoading, loadScheduledPosts, scheduleError, slides, weekDays, weekDayKeys, timeSlots, scheduledPostsByCell, activeDropCell, onDraftCardDragStart, onCellDragOver, onCellDragLeave, onCellDrop, onScheduledCardDragStart, onDeleteScheduledPostClick, formatCalendarDate }: Readonly<ScheduleCalendarPanelProps>) {
  return (
    <>
        <section className="schedule-shell" aria-label="Content scheduling calendar">
          <div className="schedule-topbar">
            <div className="schedule-nav">
              <button
                type="button"
                className="ghost-btn"
                onClick={() => setCalendarWeekStart((current) => addDays(current, -7))}
              >
                Prev
              </button>
              <button
                type="button"
                className="ghost-btn"
                onClick={() => setCalendarWeekStart((current) => addDays(current, 7))}
              >
                Next
              </button>
              <button type="button" className="ghost-btn" onClick={() => setCalendarWeekStart(startOfWeek(new Date()))}>
                Today
              </button>
            </div>
            <h3>
              {weekDays[0] ? formatCalendarDate(weekDays[0], { month: 'short', day: 'numeric', year: 'numeric' }) : ''}{' '}
              -{' '}
              {weekDays[6] ? formatCalendarDate(weekDays[6], { month: 'short', day: 'numeric', year: 'numeric' }) : ''}
            </h3>
            <button
              type="button"
              className="ghost-btn"
              onClick={() => void loadScheduledPosts()}
              disabled={isScheduleLoading}
            >
              {isScheduleLoading ? 'Refreshing...' : 'Refresh'}
            </button>
          </div>

          {scheduleError ? <p className="publish-error">{scheduleError}</p> : null}

          <div className="schedule-body">
            <aside className="draft-lane">
              <h4>Post Queue</h4>
              <p>Drag a post into a day/time slot to schedule it.</p>
              <div className="draft-cards">
                {slides.map((slide, index) => (
                  <article
                    key={slide.id}
                    className="draft-card"
                    data-slide-index={index}
                    draggable
                    onDragStart={onDraftCardDragStart}
                  >
                    <strong>{slide.headline}</strong>
                    <span>{slide.subheadline}</span>
                  </article>
                ))}
              </div>
            </aside>

            <div className="calendar-wrap">
              <table className="calendar-table">
                <thead>
                  <tr className="calendar-header-row">
                    <th className="calendar-time-head">Time</th>
                    {weekDays.map((day) => (
                      <th key={day.toISOString()} className="calendar-day-head">
                        <strong>{formatCalendarDate(day, { weekday: 'short' })}</strong>
                        <span>{formatCalendarDate(day, { month: 'numeric', day: 'numeric' })}</span>
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody className="calendar-grid">
                  {timeSlots.map((hour) => (
                    <tr key={hour} className="calendar-row">
                      <th className="calendar-time-cell">
                        {formatCalendarDate(new Date(2000, 0, 1, hour), { hour: 'numeric' })}
                      </th>
                      {weekDays.map((day, dayIndex) => {
                        const dayKey = weekDayKeys[dayIndex] ?? toLocalDateKey(day);
                        const cellKey = `${dayKey}::${hour}`;
                        const posts = scheduledPostsByCell.get(cellKey) ?? [];
                        const isActive = activeDropCell === cellKey;

                        return (
                          <td
                            key={cellKey}
                            className={isActive ? 'calendar-drop-cell active' : 'calendar-drop-cell'}
                            onDragOver={(event) => onCellDragOver(event, cellKey)}
                            onDragLeave={() => onCellDragLeave(cellKey)}
                            onDrop={(event) => {
                              void onCellDrop(event, day, hour);
                            }}
                          >
                            {posts.map((post) => (
                              <article
                                key={post.id}
                                className="scheduled-post"
                                data-post-id={post.id}
                                draggable
                                onDragStart={onScheduledCardDragStart}
                              >
                                <strong>{post.platform.toUpperCase()}</strong>
                                <span>{post.text.slice(0, 52)}</span>
                                <button
                                  type="button"
                                  className="ghost-btn danger"
                                  data-post-id={post.id}
                                  onClick={onDeleteScheduledPostClick}
                                >
                                  Delete
                                </button>
                              </article>
                            ))}
                          </td>
                        );
                      })}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </section>
    </>
  );
}

