  function buildAdvancedCaption(seed: string, variantIndex: number) {
    const sections = seed
      .split('\n\n')
      .map((section) => section.trim())
      .filter(Boolean);

    const sectionCount = captionLength === 'Small' ? 2 : captionLength === 'Medium' ? 4 : sections.length;
    const compactSeed = sections.slice(0, Math.max(1, sectionCount)).join('\n\n');

    const objectiveLine =
      captionObjective === 'Sales'
        ? 'Built to move shoppers from attention to checkout.'
        : captionObjective === 'Awareness'
          ? 'Built to make your brand and product memorable in-feed.'
          : captionObjective === 'Engagement'
            ? 'Built to earn watch time, comments, and saves.'
            : 'Built to generate leads with product clarity and trust.';

    const tonePrefix =
      captionTone === 'Professional'
        ? 'Professional brief:'
        : captionTone === 'Funny'
          ? 'Real talk:'
          : captionTone === 'Inspirational'
            ? 'Growth update:'
            : captionTone === 'Bold'
              ? 'Big upgrade:'
              : captionTone === 'Casual'
                ? 'Quick update:'
                : 'Hot take:';

    const variantLine =
      variantIndex % 3 === 0
        ? 'Use this for product demos and launch creatives.'
        : variantIndex % 3 === 1
          ? 'Great fit for paid social testing across new audiences.'
          : 'Ideal for performance teams that iterate fast.';

    const base = [
