const defaultApiKey = '';
const defaultTenantId = process.env.NEXT_PUBLIC_DEFAULT_TENANT_ID || 'tenant-demo';

async function parseJsonBody(res: Response): Promise<AnyObject | null> {
  const bodyText = await res.text();
  if (!bodyText) {
    return null;
  }

  try {
    return JSON.parse(bodyText) as AnyObject;
  } catch {
    if (!res.ok) {
      throw new Error(`Request failed: ${res.status}`);
    }
    throw new Error('Server returned an invalid JSON response.');
  }
}

async function postJson(path: string, payload: AnyObject, _apiKey: string, tenantId: string) {
  const res = await fetch(`${proxyBaseUrl}${path}`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Tenant-Id': tenantId,
    },
    body: JSON.stringify(payload),
  });

  const data = await parseJsonBody(res);
  if (!res.ok) {
    throw new Error((data?.detail as string) || `Request failed: ${res.status}`);
  }
  return data ?? {};
}

async function getJson(path: string, _apiKey: string, tenantId: string) {
  const res = await fetch(`${proxyBaseUrl}${path}`, {
    method: 'GET',
    headers: {
      'X-Tenant-Id': tenantId,
    },
  });

  const data = await parseJsonBody(res);
  if (!res.ok) {
    throw new Error((data?.detail as string) || `Request failed: ${res.status}`);
  }
  return data ?? {};
}

async function patchJson(path: string, payload: AnyObject, _apiKey: string, tenantId: string) {
  const res = await fetch(`${proxyBaseUrl}${path}`, {
    method: 'PATCH',
    headers: {
      'Content-Type': 'application/json',
      'X-Tenant-Id': tenantId,
    },
    body: JSON.stringify(payload),
  });

  const data = await parseJsonBody(res);
  if (!res.ok) {
    throw new Error((data?.detail as string) || `Request failed: ${res.status}`);
  }
  return data ?? {};
}

async function deleteJson(path: string, _apiKey: string, tenantId: string) {
  const res = await fetch(`${proxyBaseUrl}${path}`, {
    method: 'DELETE',
    headers: {
      'X-Tenant-Id': tenantId,
