'use client';

import { useState, useRef } from 'react';
import MultimodalCreatorSuite, { type CreatorSuiteConfig } from '../../components/multimodal-creator-suite';

function toMediaType(mode: CreatorSuiteConfig['creativeMode']): 'image' | 'video' | 'voice' | 'text' {
  if (mode === 'video') return 'video';
  if (mode === 'voice') return 'voice';
  if (mode === 'text') return 'text';
  return 'image';
}

export default function SocialStudioPage() {
  const [prompt, setPrompt] = useState('');
  const [mediaType, setMediaType] = useState<'image' | 'video' | 'voice' | 'text'>('image');
  const [generating, setGenerating] = useState(false);
  const [generatingLabel, setGeneratingLabel] = useState('GeneratingÔÇª');
  const [lastError, setLastError] = useState<string | null>(null);
  const [suiteConfig, setSuiteConfig] = useState<CreatorSuiteConfig | null>(null);
  const [generated, setGenerated] = useState<
    Array<{ id: string; type: string; content: string; mediaUrl?: string; timestamp: string }>
  >([]);
  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);

  async function pollJob(jobId: string, capturedPrompt: string, capturedType: string) {
    const maxAttempts = 240; // 20 min at 5s intervals
    let attempts = 0;
    pollRef.current = setInterval(async () => {
      attempts++;
      try {
        const res = await fetch(`/api/fastapi/ai/social-studio/job/${jobId}`);
        if (!res.ok) {
          stopPolling();
          setLastError(`Job poll failed: ${res.status}`);
          setGenerating(false);
          return;
        }
        const result = await res.json();
        if (result.status === 'pending') {
          const elapsed = Math.round(attempts * 5);
          setGeneratingLabel(`Generating 4K imageÔÇª (${elapsed}s ÔÇö SDXL on CPU can take 8-20 min)`);
          return;
        }
        stopPolling();
        if (result.status === 'success') {
          setGenerated((prev) => [
            {
              id: jobId,
              type: capturedType,
              content: result.content || `Generated ${capturedType} from: ${capturedPrompt}`,
              mediaUrl: typeof result.media_url === 'string' ? result.media_url : undefined,
              timestamp: new Date().toLocaleString(),
            },
            ...prev,
          ]);
          setPrompt('');
        } else {
          setLastError(result.error || 'Generation failed.');
        }
      } catch (e) {
        console.error('Poll error:', e);
      } finally {
        if (attempts >= maxAttempts) {
          stopPolling();
          setLastError('Image generation timed out after 20 min.');
          setGenerating(false);
        }
      }
    }, 5000);
  }

  function stopPolling() {
    if (pollRef.current) {
      clearInterval(pollRef.current);
      pollRef.current = null;
    }
    setGenerating(false);
    setGeneratingLabel('GeneratingÔÇª');
  }

  async function generate() {
    if (!prompt.trim()) return;
    setGenerating(true);
    setGeneratingLabel('GeneratingÔÇª');
    setLastError(null);

    try {
      const formData = new FormData();
      formData.append('prompt', prompt);
      formData.append('media_type', mediaType);
      formData.append('creative_mode', suiteConfig?.creativeMode ?? 'single-image-silent');
      formData.append('prompt_description', suiteConfig?.promptDescription ?? '');
      formData.append('aspect_ratio', suiteConfig?.aspectRatio ?? 'Auto');
      formData.append('resolution', suiteConfig?.resolution ?? '1080p');
      formData.append('contains_real_people', String(Boolean(suiteConfig?.containsRealPeople)));
      formData.append('return_last_frame', String(Boolean(suiteConfig?.returnLastFrame)));
      formData.append('model', suiteConfig?.model ?? '');
      formData.append('seed_enabled', String(Boolean(suiteConfig?.seedEnabled)));
      formData.append('seed', suiteConfig?.seedEnabled ? suiteConfig.seedValue : '');
      formData.append('portrait_library', JSON.stringify(suiteConfig?.portrait ?? {}));

      for (const file of suiteConfig?.referenceImageFiles ?? []) {
        formData.append('reference_images', file);
      }
      for (const file of suiteConfig?.referenceVideoFiles ?? []) {
        formData.append('reference_videos', file);
      }
      for (const file of suiteConfig?.referenceAudioFiles ?? []) {
        formData.append('reference_audios', file);
      }

      const response = await fetch('/api/fastapi/ai/social-studio/generate', {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) {
        setLastError(`Generation failed with status ${response.status}.`);
        setGenerating(false);
        return;
      }

      const result = await response.json();

      // Async image job ÔÇö start polling
      if (result.status === 'pending' && result.job_id) {
        setGeneratingLabel('4K image queued ÔÇö SDXL on CPU can take 8-20 min, pollingÔÇª');
        pollJob(result.job_id, prompt, mediaType);
        return;
      }

      setGenerating(false);
      if (result.status !== 'success') {
        setLastError(result.error || 'Generation failed.');
        return;
      }
      setGenerated([
        {
          id: Date.now().toString(),
          type: mediaType,
          content: result.content || `Generated ${mediaType} from: ${prompt}`,
          mediaUrl: typeof result.media_url === 'string' ? result.media_url : undefined,
          timestamp: new Date().toLocaleString(),
        },
        ...generated,
      ]);
      setPrompt('');
    } catch (e) {
      console.error('Generation failed:', e);
      setLastError('Unable to reach AI backend.');
      setGenerating(false);
    }
  }

  function downloadAsset(item: { id: string; type: string; content: string; mediaUrl?: string }) {
    if (item.mediaUrl) {
      const link = document.createElement('a');
      link.href = item.mediaUrl;
      const ext = item.type === 'image' ? 'png' : item.type === 'video' ? 'mp4' : item.type === 'voice' ? 'wav' : 'txt';
      link.download = `asset-${item.id}.${ext}`;
      document.body.appendChild(link);
      link.click();
      link.remove();
      return;
    }

    const blob = new Blob([item.content], { type: 'text/plain;charset=utf-8' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `asset-${item.id}.txt`;
    document.body.appendChild(link);
    link.click();
    link.remove();
    URL.revokeObjectURL(link.href);
  }

  return (
    <main>
      <section className="hero">
        <p className="eyebrow">AI Social Studio</p>
        <h1>Generate Images, Videos, Voice & Copy</h1>
        <p>Prompt-based content generation with editing controls. Create on-brand assets in seconds.</p>
      </section>

      <MultimodalCreatorSuite
        moduleType="social-studio"
        onApplyConfig={(config) => {
          setSuiteConfig(config);
          setPrompt((prev) => (prev.trim() ? prev : config.promptDescription));
          setMediaType(toMediaType(config.creativeMode));
        }}
      />

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1.4fr', gap: 20, marginTop: 20 }}>
        {/* Controls Panel */}
        <section className="card" style={{ height: 'fit-content', padding: 20 }}>
          <h3 style={{ marginTop: 0 }}>Content Generator</h3>

          <div style={{ marginBottom: 12 }}>
            <label style={{ display: 'block', marginBottom: 6, fontSize: 12, fontWeight: 600 }}>Type</label>
            <select
              value={mediaType}
              onChange={(e) => setMediaType(e.target.value as any)}
              style={{
                width: '100%',
                padding: '8px 10px',
                borderRadius: 8,
                border: '1px solid var(--line)',
                background: 'var(--bg)',
                color: 'var(--text)',
              }}
            >
              <option value="image">Image</option>
              <option value="video">Video</option>
              <option value="voice">Voice</option>
              <option value="text">Copy Text</option>
            </select>
          </div>

          <div style={{ marginBottom: 12 }}>
            <label style={{ display: 'block', marginBottom: 6, fontSize: 12, fontWeight: 600 }}>Prompt</label>
            <textarea
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              placeholder={`Describe the ${mediaType} you want to generate...`}
              rows={6}
              style={{
                width: '100%',
                padding: '10px',
                borderRadius: 8,
                border: '1px solid var(--line)',
                background: 'var(--bg)',
                color: 'var(--text)',
                fontFamily: 'inherit',
                resize: 'vertical',
              }}
            />
          </div>

          <button
            onClick={() => void generate()}
            disabled={!prompt.trim() || generating}
            style={{
              width: '100%',
              padding: '10px',
              borderRadius: 8,
              border: 'none',
              background: generating ? 'var(--muted)' : 'var(--brand)',
              color: '#00101e',
              fontWeight: 700,
              cursor: generating ? 'not-allowed' : 'pointer',
              opacity: generating ? 0.6 : 1,
            }}
          >
            {generating ? generatingLabel : `Generate ${mediaType.charAt(0).toUpperCase() + mediaType.slice(1)}`}
          </button>

          {lastError ? <p style={{ marginTop: 10, fontSize: 12, color: '#ff6b6b' }}>{lastError}</p> : null}

          <div
            style={{ marginTop: 16, padding: 10, background: 'rgba(27, 199, 255, 0.1)', borderRadius: 8, fontSize: 12 }}
          >
            <strong>Tips:</strong>
            <ul style={{ margin: '8px 0 0', paddingLeft: 16 }}>
              <li>Be specific and descriptive</li>
              <li>Include style preferences (e.g., "cinematic", "minimalist")</li>
              <li>Mention mood, colors, and composition</li>
            </ul>
          </div>
        </section>

        {/* Gallery */}
        <section className="card" style={{ padding: 20 }}>
          <h3 style={{ marginTop: 0 }}>Generated Assets ({generated.length})</h3>

          {generated.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '40px 20px', color: 'var(--muted)' }}>
              <p>No assets generated yet.</p>
              <p>Try generating your first {mediaType} using the form on the left.</p>
            </div>
          ) : (
            <div style={{ display: 'grid', gap: 12 }}>
              {generated.map((item) => (
                <div
                  key={item.id}
                  style={{
                    border: '1px solid var(--line)',
                    borderRadius: 10,
                    padding: 12,
                    background: 'rgba(255, 255, 255, 0.03)',
                  }}
                >
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'start' }}>
                    <div>
                      <strong style={{ textTransform: 'uppercase', fontSize: 11, color: 'var(--muted)' }}>
                        {item.type}
                      </strong>
                      <p style={{ margin: '6px 0 4px', fontSize: 13 }}>{item.content}</p>

                      {item.type === 'image' && item.mediaUrl ? (
                        <img
                          src={item.mediaUrl}
                          alt={item.content}
                          style={{
                            width: '100%',
                            maxHeight: 220,
                            objectFit: 'contain',
                            borderRadius: 8,
                            border: '1px solid var(--line)',
                          }}
                        />
                      ) : null}

                      {item.type === 'video' && item.mediaUrl ? (
                        <video
                          src={item.mediaUrl}
                          controls
                          style={{ width: '100%', maxHeight: 260, borderRadius: 8, border: '1px solid var(--line)' }}
                        />
                      ) : null}

                      {item.type === 'voice' && item.mediaUrl ? (
                        <audio src={item.mediaUrl} controls style={{ width: '100%' }} />
                      ) : null}

                      <p style={{ margin: 0, fontSize: 11, color: 'var(--muted)' }}>{item.timestamp}</p>
                    </div>
                    <div style={{ display: 'flex', gap: 6 }}>
                      <button
                        onClick={() => downloadAsset(item)}
                        style={{
                          padding: '6px 10px',
                          borderRadius: 6,
                          border: '1px solid var(--line)',
                          background: 'transparent',
                          color: 'var(--brand)',
                          cursor: 'pointer',
                          fontSize: 12,
                        }}
                      >
                        Edit
                      </button>
                      <button
                        style={{
                          padding: '6px 10px',
                          borderRadius: 6,
                          border: '1px solid var(--line)',
                          background: 'transparent',
                          color: 'var(--text)',
                          cursor: 'pointer',
                          fontSize: 12,
                        }}
                      >
                        Download
                      </button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </section>
      </div>
    </main>
  );
}

