type EngagementTabProps = {
  readonly accounts: SocialAccount[];
  readonly inboxStats: InboxStats | null;
  readonly messages: InboxMessage[];
  readonly replyDrafts: Record<number, string>;
  readonly setReplyDrafts: React.Dispatch<React.SetStateAction<Record<number, string>>>;
  readonly engageMessage: (messageId: number) => void;
};
function EngagementTab({ accounts, inboxStats, messages, replyDrafts, setReplyDrafts, engageMessage }: Readonly<EngagementTabProps>) {
  return (
    <>
      <section className="panel-grid two-col">
        <article className="workspace-card">
          <div className="card-head">
            <div>
              <p className="card-kicker">Traction</p>
              <h2>Likes, shares, comments, and inbox stats</h2>
            </div>
          </div>
          <div className="stats-grid">
            <div className="mini-stat">
              <span>Unread</span>
              <strong>{inboxStats?.unread ?? 0}</strong>
            </div>
            <div className="mini-stat">
              <span>Reply rate</span>
              <strong>{formatPercent(inboxStats?.replyRate ?? 0)}</strong>
            </div>
            <div className="mini-stat">
              <span>Priority</span>
              <strong>{Math.round(inboxStats?.avgPriorityScore ?? 0)}</strong>
            </div>
            <div className="mini-stat">
              <span>Networks</span>
              <strong>{Object.keys(inboxStats?.byNetwork ?? {}).length}</strong>
            </div>
          </div>
        </article>
        <article className="workspace-card">
          <div className="card-head">
            <div>
              <p className="card-kicker">Single-point engagement</p>
              <h2>Unified inbox</h2>
            </div>
          </div>
          <div className="message-list">
            {messages.map((message) => (
              <article key={message.id} className="message-card">
                <div className="message-meta">
                  <strong>{message.network}</strong>
                  <span>@{message.author_handle}</span>
                  <span>{message.sentiment}</span>
                </div>
                <p>{message.text}</p>
                <div className="suggestion-row">
                  {message.suggested_replies.slice(0, 2).map((reply) => (
                    <button
                      key={reply}
                      type="button"
                      className="chip-btn"
                      onClick={() => setReplyDrafts((current) => ({ ...current, [message.id]: reply }))}
                    >
                      {reply}
                    </button>
                  ))}
                </div>
                <textarea
                  value={replyDrafts[message.id] ?? ''}
                  onChange={(event) =>
                    setReplyDrafts((current) => ({ ...current, [message.id]: event.target.value }))
                  }
                  placeholder="Reply from a single desk"
                />
                <button
                  type="button"
                  className="ghost-btn"
                  onClick={() => void engageMessage(message.id)}
                  disabled={!accounts.length}
                >
                  Send engagement
                </button>
              </article>
            ))}
            {messages.length === 0 ? (
              <p className="empty-state">Connect an account to seed the unified inbox.</p>
            ) : null}
          </div>
        </article>
      </section>
    </>
  );
}

