'use client';

import { useEffect, useState } from 'react';

type ThemeMode = 'dark' | 'light';

const STORAGE_KEY = 'nuxtron-theme';

function applyTheme(theme: ThemeMode) {
  document.documentElement.dataset.theme = theme;
  document.documentElement.style.colorScheme = theme;
}

export default function ThemeToggle() {
  const [theme, setTheme] = useState<ThemeMode>('dark');

  useEffect(() => {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (stored === 'dark' || stored === 'light') {
      setTheme(stored);
      applyTheme(stored);
      return;
    }

    const preferred = globalThis.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark';
    setTheme(preferred);
    applyTheme(preferred);
  }, []);

  function toggleTheme() {
    const nextTheme: ThemeMode = theme === 'dark' ? 'light' : 'dark';
    setTheme(nextTheme);
    localStorage.setItem(STORAGE_KEY, nextTheme);
    applyTheme(nextTheme);
  }

  return (
    <button type="button" className="theme-toggle" onClick={toggleTheme} aria-label="Toggle theme">
      {theme === 'dark' ? 'Light Mode' : 'Dark Mode'}
    </button>
  );
}

'use client';

import { useEffect, useMemo, useState } from 'react';
import { apiGet, apiPost, DEFAULT_TENANT_ID } from '../lib/api-client';
import InstitutionalAiWidgets from '../components/institutional-ai-widgets';

type Json = Record<string, unknown>;

function asNumber(v: unknown, fb = 0): number {
  return typeof v === 'number' ? v : fb;
}
function asString(v: unknown, fb = ''): string {
  return typeof v === 'string' ? v : fb;
}
function asBoolean(v: unknown, fb = false): boolean {
  return typeof v === 'boolean' ? v : fb;
}
function asArray(v: unknown): unknown[] {
  return Array.isArray(v) ? v : [];
}

const POSTURE_LABEL: Record<string, string> = {
  critical: '­ƒö┤ Critical',
  high: '­ƒƒá High',
  medium: '­ƒƒí Medium',
  low: '­ƒƒó Low',
};

export default function TrustCenterPage() {
  const [tenantId, setTenantId] = useState(DEFAULT_TENANT_ID);
  const [posture, setPosture] = useState<Json>({});
  const [incidents, setIncidents] = useState<unknown[]>([]);
  const [chains, setChains] = useState<unknown[]>([]);
  const [policies, setPolicies] = useState<unknown[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  // New incident form
  const [incTitle, setIncTitle] = useState('');
  const [incDesc, setIncDesc] = useState('');
  const [incSeverity, setIncSeverity] = useState('medium');
  const [incModule, setIncModule] = useState('ira');
  const [incMsg, setIncMsg] = useState('');

  // New approval chain form
  const [chainName, setChainName] = useState('');
  const [chainAction, setChainAction] = useState('billing_change');
  const [chainMsg, setChainMsg] = useState('');

  const postureScore = asNumber(posture.posture_score, -1);
  const openIncidents = asNumber(posture.open_incidents, 0);
  const criticalOpen = asNumber(posture.critical_open_incidents, 0);
  const activeChains = asNumber(posture.active_approval_chains, 0);
  const policyCount = asNumber(posture.policy_changes_recorded, 0);

  const postureColor = useMemo(() => {
    if (postureScore < 0) return '#888';
    if (postureScore >= 80) return '#22c55e';
    if (postureScore >= 55) return '#f59e0b';
    return '#ef4444';
  }, [postureScore]);

  async function load() {
    setLoading(true);
    setError('');
    try {
      const [postureData, incData, chainData, policyData] = await Promise.all([
        apiGet('/trust-center/posture', tenantId),
        apiGet('/trust-center/incidents', tenantId),
        apiGet('/trust-center/approval-chains', tenantId),
        apiGet('/trust-center/policies', tenantId),
      ]);
      setPosture(postureData as Json);
      setIncidents(asArray((incData as Json).incidents));
      setChains(asArray((chainData as Json).chains));
      setPolicies(asArray((policyData as Json).history));
    } catch (e) {
      setError(String(e));
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tenantId]);

  async function createIncident() {
    if (!incTitle.trim() || !incDesc.trim()) return;
    setIncMsg('');
    try {
      const res = await apiPost(
        '/trust-center/incidents',
        {
          title: incTitle,
          description: incDesc,
          severity: incSeverity,
          affected_module: incModule,
        },
        tenantId
      );
      setIncMsg(`Created incident ${asString((res as Json).incident_id)}`);
      setIncTitle('');
      setIncDesc('');
      await load();
    } catch (e) {
      setIncMsg(`Error: ${String(e)}`);
    }
  }

  async function createChain() {
    if (!chainName.trim()) return;
    setChainMsg('');
    try {
      const res = await apiPost(
        '/trust-center/approval-chains',
        {
          chain_name: chainName,
          action_type: chainAction,
          steps: [{ role: 'admin', label: 'Admin approval required' }],
          require_all: true,
        },
        tenantId
      );
      setChainMsg(`Created chain ${asString((res as Json).chain_id)}`);
      setChainName('');
      await load();
    } catch (e) {
      setChainMsg(`Error: ${String(e)}`);
    }
  }

  async function takeSnapshot() {
    try {
      await apiPost(
        '/trust-center/snapshots',
        {
          autonomy_enabled: true,
          allow_high_impact_actions: false,
          strict_policy_lock: true,
          policy_change_human_validation: false,
          active_approval_chains: activeChains,
          open_incidents: openIncidents,
          notes: 'Snapshot captured from Trust Center dashboard',
        },
        tenantId
      );
      alert('Governance snapshot captured');
    } catch (e) {
      alert(`Error: ${String(e)}`);
    }
  }

  return (
    <main>
      <section className="hero">
        <p className="eyebrow">Governance Surface</p>
        <h1>Trust Center</h1>
        <p>
          Governance posture, policy history, approval chains, and incident metrics with institutional control flows.
        </p>
      </section>

      <section className="card trust-toolbar" style={{ marginTop: 20 }}>
        <input
          value={tenantId}
          onChange={(e) => setTenantId(e.target.value)}
          placeholder="Tenant ID"
          className="trust-input"
        />
        <button onClick={load} disabled={loading} className="cta-link">
          {loading ? 'LoadingÔÇª' : 'Refresh'}
        </button>
        <button onClick={takeSnapshot} className="cta-link">
          Capture Snapshot
        </button>
      </section>

      {error && (
        <p className="muted" style={{ color: '#ef4444', marginTop: 12 }}>
          {error}
        </p>
      )}

      {postureScore >= 0 && (
        <section className="grid dashboard-kpis" style={{ marginTop: 20 }}>
          <article className="card kpi-card">
            <p className="kpi-label">Posture Score</p>
            <h3 style={{ color: postureColor }}>{postureScore}</h3>
          </article>
          <article className="card kpi-card">
            <p className="kpi-label">Open Incidents</p>
            <h3>{openIncidents}</h3>
          </article>
          <article className="card kpi-card">
            <p className="kpi-label">Critical Open</p>
            <h3>{criticalOpen}</h3>
          </article>
