'use client';

import { useState } from 'react';

type AnyObject = Record<string, unknown>;

const proxyBaseUrl = '/api/fastapi';
const defaultApiKey = '';
const defaultTenantId = process.env.NEXT_PUBLIC_DEFAULT_TENANT_ID || 'tenant-demo';

async function postJson(path: string, payload: AnyObject, apiKey: string, tenantId: string) {
  const res = await fetch(`${proxyBaseUrl}${path}`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Tenant-Id': tenantId,
    },
    body: JSON.stringify(payload),
  });
  const data = await res.json();
  if (!res.ok) throw new Error((data?.detail as string) || `Request failed: ${res.status}`);
  return data;
}

async function getJson(path: string, apiKey: string, tenantId: string) {
  const res = await fetch(`${proxyBaseUrl}${path}`, {
    method: 'GET',
    headers: { 'X-Tenant-Id': tenantId },
  });
  const data = await res.json();
  if (!res.ok) throw new Error((data?.detail as string) || `Request failed: ${res.status}`);
  return data;
}

// ÔöÇÔöÇ Small helpers ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

function Section({ title, children }: Readonly<{ title: string; children: React.ReactNode }>) {
  return (
    <section className="mb-10 rounded-xl border border-white/10 bg-white/5 p-6 backdrop-blur">
      <h2 className="mb-4 text-lg font-semibold text-purple-300">{title}</h2>
      {children}
    </section>
  );
}

function Field({
  label,
  id,
  value,
  onChange,
  placeholder,
  type = 'text',
  rows,
}: Readonly<{
  label: string;
  id: string;
  value: string;
  onChange: (v: string) => void;
  placeholder?: string;
  type?: string;
  rows?: number;
}>) {
  return (
    <div className="mb-3">
      <label htmlFor={id} className="mb-1 block text-sm text-gray-300">
        {label}
      </label>
      {rows ? (
        <textarea
          id={id}
          rows={rows}
          className="w-full rounded border border-white/20 bg-black/30 px-3 py-2 text-sm text-white"
          placeholder={placeholder}
          value={value}
          onChange={(e) => onChange(e.target.value)}
        />
      ) : (
        <input
          id={id}
          type={type}
          className="w-full rounded border border-white/20 bg-black/30 px-3 py-2 text-sm text-white"
          placeholder={placeholder}
          value={value}
          onChange={(e) => onChange(e.target.value)}
        />
      )}
    </div>
  );
}

function Btn({
  onClick,
  loading,
  children,
}: Readonly<{
  onClick: () => void;
  loading: boolean;
  children: React.ReactNode;
}>) {
  return (
    <button
      onClick={onClick}
      disabled={loading}
      className="rounded bg-purple-600 px-4 py-2 text-sm font-medium text-white hover:bg-purple-700 disabled:opacity-50"
    >
      {loading ? 'WorkingÔÇª' : children}
    </button>
  );
}

function ResultBox({ data }: Readonly<{ data: AnyObject | null }>) {
  if (!data) return null;
  return (
    <pre className="mt-4 max-h-80 overflow-auto rounded bg-black/50 p-3 text-xs text-green-300">
      {JSON.stringify(data, null, 2)}
    </pre>
  );
}

function useVSE(apiKey: string, tenantId: string) {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [result, setResult] = useState<AnyObject | null>(null);

  const run = async (fn: () => Promise<AnyObject>) => {
    setLoading(true);
    setError('');
    setResult(null);
    try {
      const data = await fn();
      setResult(data);
    } catch (e: unknown) {
      setError((e as Error).message);
    } finally {
      setLoading(false);
    }
  };

  return { loading, error, result, run };
}

